:root {
  --ink: #08070d;
  --blood: #d21f3c;
  --bone: #f2e6d8;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #050409;
}

body {
  display: grid;
  place-items: center;
  color: var(--bone);
  font-family: "DejaVu Sans Mono", "Courier New", monospace;
  background:
    radial-gradient(ellipse at 50% 45%, #24101c 0%, #0b0710 55%, #040308 100%);
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
}

/* faint blood vignette behind the screen */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 12% 18%, rgba(210, 31, 60, .10), transparent 28%),
    radial-gradient(circle at 88% 82%, rgba(210, 31, 60, .08), transparent 30%);
}

#frame {
  position: relative;
  line-height: 0;
  filter: drop-shadow(0 24px 60px rgba(0, 0, 0, .75));
  outline: 1px solid rgba(242, 230, 216, .10);
  background: #08070d;
}

canvas {
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  width: 480px;
  height: 272px;
  cursor: crosshair;
}

#scanlines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    to bottom,
    rgba(0, 0, 0, 0) 0px,
    rgba(0, 0, 0, 0) 2px,
    rgba(0, 0, 0, .16) 3px,
    rgba(0, 0, 0, .16) 4px
  );
  mix-blend-mode: multiply;
  opacity: .55;
}

#boot {
  position: fixed;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  font-size: 10px;
  letter-spacing: .28em;
  color: rgba(242, 230, 216, .5);
  pointer-events: none;
  transition: opacity .4s ease;
  text-transform: uppercase;
}

#boot.hidden { opacity: 0; }

/* touch controls, injected only on coarse-pointer devices */
#touch {
  position: fixed;
  inset: auto 0 0 0;
  display: none;
  justify-content: space-between;
  align-items: flex-end;
  padding: 16px 18px 22px;
  pointer-events: none;
  z-index: 10;
}
#touch .pad, #touch .acts { display: flex; gap: 10px; pointer-events: auto; }
#touch button {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  border: 1px solid rgba(242, 230, 216, .3);
  background: rgba(8, 7, 13, .62);
  color: var(--bone);
  font: 700 11px/1 "DejaVu Sans Mono", monospace;
  letter-spacing: .04em;
  touch-action: none;
}
#touch button:active { background: rgba(210, 31, 60, .5); }
@media (pointer: coarse) {
  #touch { display: flex; }
  #boot { bottom: 96px; }
}

export const W = 480;
export const H = 272;
export const TILE = 16;

export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const approach = (v, target, step) => {
  if (v < target) return Math.min(v + step, target);
  return Math.max(v - step, target);
};
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const randInt = (a, b) => Math.floor(rand(a, b + 1));
export const choice = (arr) => arr[Math.floor(Math.random() * arr.length)];
export const sign = (v) => (v < 0 ? -1 : 1);
export const overlap = (a, b) =>
  a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
export const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
export const formatTime = (sec) => {
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
};
export const hash = (n) => {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
};

export const PAL = {
  ink: "#08070d",
  ink2: "#100d19",
  ink3: "#1a1428",
  night: "#241a38",
  plum: "#3a1e44",
  blood: "#c3152f",
  blood2: "#ff3b52",
  blood3: "#ff7b82",
  rust: "#7e1a2c",
  bone: "#f2e6d8",
  bone2: "#cdbfae",
  steel: "#aab6cc",
  steel2: "#6d7893",
  gold: "#ffc857",
  gold2: "#b97d24",
  teal: "#49d8c6",
  teal2: "#1c7d7b",
  purple: "#8a5cff",
  skin: "#f0c49a",
  skin2: "#b98262",
  hair: "#f3c969",
  hair2: "#b28435",
  green: "#8fae5d",
  green2: "#4f6b3e",
  white: "#ffffff",
};

const MAP = {
  left: ["KeyA", "ArrowLeft"],
  right: ["KeyD", "ArrowRight"],
  up: ["KeyW", "ArrowUp"],
  down: ["KeyS", "ArrowDown"],
  jump: ["Space", "KeyZ"],
  attack: ["KeyJ", "KeyX"],
  dash: ["KeyK", "KeyC"],
  special: ["KeyL", "KeyV"],
  swap: ["KeyQ"],
  interact: ["KeyE"],
  contracts: ["Tab"],
  pause: ["Escape", "KeyP"],
  confirm: ["Enter", "NumpadEnter"],
  back: ["Escape"],
  mute: ["KeyM"],
  restart: ["KeyR"],
  menu1: ["Digit1"],
  menu2: ["Digit2"],
  menu3: ["Digit3"],
  menu4: ["Digit4"],
};

const BLOCK = new Set([
  "Space", "ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Tab", "Enter",
]);

export class Input {
  constructor() {
    this.downSet = new Set();
    this.pressedSet = new Set();
    this.releasedSet = new Set();
    this.onAction = null;
    this.anyPressed = false;

    addEventListener("keydown", (e) => {
      if (BLOCK.has(e.code)) e.preventDefault();
      if (!e.repeat) {
        this.downSet.add(e.code);
        this.pressedSet.add(e.code);
        this.anyPressed = true;
        this.onAction?.(e.code);
      }
    });
    addEventListener("keyup", (e) => {
      this.downSet.delete(e.code);
      this.releasedSet.add(e.code);
    });
    addEventListener("blur", () => this.downSet.clear());
  }

  down(action) {
    return MAP[action].some((code) => this.downSet.has(code));
  }
  pressed(action) {
    return MAP[action].some((code) => this.pressedSet.has(code));
  }
  released(action) {
    return MAP[action].some((code) => this.releasedSet.has(code));
  }
  axis() {
    let x = 0;
    if (this.down("left")) x -= 1;
    if (this.down("right")) x += 1;
    return x;
  }
  endFrame() {
    this.pressedSet.clear();
    this.releasedSet.clear();
    this.anyPressed = false;
  }
}

// Basic touch support: on-screen d-pad and action buttons write into the
// same key sets as the keyboard.
export function installTouchControls(input) {
  if (!matchMedia("(pointer: coarse)").matches) return;
  const wrap = document.createElement("div");
  wrap.id = "touch";
  wrap.innerHTML = `
    <div class="pad">
      <button data-code="KeyA">◀</button>
      <button data-code="KeyD">▶</button>
    </div>
    <div class="acts">
      <button data-code="KeyE">E</button>
      <button data-code="KeyK">K</button>
      <button data-code="KeyJ">J</button>
      <button data-code="Space">JMP</button>
    </div>`;
  document.body.appendChild(wrap);
  wrap.querySelectorAll("button").forEach((btn) => {
    const code = btn.dataset.code;
    const press = (e) => {
      e.preventDefault();
      input.downSet.add(code);
      input.pressedSet.add(code);
      input.onAction?.(code);
    };
    const release = (e) => {
      e.preventDefault();
      input.downSet.delete(code);
    };
    btn.addEventListener("pointerdown", press);
    btn.addEventListener("pointerup", release);
    btn.addEventListener("pointercancel", release);
    btn.addEventListener("pointerleave", release);
  });
}

// Tiny procedural sound engine. Everything is synthesized, so the build has
// no external assets and still has kicks, chainsaw growls and boss roars.
export class Sfx {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.musicTimer = null;
    this.step = 0;
    this.mode = "city";
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === "suspended") this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.55;
    this.master.connect(this.ctx.destination);
    this.noiseBuf = this.makeNoise(1.2);
  }

  get ok() {
    return !!this.ctx && !this.muted;
  }

  makeNoise(seconds) {
    const rate = this.ctx.sampleRate;
    const buf = this.ctx.createBuffer(1, rate * seconds, rate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    return buf;
  }

  toggle() {
    this.muted = !this.muted;
    if (this.master) this.master.gain.value = this.muted ? 0 : 0.55;
    return this.muted;
  }

  tone(freq, dur, type = "square", vol = 0.12, slide = 0, delay = 0) {
    if (!this.ok) return;
    const t = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(this.master);
    o.start(t);
    o.stop(t + dur + 0.02);
  }

  noise(dur = 0.15, vol = 0.18, filter = 1200, delay = 0, type = "lowpass", sweep = 0) {
    if (!this.ok) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(filter, t);
    if (sweep) f.frequency.exponentialRampToValueAtTime(Math.max(80, filter + sweep), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  jump() { this.tone(240, 0.12, "square", 0.05, 160); }
  doubleJump() { this.tone(330, 0.16, "triangle", 0.06, 240); }
  slash() {
    this.noise(0.08, 0.1, 2200, 0, "bandpass", -1200);
    this.tone(130, 0.07, "sawtooth", 0.05, -60);
  }
  rev() {
    this.tone(70, 0.28, "sawtooth", 0.09, 90);
    this.noise(0.25, 0.06, 500, 0, "lowpass", 500);
  }
  shotgun() {
    this.noise(0.22, 0.28, 1700, 0, "lowpass", -1500);
    this.tone(70, 0.2, "square", 0.12, -40);
  }
  hit() {
    this.noise(0.07, 0.16, 1700, 0, "bandpass", -900);
    this.tone(180, 0.05, "square", 0.07, -90);
  }
  hurt() {
    this.noise(0.24, 0.2, 900, 0, "lowpass", -650);
    this.tone(120, 0.28, "sawtooth", 0.1, -70);
  }
  pickup() { this.tone(740, 0.06, "triangle", 0.05, 240); this.tone(1110, 0.09, "triangle", 0.035, 180, 0.045); }
  dash() { this.noise(0.18, 0.14, 2800, 0, "bandpass", -2200); this.tone(200, 0.1, "sawtooth", 0.04, 120); }
  coin() { this.tone(980, 0.06, "square", 0.04, 0); this.tone(1320, 0.1, "square", 0.03, 0, 0.04); }
  contract() {
    [196, 247, 294, 392].forEach((f, i) => this.tone(f, 0.55, "triangle", 0.055, 0, i * 0.08));
    this.noise(0.5, 0.05, 500, 0, "lowpass", 900);
  }
  deny() { this.tone(110, 0.18, "square", 0.08, -40); this.tone(105, 0.2, "square", 0.06, -30, 0.1); }
  checkpoint() {
    [392, 523, 659].forEach((f, i) => this.tone(f, 0.4, "sine", 0.05, 0, i * 0.09));
  }
  death() {
    this.tone(220, 0.9, "sawtooth", 0.11, -170);
    this.noise(0.9, 0.14, 800, 0, "lowpass", -600);
  }
  bossRoar() {
    this.tone(52, 1.2, "sawtooth", 0.16, 24);
    this.tone(78, 1.0, "square", 0.08, -22, 0.08);
    this.noise(1.1, 0.12, 380, 0, "lowpass", 500);
  }
  win() {
    [262, 330, 392, 523, 659].forEach((f, i) => this.tone(f, 0.8, "triangle", 0.07, 0, i * 0.13));
  }
  click() { this.tone(520, 0.05, "square", 0.035, 80); }
  beam() {
    this.tone(90, 0.55, "sawtooth", 0.12, 30);
    this.noise(0.5, 0.12, 2400, 0, "bandpass", -1000);
  }

  startMusic(mode = "city") {
    this.init();
    this.mode = mode;
    if (this.musicTimer) return;
    this.step = 0;
    this.musicTimer = setInterval(() => this.tick(), 250);
  }

  tick() {
    if (!this.ok || !this.ctx) return;
    this.step = (this.step + 1) % 32;
    const s = this.step;
    const boss = this.mode === "boss";
    const root = boss ? 55 : 49; // A1 / G1-ish
    const pattern = boss
      ? [0, 0, 3, 0, 5, 3, 0, -2]
      : [0, 0, 7, 0, 3, 0, 5, 3];
    if (s % 2 === 0) {
      const semi = pattern[(s / 2) % pattern.length];
      const f = root * Math.pow(2, semi / 12);
      this.tone(f, boss ? 0.22 : 0.3, "triangle", boss ? 0.06 : 0.045);
    }
    if (boss && s % 4 === 0) this.tone(root * 2, 0.1, "square", 0.025, 0);
    if (!boss && s % 8 === 4) this.tone(root * 4, 0.5, "sine", 0.02, 12);
  }

  setMusic(mode) {
    this.mode = mode;
  }
}

import { PAL, clamp } from "./util.js";

const px = (ctx, x, y, w, h, c) => {
  ctx.fillStyle = c;
  ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
};

export function shadow(ctx, x, y, w, alpha = 0.35) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = "#000000";
  ctx.beginPath();
  ctx.ellipse(x, y, w / 2, 2.2, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function outlineRect(ctx, x, y, w, h, color, outline = PAL.ink) {
  px(ctx, x - 1, y - 1, w + 2, h + 2, outline);
  px(ctx, x, y, w, h, color);
}

export function drawPlayer(ctx, p, t, game) {
  const cx = Math.round(p.x + p.w / 2);
  const feet = Math.round(p.y + p.h);
  const moving = Math.abs(p.vx) > 14 && p.onGround;
  const run = moving ? Math.sin(p.animTime * 18) : 0;
  const bob = moving ? Math.abs(Math.sin(p.animTime * 18)) * -1 : Math.sin(t * 3.2) * 0.5;
  const dashLean = p.dashTimer > 0 ? 3 : 0;
  const hurt = p.invuln > 0 && Math.floor(t * 24) % 2 === 0;

  shadow(ctx, cx, feet + 1, 16, 0.4);
  ctx.save();
  ctx.translate(cx, feet);
  if (p.facing < 0) ctx.scale(-1, 1);
  ctx.translate(0, bob);
  if (dashLean) ctx.translate(1, 0);

  const suit = hurt ? PAL.white : "#17121f";
  const suit2 = hurt ? PAL.bone : "#241b30";
  const skin = hurt ? PAL.white : PAL.skin;
  const hair = hurt ? PAL.white : PAL.hair;

  // legs
  if (!p.onGround) {
    px(ctx, -4, -7, 3, 6, suit);
    px(ctx, 2, -5, 3, 5, suit);
    px(ctx, -4, -2, 4, 2, PAL.ink);
    px(ctx, 2, -1, 4, 2, PAL.ink);
  } else if (moving) {
    px(ctx, -5 + run * 2, -6, 3, 6, suit);
    px(ctx, 2 - run * 2, -6, 3, 6, suit);
    px(ctx, -6 + run * 2, -1, 5, 2, PAL.ink);
    px(ctx, 1 - run * 2, -1, 5, 2, PAL.ink);
  } else {
    px(ctx, -4, -6, 3, 6, suit);
    px(ctx, 1, -6, 3, 6, suit);
    px(ctx, -5, -1, 4, 2, PAL.ink);
    px(ctx, 1, -1, 5, 2, PAL.ink);
  }

  // torso / suit
  outlineRect(ctx, -5, -15, 10, 10, suit, PAL.ink);
  px(ctx, -5, -14, 1, 7, suit2);
  // shirt + tie
  px(ctx, -2, -14, 4, 5, PAL.bone);
  px(ctx, 0, -14, 1, 6, PAL.blood);
  px(ctx, 1, -13, 1, 3, PAL.blood);
  // lapels
  px(ctx, -3, -14, 1, 3, PAL.bone2);
  px(ctx, 2, -14, 1, 3, PAL.bone2);
  // belt
  px(ctx, -5, -7, 10, 1, PAL.ink);
  px(ctx, -1, -7, 2, 1, PAL.gold);

  // arms
  px(ctx, -7, -14, 2, 6, suit);
  px(ctx, 5, -14, 2, 6, suit);
  px(ctx, -7, -9, 2, 2, skin);
  px(ctx, 5, -9, 2, 2, skin);

  // head
  outlineRect(ctx, -4, -21, 8, 7, skin, PAL.ink);
  // face details
  px(ctx, 1, -19, 1, 1, PAL.ink);
  px(ctx, -2, -19, 1, 1, PAL.ink);
  px(ctx, 2, -17, 1, 1, PAL.rust);
  // messy blonde hair
  px(ctx, -5, -22, 10, 4, hair);
  px(ctx, -5, -20, 2, 2, hair);
  px(ctx, 4, -21, 2, 3, hair);
  px(ctx, -4, -23, 2, 2, hair);
  px(ctx, 0, -24, 2, 2, hair);
  px(ctx, 3, -23, 2, 2, hair);
  px(ctx, -5, -18, 1, 2, hair);
  px(ctx, 4, -18, 1, 1, hair);
  px(ctx, -3, -22, 2, 1, PAL.hair2);

  // weapon in hand when idle
  if (p.attackTimer <= 0) {
    if (p.weapon === "shotgun") {
      px(ctx, 4, -11, 9, 2, PAL.ink);
      px(ctx, 5, -11, 7, 1, PAL.steel2);
      px(ctx, 8, -10, 1, 2, PAL.rust);
      px(ctx, 12, -11, 2, 2, PAL.steel);
    } else if (p.weapon === "katana") {
      ctx.save();
      ctx.translate(5, -10);
      ctx.rotate(-0.35);
      px(ctx, 0, -1, 13, 2, PAL.ink);
      px(ctx, 1, -1, 11, 1, PAL.steel);
      px(ctx, 12, -1, 2, 1, PAL.white);
      px(ctx, -1, -2, 2, 3, PAL.gold2);
      ctx.restore();
    } else {
      // idle pull-cord
      px(ctx, 5, -11, 1, 4, PAL.rust);
      px(ctx, 5, -7, 2, 1, PAL.steel2);
    }
  }

  // attacks
  if (p.attackTimer > 0) {
    const prog = 1 - p.attackTimer / p.attackDur;
    drawAttack(ctx, p, prog, t);
  }

  ctx.restore();

  if (p.dashTimer > 0) {
    ctx.save();
    ctx.globalAlpha = 0.3;
    px(ctx, p.x + 2, p.y + 4, p.w - 4, p.h - 6, PAL.blood);
    ctx.restore();
  }
}

function drawAttack(ctx, p, prog, t) {
  const swing = Math.sin(prog * Math.PI);
  if (p.weapon === "chainsaw") {
    // arm + motor
    px(ctx, 5, -14, 6, 4, "#17121f");
    px(ctx, 10, -15, 5, 6, PAL.rust);
    px(ctx, 11, -14, 3, 4, PAL.blood);
    px(ctx, 9, -16, 2, 2, PAL.steel2);
    // blade
    ctx.save();
    ctx.translate(15, -12);
    ctx.rotate(-0.25 + swing * 0.55);
    px(ctx, 0, -3, 23, 6, PAL.ink);
    px(ctx, 1, -2, 21, 4, PAL.steel);
    px(ctx, 2, -2, 19, 1, PAL.white);
    for (let i = 0; i < 7; i++) {
      const x = 2 + i * 3;
      ctx.fillStyle = PAL.steel;
      ctx.beginPath();
      ctx.moveTo(x, -3);
      ctx.lineTo(x + 2, -6);
      ctx.lineTo(x + 2, -3);
      ctx.fill();
    }
    ctx.fillStyle = PAL.blood;
    px(ctx, 4, 0, 13, 1, PAL.blood);
    ctx.restore();

    // motion arcs
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = 0.55 * (1 - prog * 0.4);
    ctx.strokeStyle = PAL.blood2;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(2, -12, 24 + p.attackIndex * 3, -1.0 + prog * 0.3, 0.75 + prog * 0.3);
    ctx.stroke();
    ctx.globalAlpha *= 0.8;
    ctx.strokeStyle = PAL.white;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(2, -12, 20 + p.attackIndex * 3, -0.8, 0.55);
    ctx.stroke();
    ctx.restore();

    if (Math.random() < 0.5) {
      ctx.save();
      ctx.globalAlpha = 0.7;
      px(ctx, 24 + Math.random() * 9, -17 + Math.random() * 10, 1, 1, PAL.gold);
      ctx.restore();
    }
  } else if (p.weapon === "katana") {
    ctx.save();
    ctx.translate(4, -13);
    ctx.rotate(-1.15 + prog * 1.9);
    px(ctx, 0, -1, 28, 2, PAL.ink);
    px(ctx, 1, -1, 26, 1, PAL.steel);
    px(ctx, 24, -1, 3, 1, PAL.white);
    px(ctx, -2, -2, 3, 3, PAL.gold2);
    ctx.restore();
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = 0.65 * (1 - prog * 0.5);
    ctx.strokeStyle = PAL.bone;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(3, -12, 29, -1.0 + prog * 0.4, 0.7 + prog * 0.4);
    ctx.stroke();
    ctx.restore();
  } else if (p.weapon === "shotgun") {
    px(ctx, 4, -13, 13, 3, PAL.ink);
    px(ctx, 5, -13, 11, 1, PAL.steel2);
    px(ctx, 15, -13, 3, 3, PAL.steel);
    if (prog < 0.3) {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = 0.9 - prog * 2;
      px(ctx, 17, -15, 8, 7, PAL.gold);
      px(ctx, 20, -13, 7, 3, PAL.white);
      ctx.restore();
    }
  }
}

export function drawZombie(ctx, e, t) {
  const cx = Math.round(e.x + e.w / 2);
  const feet = Math.round(e.y + e.h);
  const walk = Math.sin(e.animTime * 9) * 1.4;
  const flash = e.flash > 0;
  shadow(ctx, cx, feet + 1, 14, 0.35);
  ctx.save();
  ctx.translate(cx + walk * 0.2, feet);
  if (e.facing < 0) ctx.scale(-1, 1);
  const skin = flash ? PAL.white : PAL.green;
  const suit = flash ? PAL.white : "#1d1a24";

  // legs
  px(ctx, -4 + walk, -6, 3, 6, suit);
  px(ctx, 2 - walk, -6, 3, 6, suit);
  px(ctx, -5 + walk, 0, 4, 1, PAL.ink);
  px(ctx, 2 - walk, 0, 4, 1, PAL.ink);

  // torso hunched
  px(ctx, -5, -14, 10, 9, PAL.ink);
  px(ctx, -4, -14, 9, 8, suit);
  px(ctx, -4, -12, 2, 2, flash ? PAL.white : PAL.blood);
  px(ctx, 2, -11, 2, 1, PAL.ink);

  // arms
  px(ctx, 4, -13, 7, 2, suit);
  px(ctx, 10, -13, 3, 2, skin);
  px(ctx, -5, -13, 2, 5, suit);

  // head
  px(ctx, -2, -20, 9, 7, PAL.ink);
  px(ctx, -1, -19, 7, 6, skin);
  px(ctx, -2, -20, 3, 2, skin);
  px(ctx, 2, -20, 4, 2, skin);
  px(ctx, 1, -18, 2, 2, PAL.ink);
  px(ctx, 5, -17, 1, 1, PAL.gold);
  px(ctx, 2, -15, 4, 1, PAL.ink);
  px(ctx, 1, -14, 1, 1, PAL.bone);
  // exposed brain
  px(ctx, -1, -22, 5, 3, flash ? PAL.white : "#d97d94");
  px(ctx, 0, -23, 2, 2, flash ? PAL.white : "#f0a6b6");
  px(ctx, 2, -22, 1, 1, PAL.blood);
  // collar tags
  px(ctx, 0, -14, 2, 1, PAL.gold2);
  ctx.restore();
}

export function drawBat(ctx, e, t) {
  const cx = Math.round(e.x + e.w / 2);
  const cy = Math.round(e.y + e.h / 2);
  const flap = Math.sin(t * 12 + e.seed) * 6;
  const flash = e.flash > 0;
  const body = flash ? PAL.white : "#2b1533";
  const wing = flash ? PAL.white : "#4a1f4e";
  ctx.save();
  ctx.translate(cx, cy);
  if (e.facing < 0) ctx.scale(-1, 1);
  // wings
  ctx.beginPath();
  ctx.moveTo(-1, -2);
  ctx.lineTo(-16, -5 - flap);
  ctx.lineTo(-12, 1 - flap * 0.5);
  ctx.lineTo(-15, 4);
  ctx.lineTo(-4, 4);
  ctx.closePath();
  ctx.fillStyle = wing;
  ctx.fill();
  ctx.strokeStyle = PAL.ink;
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(1, -2);
  ctx.lineTo(16, -5 - flap);
  ctx.lineTo(12, 1 - flap * 0.5);
  ctx.lineTo(15, 4);
  ctx.lineTo(4, 4);
  ctx.closePath();
  ctx.fillStyle = wing;
  ctx.fill();
  ctx.stroke();
  // body
  px(ctx, -4, -5, 8, 9, PAL.ink);
  px(ctx, -3, -4, 6, 7, body);
  px(ctx, -3, -6, 2, 2, body);
  px(ctx, 1, -7, 2, 3, body);
  // ears
  px(ctx, -4, -7, 2, 3, body);
  px(ctx, 2, -8, 2, 4, body);
  // eyes / fangs
  px(ctx, -2, -3, 1, 1, PAL.blood2);
  px(ctx, 2, -3, 1, 1, PAL.blood2);
  px(ctx, 0, 1, 1, 2, PAL.bone);
  px(ctx, 2, 1, 1, 2, PAL.bone);
  ctx.restore();
}

export function drawKatana(ctx, e, t) {
  const cx = Math.round(e.x + e.w / 2);
  const feet = Math.round(e.y + e.h);
  const flash = e.flash > 0;
  const telegraph = e.state === "windup";
  const dash = e.state === "dash";
  shadow(ctx, cx, feet + 1, 14, 0.4);
  ctx.save();
  ctx.translate(cx, feet);
  if (e.facing < 0) ctx.scale(-1, 1);
  if (dash) ctx.translate(2, 1);
  const suit = flash ? PAL.white : "#111019";
  const suit2 = flash ? PAL.white : "#292138";
  // legs
  if (dash) {
    px(ctx, -7, -6, 5, 3, suit);
    px(ctx, 2, -4, 5, 3, suit);
  } else {
    px(ctx, -4, -7, 3, 7, suit);
    px(ctx, 1, -7, 3, 7, suit);
  }
  px(ctx, -5, -1, 4, 2, PAL.ink);
  px(ctx, 1, -1, 5, 2, PAL.ink);
  // coat tails
  ctx.fillStyle = suit2;
  ctx.beginPath();
  ctx.moveTo(-5, -15);
  ctx.lineTo(-9, -3);
  ctx.lineTo(-4, -6);
  ctx.closePath();
  ctx.fill();
  // torso
  px(ctx, -5, -16, 10, 10, PAL.ink);
  px(ctx, -4, -15, 8, 9, suit);
  px(ctx, -1, -15, 3, 6, PAL.bone);
  px(ctx, 0, -15, 1, 6, PAL.blood);
  // arms
  px(ctx, 4, -14, 3, 6, suit);
  px(ctx, 5, -9, 2, 2, PAL.skin);
  // head - porcelain katana mask
  px(ctx, -4, -24, 9, 8, PAL.ink);
  px(ctx, -3, -23, 7, 7, flash ? PAL.white : "#d9d4c7");
  px(ctx, -2, -21, 2, 2, PAL.ink);
  px(ctx, 2, -21, 1, 2, PAL.ink);
  px(ctx, 0, -20, 1, 4, PAL.blood);
  px(ctx, -3, -24, 2, 2, PAL.blood);
  px(ctx, 3, -25, 2, 3, PAL.blood);
  // katana arm
  ctx.save();
  ctx.translate(5, -13);
  const ang = telegraph ? -1.9 : dash ? 0.05 : -0.55;
  ctx.rotate(ang);
  px(ctx, 0, -1, 27, 2, PAL.ink);
  px(ctx, 1, -1, 25, 1, telegraph ? PAL.white : PAL.steel);
  px(ctx, -2, -2, 3, 3, PAL.gold2);
  ctx.restore();
  if (telegraph) {
    ctx.save();
    ctx.globalAlpha = 0.35 + Math.sin(t * 30) * 0.2;
    ctx.globalCompositeOperation = "lighter";
    px(ctx, 2, -22, 26, 2, PAL.white);
    ctx.restore();
  }
  ctx.restore();
}

export function drawCollector(ctx, e, t) {
  const cx = Math.round(e.x + e.w / 2);
  const cy = Math.round(e.y + e.h / 2);
  const bob = Math.sin(t * 3 + e.seed) * 2;
  const flash = e.flash > 0;
  ctx.save();
  ctx.translate(cx, cy + bob);
  if (e.facing < 0) ctx.scale(-1, 1);
  // chains
  ctx.strokeStyle = flash ? PAL.white : PAL.gold2;
  ctx.lineWidth = 1;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(-8 + i * 7, -14);
    ctx.lineTo(-10 + i * 6, -26);
    ctx.stroke();
  }
  // coat body
  ctx.fillStyle = flash ? PAL.white : "#1b1623";
  ctx.beginPath();
  ctx.moveTo(-7, -10);
  ctx.lineTo(-10, 14);
  ctx.lineTo(0, 10);
  ctx.lineTo(10, 14);
  ctx.lineTo(7, -10);
  ctx.closePath();
  ctx.fill();
  // coin head
  px(ctx, -7, -24, 14, 14, PAL.ink);
  px(ctx, -6, -23, 12, 12, flash ? PAL.white : PAL.gold2);
  px(ctx, -5, -22, 10, 10, flash ? PAL.white : PAL.gold);
  px(ctx, -3, -20, 6, 5, PAL.ink);
  px(ctx, -2, -19, 2, 2, PAL.blood2);
  px(ctx, 2, -19, 1, 2, PAL.blood2);
  px(ctx, -4, -15, 8, 1, PAL.gold2);
  // ledger
  px(ctx, 7, -8, 7, 9, PAL.ink);
  px(ctx, 8, -7, 5, 7, PAL.bone2);
  px(ctx, 9, -6, 3, 1, PAL.rust);
  px(ctx, 9, -4, 3, 1, PAL.rust);
  ctx.restore();
}

export function drawBoss(ctx, b, t, player) {
  const cx = b.x + b.w / 2;
  const base = b.y + b.h;
  const bob = Math.sin(t * 2.1) * 3;
  const phase2 = b.phase === 2;
  const flash = b.flash > 0;
  const flesh = flash ? PAL.white : phase2 ? "#7c1734" : "#5c2346";
  const flesh2 = flash ? PAL.white : phase2 ? "#b32246" : "#8c3b5e";
  const dark = PAL.ink;

  // ground shadow
  shadow(ctx, cx, base + 2, 100, 0.5);

  ctx.save();
  ctx.translate(cx, base + bob);
  const squash = 1 + Math.sin(t * 2.1) * 0.025;

  // hanging chains
  ctx.strokeStyle = "#6b5a44";
  ctx.lineWidth = 1;
  for (let i = -2; i <= 2; i++) {
    ctx.beginPath();
    ctx.moveTo(i * 26, -112);
    ctx.lineTo(i * 22 + Math.sin(t + i) * 2, -84);
    ctx.stroke();
  }

  // back scales / arms
  ctx.fillStyle = flash ? PAL.white : "#2a1424";
  ctx.beginPath();
  ctx.ellipse(-48, -48, 20, 30, -0.25, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(48, -48, 20, 30, 0.25, 0, Math.PI * 2);
  ctx.fill();
  // claws
  for (const s of [-1, 1]) {
    px(ctx, s * 58 - 3, -26, 5, 12, PAL.bone2);
    px(ctx, s * 64 - 3, -30, 4, 9, PAL.bone2);
    px(ctx, s * 52 - 2, -33, 4, 8, PAL.bone2);
  }

  // main body
  ctx.fillStyle = dark;
  ctx.beginPath();
  ctx.ellipse(0, -54 * squash, 42, 54 * squash, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = flesh;
  ctx.beginPath();
  ctx.ellipse(0, -55 * squash, 38, 50 * squash, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = flesh2;
  ctx.beginPath();
  ctx.ellipse(-8, -62, 26, 34, -0.2, 0, Math.PI * 2);
  ctx.fill();

  // pulsing veins
  ctx.strokeStyle = phase2 ? "#ff4d63" : "#3c1328";
  ctx.lineWidth = 1;
  for (let i = 0; i < 5; i++) {
    const a = i * 1.27 + Math.sin(t * 1.5 + i) * 0.08;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * 6, -55 + Math.sin(a) * 8);
    ctx.quadraticCurveTo(
      Math.cos(a) * 24, -55 + Math.sin(a) * 30,
      Math.cos(a + 0.3) * 36, -55 + Math.sin(a + 0.3) * 46
    );
    ctx.stroke();
  }

  // eyes track the player
  const pxp = player ? player.x + player.w / 2 - cx : 0;
  const pyp = player ? player.y + player.h / 2 - base : -40;
  const eyes = [
    [-22, -82, 8],
    [16, -88, 10],
    [-5, -69, 6],
    [28, -67, 6],
    [-30, -63, 5],
  ];
  eyes.forEach(([ex, ey, r], i) => {
    const blink = Math.sin(t * 1.3 + i * 2.1) > 0.97 ? 0.2 : 1;
    ctx.fillStyle = flash ? PAL.white : PAL.bone;
    ctx.beginPath();
    ctx.ellipse(ex, ey, r, r * 0.66 * blink, 0, 0, Math.PI * 2);
    ctx.fill();
    if (blink > 0.5) {
      const dx = clamp(pxp / 80, -1, 1) * r * 0.35;
      const dy = clamp(pyp / 40, -1, 1) * r * 0.25;
      ctx.fillStyle = phase2 ? "#ff2038" : PAL.blood;
      ctx.beginPath();
      ctx.arc(ex + dx, ey + dy, r * 0.36, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = PAL.ink;
      ctx.beginPath();
      ctx.arc(ex + dx, ey + dy, r * 0.15, 0, Math.PI * 2);
      ctx.fill();
    }
  });

  // mouth
  const open = 6 + Math.sin(t * 3.1) * 3 + (b.state === "roar" ? 8 : 0);
  ctx.fillStyle = dark;
  ctx.beginPath();
  ctx.ellipse(2, -34, 17, open, 0.04, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#5b0d20";
  ctx.beginPath();
  ctx.ellipse(2, -33, 14, open * 0.7, 0.04, 0, Math.PI * 2);
  ctx.fill();
  for (let i = -2; i <= 2; i++) {
    px(ctx, i * 6 - 2, -34 - open * 0.55, 3, 5, PAL.bone);
    px(ctx, i * 6 - 1, -34 + open * 0.35, 2, 4, PAL.bone);
  }

  // suit collar / tie at the bottom
  px(ctx, -26, -18, 52, 12, flash ? PAL.white : "#17121f");
  px(ctx, -26, -18, 8, 7, flash ? PAL.white : "#241b30");
  px(ctx, 18, -18, 8, 7, flash ? PAL.white : "#241b30");
  px(ctx, -3, -17, 6, 4, PAL.bone);
  px(ctx, -1, -15, 2, 9, PAL.blood);

  // orbiting coins
  for (let i = 0; i < 4; i++) {
    const a = t * 0.8 + i * Math.PI / 2;
    const ox = Math.cos(a) * 58;
    const oy = -58 + Math.sin(a) * 14;
    px(ctx, ox - 3, oy - 3, 6, 6, PAL.gold2);
    px(ctx, ox - 2, oy - 2, 4, 4, PAL.gold);
    px(ctx, ox - 1, oy - 1, 1, 1, PAL.white);
  }

  // phase transition aura
  if (b.state === "phase") {
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = 0.4 + Math.sin(t * 22) * 0.2;
    ctx.strokeStyle = PAL.blood2;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, -55, 58 + Math.sin(t * 8) * 5, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();
}

