    this.banner = null;
    this.hint = null;
    this.prompt = null;
    this.menuIndex = 0;
    this.message = null;
    this.menuMessage = "";
    this.menuMessageTime = 0;
    this.bossDefeated = false;
    this.best = 0;
    try { this.best = Number(localStorage.getItem("chainsawdebt.best") || 0); } catch {}
    this.debugGod = false;
    this.frame = 0;
    this.resetRunState();
  }

  resetRunState() {
    this.blood = 0;
    this.debt = 0;
    this.kills = 0;
    this.deaths = 0;
    this.elapsed = 0;
    this.contracts = new Set();
    this.weapons = new Set(["chainsaw"]);
    this.weapon = "chainsaw";
    this.upgrades = 0;
    this.interestTimer = 20;
    this.collectorMarks = new Set();
    this.shopBought = new Set();
    this.checkpoint = { roomIndex: 0, x: 74, y: 240 };
    this.bossDefeated = false;
    this.boss = null;
    this.player = null;
    this.enemies = [];
    this.projectiles = [];
    this.pickups = [];
    this.particles = [];
    this.effects = [];
    this.texts = [];
    this.warnings = [];
    this.hint = null;
    this.banner = null;
    this.prompt = null;
    this.fade = 0;
    this.hitstop = 0;
    this.menuIndex = 0;
    this.menuMessage = "";
    this.seenHints = new Set();
  }

  startRun() {
    this.sfx.init();
    this.sfx.startMusic("city");
    this.resetRunState();
    this.mode = "play";
    this.loadRoom(0);
    this.player.hp = 5;
    this.player.maxHp = 5;
    this.setHint("A / D  MOVE      SPACE  JUMP      J  ATTACK", 8);
    this.flashScreen(0.35, PAL.bone);
    this.sfx.contract();
  }

  toTitle() {
    this.mode = "title";
    this.sfx.setMusic("city");
  }

  loadRoom(index, spawnOverride) {
    this.roomIndex = index;
    this.room = this.rooms[index];
    this.enemies = this.room.enemies.map((d) => createEnemy({ ...d }));
    this.projectiles = [];
    this.pickups = [];
    this.warnings = [];
    this.boss = null;
    if (this.room.boss && !this.bossDefeated) {
      this.boss = new Boss(this.room.width / 2, this.room.ground);
      this.boss.entered = false;
    }
    const spawn = spawnOverride || this.room.spawn;
    if (!this.player) {
      this.player = new Player(spawn.x, spawn.y);
    } else {
      this.player.x = spawn.x - this.player.w / 2;
      this.player.y = spawn.y - this.player.h;
      this.player.vx = 0;
      this.player.vy = 0;
      this.player.dead = false;
      this.player.attackTimer = 0;
      this.player.dashTimer = 0;
    }
    this.camera.x = clamp(this.player.centerX - W / 2, 0, Math.max(0, this.room.width - W));
    this.camera.y = 0;
    this.banner = {
      title: this.room.name,
      sector: this.room.sector,
      flavor: this.room.flavor,
      t: 0, dur: 3.2,
    };
    this.fade = Math.max(this.fade, 0.7);
    this.sfx.setMusic(index === 2 ? "boss" : "city");
    if (index === 2) {
      setTimeout(() => {
        if (this.mode === "play" && this.roomIndex === 2 && this.boss && !this.boss.dead) {
          this.sfx.bossRoar();
          this.shake(8, 0.8);
        }
      }, 700);
    }
    if (index === 1 && !this.seenHints.has("subway")) {
      this.seenHints.add("subway");
      this.setHint("TAB — OPEN CONTRACTS. POWER NOW. INTEREST LATER.", 7);
    }
  }

  hasContract(id) { return this.contracts.has(id); }

  setHint(text, dur = 5) {
    this.hint = { text, t: 0, dur };
  }

  update(dt) {
    this.time += dt;
    this.frame++;
    if (this.mode === "title") {
      this.titleTime += dt;
      if (this.input.pressed("confirm") || this.input.pressed("jump")) this.startRun();
      if (this.input.pressed("mute")) this.sfx.toggle();
      return;
    }

    if (this.input.pressed("mute")) {
      const muted = this.sfx.toggle();
      this.menuMessage = muted ? "SOUND OFF" : "SOUND ON";
      this.menuMessageTime = 1.2;
    }

    if (this.mode === "play") this.updateWorld(dt);
    else if (this.mode === "contracts") this.updateContracts(dt);
    else if (this.mode === "shop") this.updateShop(dt);
    else if (this.mode === "pause") {
      if (this.input.pressed("pause") || this.input.pressed("back") || this.input.pressed("confirm")) this.mode = "play";
    } else if (this.mode === "dead") {
      this.updateParticles(dt);
      this.texts = this.texts.filter((t) => { t.t += dt; return t.t < t.dur; });
      if (this.input.pressed("confirm") || this.input.pressed("restart") || this.input.pressed("jump")) this.respawn();
      if (this.input.pressed("back")) this.toTitle();
    } else if (this.mode === "win") {
      this.updateParticles(dt);
      if (this.input.pressed("confirm") || this.input.pressed("restart") || this.input.pressed("jump")) this.startRun();
      if (this.input.pressed("back")) this.toTitle();
    }

    this.updateBanner(dt);
    this.menuMessageTime = Math.max(0, this.menuMessageTime - dt);
    this.shakeTime = Math.max(0, this.shakeTime - dt);
    if (this.shakeTime <= 0) this.shakeMag = 0;
    this.flashTime = Math.max(0, this.flashTime - dt);
    this.fade = Math.max(0, this.fade - dt * 2.4);
  }

  updateBanner(dt) {
    if (this.banner) {
      this.banner.t += dt;
      if (this.banner.t > this.banner.dur) this.banner = null;
    }
    if (this.hint) {
      this.hint.t += dt;
      if (this.hint.t > this.hint.dur) this.hint = null;
    }
  }

  updateWorld(dt) {
    if (this.hitstop > 0) {
      this.hitstop = Math.max(0, this.hitstop - dt);
      this.updateParticles(dt * 0.25);
      this.texts.forEach((t) => (t.t += dt * 0.3));
      return;
    }
    this.elapsed += dt;
    const p = this.player;
    if (!p) return;

    if (this.input.pressed("contracts")) {
      this.openContracts();
      return;
    }
    if (this.input.pressed("pause")) {
      this.mode = "pause";
      return;
    }

    // weapon swap
    if (this.input.pressed("swap") && this.weapons.size > 1) {
      const list = [...this.weapons];
      const i = list.indexOf(this.player.weapon);
      this.player.weapon = list[(i + 1) % list.length];
      this.player.attackTimer = 0;
      this.sfx.click();
      this.addText(p.centerX, p.y - 8, this.player.weapon.toUpperCase(), PAL.gold, 0.8);
    }

    p.update(dt, this);

    for (const e of this.enemies) if (!e.dead) e.update(dt, this);
    this.enemies = this.enemies.filter((e) => !e.dead);

    if (this.boss && !this.boss.dead) {
      this.boss.update(dt, this);
      if (this.boss.entered === false && this.boss.state !== "intro") {
        this.boss.entered = true;
        this.banner = { title: "THE DEBT DEVIL", sector: "COLLECTOR CLASS", flavor: "It has come to collect.", t: 0, dur: 2.8 };
      }
    }

    for (const pr of this.projectiles) pr.update(dt, this);
    this.projectiles = this.projectiles.filter((pr) => !pr.dead);

    for (const pk of this.pickups) pk.update(dt, this);
    this.pickups = this.pickups.filter((pk) => !pk.dead);

    this.updateParticles(dt);
    this.updateEffects(dt);
    this.texts = this.texts.filter((t) => { t.t += dt; return t.t < t.dur; });
    this.warnings = this.warnings.filter((w) => { w.t += dt; return w.t < w.dur; });

    // hazards
    for (const hz of this.room.hazards) {
      if (overlap(p.rect, hz) && p.invuln <= 0) {
        p.hurt(1, p.centerX, this);
        p.y = hz.y - p.h - 2;
        p.vy = -310;
      }
    }

    // debt interest
    if (this.debt > 0 && this.debt < 99) {
      this.interestTimer -= dt;
      if (this.interestTimer <= 0) {
        this.interestTimer = 20;
        this.debt = Math.min(99, this.debt + 1);
        this.addText(p.centerX, p.y - 18, "INTEREST +1 DEBT", PAL.gold2, 1.5);
        this.checkCollector();
      }
    }

    // interaction
    this.prompt = this.findInteractable();
    if (this.prompt && this.input.pressed("interact")) this.interact(this.prompt);

    // camera
    const target = clamp(p.centerX - W / 2 + p.facing * 26, 0, Math.max(0, this.room.width - W));
    this.camera.x = lerp(this.camera.x, target, 1 - Math.pow(0.0008, dt));
    this.camera.y = 0;

    // tutorial beats
    if (this.roomIndex === 0 && !this.seenHints.has("intro") && this.elapsed > 1.2) {
      this.seenHints.add("intro");
    }
    if (this.roomIndex === 0 && !this.seenHints.has("altar") && p.x > 260) {
      this.seenHints.add("altar");
      this.setHint("TAB — SIGN A CONTRACT. BLOOD NOW, DEBT FOREVER.", 7);
    }
    if (this.roomIndex === 0 && !this.seenHints.has("talk") && p.x > 150 && p.x < 230) {
      this.seenHints.add("talk");
      this.setHint("E — TALK TO MAKIMA / REST AT LAMPS", 6);
    }
    if (this.roomIndex === 2 && !this.seenHints.has("boss") && this.elapsed > 2) {
      this.seenHints.add("boss");
      this.setHint("IT FLOATS. IT LIES. CUT IT DOWN.", 6);
    }
  }

  updateContracts(dt) {
    const items = CONTRACTS;
    if (this.input.pressed("back") || this.input.pressed("contracts")) { this.mode = "play"; return; }
    if (this.input.pressed("up")) { this.menuIndex = (this.menuIndex - 1 + items.length) % items.length; this.sfx.click(); }
    if (this.input.pressed("down")) { this.menuIndex = (this.menuIndex + 1) % items.length; this.sfx.click(); }
    if (this.input.pressed("confirm") || this.input.pressed("interact") || this.input.pressed("attack")) {
      this.signContract(items[this.menuIndex]);
    }
    this.updateParticles(dt * 0.4);
  }

  signContract(item) {
    if (this.contracts.has(item.id)) {
      this.menuMessage = "ALREADY SIGNED.";
      this.menuMessageTime = 1.4;
      this.sfx.deny();
      return;
    }
    if (this.blood < item.cost) {
      this.menuMessage = `NOT ENOUGH BLOOD — NEED ${item.cost}`;
      this.menuMessageTime = 1.6;
      this.sfx.deny();
      this.shake(2, 0.12);
      return;
    }
    this.blood -= item.cost;
    this.debt = Math.min(99, this.debt + item.debt);
    this.contracts.add(item.id);
    if (item.id === "katana") {
      this.weapons.add("katana");
      this.player.weapon = "katana";
    }
    this.sfx.contract();
    this.flashScreen(0.35, PAL.blood);
    this.shake(4, 0.3);
    this.spawnBlood(this.player.centerX, this.player.centerY, 20, PAL.blood2);
    this.menuMessage = `${item.name} SIGNED. DEBT +${item.debt}.`;
    this.menuMessageTime = 2;
    this.checkCollector();
  }

  openContracts() {
    this.mode = "contracts";
    this.menuIndex = 0;
    this.menuMessage = "";
    this.sfx.click();
  }

  updateShop(dt) {
    const items = SHOP_ITEMS;
    if (this.input.pressed("back") || this.input.pressed("interact")) { this.mode = "play"; return; }
    if (this.input.pressed("up")) { this.menuIndex = (this.menuIndex - 1 + items.length) % items.length; this.sfx.click(); }
    if (this.input.pressed("down")) { this.menuIndex = (this.menuIndex + 1) % items.length; this.sfx.click(); }
    if (this.input.pressed("confirm") || this.input.pressed("attack")) this.buy(items[this.menuIndex]);
    this.updateParticles(dt * 0.4);
  }

  buy(item) {
    const sold = !item.repeat && this.shopBought.has(item.id);
    if (sold) {
      this.menuMessage = "SOLD OUT.";
      this.menuMessageTime = 1.2;
      this.sfx.deny();
      return;
    }
    if (item.id === "heal" && this.player.hp >= this.player.maxHp) {
      this.menuMessage = "YOU'RE ALREADY STITCHED.";
      this.menuMessageTime = 1.4;
      this.sfx.deny();
      return;
    }
    if (item.id === "debt" && this.debt <= 0) {
      this.menuMessage = "NO DEBT. SUSPICIOUS.";
      this.menuMessageTime = 1.4;
      this.sfx.deny();
      return;
    }
    if (this.blood < item.cost) {
      this.menuMessage = `NOT ENOUGH BLOOD — NEED ${item.cost}`;
      this.menuMessageTime = 1.5;
      this.sfx.deny();
      return;
    }
    this.blood -= item.cost;
    if (!item.repeat) this.shopBought.add(item.id);
    if (item.id === "shotgun") {
      this.weapons.add("shotgun");
      this.player.weapon = "shotgun";
      this.player.ammo = 6;
    } else if (item.id === "heart") {
      this.player.maxHp++;
      this.player.hp = this.player.maxHp;
    } else if (item.id === "tune") {
      this.upgrades++;
    } else if (item.id === "debt") {
      this.debt = Math.max(0, this.debt - 10);
    } else if (item.id === "heal") {
      this.player.heal(2);
    }
    this.sfx.coin();
    this.sfx.pickup();
    this.menuMessage = `${item.name} — DONE.`;
    this.menuMessageTime = 1.8;
    this.spawnSpark(this.player.centerX, this.player.centerY, 8);
  }

  findInteractable() {
    const p = this.player;
    const px = p.centerX;
    let best = null;
    let bestD = 30;
    for (const cp of this.room.checkpoints) {
      const d = Math.abs(px - cp.x) + Math.abs(p.y + p.h - cp.y) * 0.35;
      if (d < bestD) { best = { type: "checkpoint", x: cp.x, y: cp.y, label: "REST  [E]" }; bestD = d; }
    }
    for (const a of this.room.altars) {
      const d = Math.abs(px - a.x) + Math.abs(p.y + p.h - a.y) * 0.35;
      if (d < bestD) { best = { type: "altar", x: a.x, y: a.y, label: "DEVIL CONTRACTS  [E]" }; bestD = d; }
    }
    for (const n of this.room.npcs) {
      const d = Math.abs(px - n.x) + Math.abs(p.y + p.h - n.y) * 0.35;
      if (d < bestD) { best = { type: "npc", x: n.x, y: n.y, label: "MAKIMA  [E]" }; bestD = d; }
    }
    for (const door of this.room.doors) {
      const d = Math.abs(px - door.x) + Math.abs(p.y + p.h - door.y) * 0.35;
      if (d < bestD) { best = { type: "door", x: door.x, y: door.y, to: door.to, label: `${door.label}  [E]` }; bestD = d; }
    }
    return best;
  }

  interact(it) {
    if (it.type === "checkpoint") {
      this.checkpoint = { roomIndex: this.roomIndex, x: it.x, y: it.y };
      this.player.heal(this.player.maxHp);
      this.sfx.checkpoint();
      this.spawnSpark(it.x, it.y - 30, 14);
      this.addText(it.x, it.y - 44, "CHECKPOINT", PAL.gold, 1.4);
      if (this.room.boss && !this.bossDefeated) {
        this.boss = new Boss(this.room.width / 2, this.room.ground);
      }
      this.enemies = this.room.enemies.map((d) => createEnemy({ ...d }));
      this.fade = 0.25;
    } else if (it.type === "altar") {
      this.openContracts();
    } else if (it.type === "npc") {
      this.mode = "shop";
      this.menuIndex = 0;
      this.menuMessage = "";
      this.sfx.click();
    } else if (it.type === "door") {
      this.fade = 0.8;
      this.loadRoom(it.to);
    }
  }

  updateParticles(dt) {
    for (const p of this.particles) {
      p.life -= dt;
      p.vy += (p.gravity || 0) * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      if (p.type === "dust") p.vx *= 0.96;
    }
    this.particles = this.particles.filter((p) => p.life > 0);
    if (this.particles.length > 420) this.particles.splice(0, this.particles.length - 420);
  }

  updateEffects(dt) {
    for (const e of this.effects) e.t += dt;
    this.effects = this.effects.filter((e) => e.t < e.dur);
  }

  spawnParticle(x, y, vx, vy, life, color, size = 1, gravity = 0, type = "blood") {
    this.particles.push({ x, y, vx, vy, life, maxLife: life, color, size, gravity, type });
  }

  spawnBlood(x, y, n = 8, color = PAL.blood) {
    for (let i = 0; i < n; i++) {
      const a = rand(0, Math.PI * 2);
      const s = rand(30, 170);
      this.spawnParticle(
        x + rand(-4, 4), y + rand(-4, 4),
        Math.cos(a) * s, Math.sin(a) * s - 50,
        rand(0.3, 0.85), Math.random() < 0.25 ? PAL.blood2 : color,
        randInt(1, 2), 620, "blood"
      );
    }
  }

  spawnSpark(x, y, n = 5) {
    for (let i = 0; i < n; i++) {
      const a = rand(0, Math.PI * 2);
      const s = rand(30, 130);
      this.spawnParticle(x, y, Math.cos(a) * s, Math.sin(a) * s, rand(0.12, 0.35), Math.random() < 0.5 ? PAL.gold : PAL.bone, 1, 180, "spark");
    }
  }

  spawnDust(x, y, n = 6) {
    for (let i = 0; i < n; i++) {
      this.spawnParticle(
        x + rand(-6, 6), y - rand(0, 4),
        rand(-40, 40), rand(-60, -10),
        rand(0.25, 0.6), PAL.bone2, randInt(1, 2), -10, "dust"
      );
    }
  }

  addText(x, y, text, color = PAL.bone, dur = 0.8, size = 1) {
    this.texts.push({ x, y, text, color, t: 0, dur, size });
  }

  addEffect(e) {
    e.t = e.t || 0;
    e.dur = e.dur || 0.3;
    this.effects.push(e);
  }

  spawnWarning(x, y, w, h, dur, type = "coin") {
    this.warnings.push({ x, y, w, h, t: 0, dur, type });
  }

  shake(mag, time) {
    this.shakeMag = Math.max(this.shakeMag, mag);
    this.shakeTime = Math.max(this.shakeTime, time);
  }

  flashScreen(time, color = PAL.white) {
    this.flashTime = time;
    this.flashColor = color;
  }

  meleeHit(player) {
    const weapon = player.weapon;
    if (weapon === "shotgun") return;
    const heavy = player.attackIndex === 2;
    let range = weapon === "katana" ? 43 : 31 + player.attackIndex * 3;
    if (heavy) range += 4;
    let damage = weapon === "katana"
      ? (heavy ? 26 : 17)
      : (heavy ? 16 : 9);
    damage += this.upgrades * 5;
    const box = {
      x: player.facing > 0 ? player.x + player.w - 2 : player.x - range + 2,
      y: player.y + 1,
      w: range,
      h: 19,
    };
    let hits = 0;
    for (const e of this.enemies) {
      if (e.dead || !overlap(box, e.rect)) continue;
      e.hurt(damage, this, player.facing);
      hits++;
    }
    if (this.boss && !this.boss.dead && overlap(box, this.boss.rect)) {
      this.boss.hurt(damage, this);
      hits++;
    }
    for (const pr of this.projectiles) {
      if (!pr.friendly && overlap(box, pr.rect)) {
        pr.dead = true;
        this.spawnSpark(pr.x, pr.y, 3);
      }
    }
    if (hits) {
      this.sfx.hit();
      this.hitstop = 0.045;
      this.shake(weapon === "katana" ? 3 : 2, 0.1);
      this.spawnSpark(box.x + box.w * 0.6, box.y + 8, 3);
    }
  }

  fireShotgun(player) {
    const x = player.centerX + player.facing * 10;
    const y = player.y + 9;
    for (let i = -1; i <= 1; i++) {
      this.projectiles.push(new Projectile({
        x, y: y + i * 1.5,
        vx: player.facing * 430,
        vy: i * 26,
        type: "pellet", friendly: true, life: 0.5,
      }));
    }
    for (let i = 0; i < 8; i++) {
      this.spawnParticle(
        x, y,
        player.facing * rand(60, 220), rand(-60, 60),
        rand(0.08, 0.22), Math.random() < 0.5 ? PAL.gold : PAL.white,
        1, 0, "spark"
      );
    }
    this.addEffect({ type: "muzzle", x, y, facing: player.facing, t: 0, dur: 0.1 });
  }

  slashWave(player) {
    if (player.attackIndex !== 2) return;
    this.projectiles.push(new Projectile({
      x: player.centerX + player.facing * 16,
      y: player.y + 2,
      vx: player.facing * 300,
      vy: 0,
      type: "wave", friendly: true, life: 0.55,
    }));
   }

  foxBite(player) {
    const cx = player.centerX + player.facing * 48;
    const cy = player.y + 6;
    this.addEffect({ type: "fox", x: cx, y: cy, facing: player.facing, t: 0, dur: 0.55 });
    const box = {
      x: player.facing > 0 ? player.centerX : player.centerX - 96,
      y: player.y - 34,
      w: 96,
      h: 90,
    };
    for (const e of this.enemies) {
      if (!e.dead && overlap(box, e.rect)) e.hurt(55 + this.upgrades * 4, this, player.facing);
    }
    if (this.boss && !this.boss.dead && overlap(box, this.boss.rect)) {
      this.boss.hurt(60 + this.upgrades * 4, this);
    }
    for (let i = 0; i < 26; i++) {
      this.spawnParticle(cx + rand(-50, 50), cy + rand(-20, 40), rand(-90, 90), rand(-150, 60), rand(0.2, 0.7), Math.random() < 0.5 ? PAL.blood : PAL.bone, randInt(1, 2), 500);
    }
    this.hitstop = 0.08;
  }

  spawnProjectile(o) {
    this.projectiles.push(new Projectile(o));
  }

  spawnEnemyAt(type, x, ground, fromBoss = false) {
    const e = createEnemy({ type, x, y: ground });
    if (type === "collector") {
      e.x = clamp(x, 40, this.room.width - 40);
      e.y = 70;
    }
    this.enemies.push(e);
    this.spawnBlood(e.centerX, e.centerY, 8, PAL.blood);
    if (fromBoss) this.addEffect({ type: "portal", x: e.centerX, y: e.centerY, t: 0, dur: 0.45 });
    return e;
  }

  checkCollector() {
    const marks = [25, 55, 85];
    for (const mark of marks) {
      if (this.debt >= mark && !this.collectorMarks.has(mark) && this.roomIndex !== 2) {
        this.collectorMarks.add(mark);
        const p = this.player;
        this.spawnEnemyAt("collector", clamp(p.centerX + (p.facing > 0 ? 140 : -140), 50, this.room.width - 50), 0, true);
        this.banner = { title: "DEBT COLLECTOR", sector: "INTEREST DUE", flavor: "It can smell your credit.", t: 0, dur: 3 };
        this.sfx.bossRoar();
        this.shake(6, 0.5);
        this.flashScreen(0.25, PAL.gold);
        break;
      }
    }
  }

  onEnemyKilled(enemy) {
    this.kills++;
    const n = clamp(Math.round((enemy.blood || 10) / 3), 2, 5);
    let left = enemy.blood || 10;
    for (let i = 0; i < n; i++) {
      const val = i === n - 1 ? left : Math.max(1, Math.floor((enemy.blood || 10) / n));
      left -= val;
      this.pickups.push(new Pickup(enemy.centerX + rand(-6, 6), enemy.centerY + rand(-6, 6), val, "blood"));
    }
    if (Math.random() < (enemy.type === "katana" ? 0.3 : 0.12)) {
      this.pickups.push(new Pickup(enemy.centerX, enemy.centerY, 1, "heart"));
    }
    this.spawnBlood(enemy.centerX, enemy.centerY, 20, PAL.blood);
    this.spawnDust(enemy.centerX, enemy.y + enemy.h, 6);
    this.addEffect({ type: "death", x: enemy.centerX, y: enemy.centerY, t: 0, dur: 0.3 });
    this.shake(3.5, 0.16);
    this.sfx.hit();
    this.sfx.rev();
  }

  onPlayerDeath() {
    if (this.mode !== "play") return;
    this.mode = "dead";
    this.deaths++;
    this.debt = Math.min(99, this.debt + 3);
    this.blood = Math.floor(this.blood * 0.7);
    this.sfx.death();
    this.flashScreen(0.7, PAL.blood);
    this.shake(12, 0.8);
    this.spawnBlood(this.player.centerX, this.player.centerY, 34, PAL.blood2);
  }

  respawn() {
    const cp = this.checkpoint;
    if (cp.roomIndex !== this.roomIndex) {
      this.loadRoom(cp.roomIndex);
    } else {
      this.loadRoom(this.roomIndex);
    }
    this.player.hp = this.player.maxHp;
    this.player.invuln = 1.4;
    this.player.x = cp.x - this.player.w / 2;
    this.player.y = cp.y - this.player.h;
    this.player.vx = 0;
    this.player.vy = 0;
    this.player.facing = 1;
    this.player.dead = false;
    this.mode = "play";
    this.fade = 0.9;
    this.flashScreen(0.3, PAL.bone);
    this.banner = { title: "RISE AGAIN", sector: "DEBT OUTLIVES YOU", flavor: "The devil keeps the change.", t: 0, dur: 2.6 };
    this.sfx.checkpoint();
  }

  onBossDefeated() {
    if (this.mode !== "play") return;
    this.bossDefeated = true;
    this.mode = "win";
    this.blood += 150;
    this.boss = null;
    this.flashScreen(1.1, PAL.bone);
    this.shake(16, 1.5);
    this.sfx.win();
    if (!this.best || this.elapsed < this.best) {
      this.best = this.elapsed;
      try { localStorage.setItem("chainsawdebt.best", String(this.best)); } catch {}
    }
  }

  get rank() {
    if (this.debt <= 24 && this.deaths === 0) return "S";
    if (this.debt <= 40) return "A";
    if (this.debt <= 60) return "B";
    if (this.debt <= 80) return "C";
    return "D";
  }

  get rankFlavor() {
    const r = this.rank;
    return {
      S: "THE CHAINSAW HEART BEATS CLEAN.",
      A: "A GOOD DEAL. ALMOST.",
      B: "THE INTEREST IS MANAGEABLE.",
      C: "YOU PAID IN PIECES.",
      D: "YOU ARE THE COLLATERAL.",
    }[r];
  }

  get timeText() { return formatTime(this.elapsed); }
  get bestText() { return this.best ? formatTime(this.best) : "--:--"; }
}

import { W, H, PAL, hash, clamp } from "./util.js";
import {
  drawCheckpoint, drawAltar, drawMakima, drawDoor,
} from "./sprites.js";

const px = (ctx, x, y, w, h, c) => {
  ctx.fillStyle = c;
  ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
};

export function drawSkyline(ctx, cam, par, baseY, step, color, seed, winColor, alpha = 1) {
  const shift = (cam * par) % step;
  const start = Math.floor((cam * par) / step);
  ctx.save();
  ctx.globalAlpha = alpha;
  for (let i = -1; i < W / step + 2; i++) {
    const idx = i + start;
    const x = Math.round(i * step - shift);
    const hgt = 44 + Math.round(hash(idx * 3.1 + seed) * 104);
    const w = step - 4;
    const y = baseY - hgt;
    px(ctx, x, y, w, hgt, color);
    // rooftop antenna / water tank
    if (hash(idx + seed) > 0.62) {
      px(ctx, x + 8, y - 12, 1, 12, color);
      px(ctx, x + 7, y - 14, 3, 2, color);
    }
    if (hash(idx * 1.7 + seed) > 0.8) {
      px(ctx, x + w - 14, y - 6, 9, 6, color);
      px(ctx, x + w - 15, y - 7, 11, 2, color);
    }
    // windows
    const rows = Math.floor(hgt / 11);
    const cols = Math.max(1, Math.floor((w - 6) / 9));
    for (let r = 1; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const hv = hash(idx * 9.7 + r * 3.3 + c * 7.1 + seed);
        if (hv > 0.58) {
          const wy = y + r * 11;
          const wx = x + 4 + c * 9;
          ctx.globalAlpha = alpha * (0.25 + hv * 0.45);
          px(ctx, wx, wy, 3, 2, winColor);
          ctx.globalAlpha = alpha;
        }
      }
    }
  }
  ctx.restore();
}

export function drawBackground(ctx, game) {
  const t = game.time;
  const cam = game.camera.x;
  const theme = game.room.theme;
  if (theme === "city") drawCity(ctx, game, t, cam);
  else if (theme === "subway") drawSubway(ctx, game, t, cam);
  else drawBossRoom(ctx, game, t, cam);
}

function drawCity(ctx, game, t, cam) {
  // sky
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, "#06050e");
  g.addColorStop(0.42, "#160b20");
  g.addColorStop(0.72, "#351226");
  g.addColorStop(1, "#4a1927");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // stars
  for (let i = 0; i < 46; i++) {
    const x = (hash(i * 1.7) * 620 - cam * 0.02 + 1200) % 620 - 70;
    const y = 8 + hash(i * 2.9) * 92;
    const a = 0.15 + Math.abs(Math.sin(t * 0.7 + i)) * 0.5;
    ctx.globalAlpha = a;
    px(ctx, x, y, hash(i) > 0.85 ? 2 : 1, 1, i % 7 === 0 ? PAL.blood3 : PAL.bone);
  }
  ctx.globalAlpha = 1;

  // blood moon
  const mx = 344 - cam * 0.035;
  const my = 58;
  ctx.save();
  const glow = ctx.createRadialGradient(mx, my, 8, mx, my, 84);
  glow.addColorStop(0, "rgba(255,90,100,0.26)");
  glow.addColorStop(0.5, "rgba(210,40,60,0.10)");
  glow.addColorStop(1, "rgba(210,40,60,0)");
  ctx.fillStyle = glow;
  ctx.fillRect(mx - 90, my - 90, 180, 180);
  ctx.fillStyle = "#e8b7a7";
  ctx.beginPath();
  ctx.arc(mx, my, 31, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#d7958d";
  // craters
  ctx.globalAlpha = 0.5;
  const craters = [[-9, -7, 6], [8, 2, 9], [-4, 11, 4], [13, -11, 4], [-15, 4, 3]];
  for (const [cx, cy, r] of craters) {
    ctx.beginPath();
    ctx.arc(mx + cx, my + cy, r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  // drips of blood from the moon
  ctx.fillStyle = "#b12b40";
  px(ctx, mx - 3, my + 29, 2, 8, "#b12b40");
  px(ctx, mx + 11, my + 25, 1, 12, "#9d2136");
  ctx.restore();

  // thin clouds
  ctx.save();
  ctx.globalAlpha = 0.18;
  ctx.fillStyle = "#c47b8e";
  for (let i = 0; i < 5; i++) {
    const x = ((i * 170 + t * 4 - cam * 0.05) % 720 + 720) % 720 - 120;
    const y = 34 + i * 13;
    ctx.beginPath();
    ctx.ellipse(x, y, 46, 3, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();

  // far / mid / near skylines
  drawSkyline(ctx, cam, 0.06, 218, 42, "#120d1b", 3, "#7c4a68", 0.9);
  drawSkyline(ctx, cam, 0.16, 236, 54, "#1a1024", 11, "#b66573", 1);
  drawSkyline(ctx, cam, 0.31, 252, 66, "#21152c", 23, "#d69358", 1);

  // neon signs on the near layer
  for (const n of game.room.neon) {
    const x = n.x - cam * 0.31;
    if (x < -90 || x > W + 90) continue;
    drawNeon(ctx, x, n.y, n.text, n.color, t + n.x);
  }

  // overhead cables and hanging chains
  ctx.strokeStyle = "rgba(8,7,13,0.9)";
  ctx.lineWidth = 1;
  for (let i = 0; i < 4; i++) {
    const y = 18 + i * 14 + Math.sin(t * 0.4 + i) * 1;
    ctx.beginPath();
    ctx.moveTo(-10, y);
    ctx.bezierCurveTo(120, y + 10, 330, y - 6, W + 10, y + 6);
    ctx.stroke();
  }
  drawChain(ctx, 58 - cam * 0.4, 0, 46 + Math.sin(t * 0.7) * 3, t);
  drawChain(ctx, 404 - cam * 0.5, 0, 62 + Math.sin(t * 0.5 + 2) * 4, t);

  // ground haze
  const haze = ctx.createLinearGradient(0, 190, 0, H);
  haze.addColorStop(0, "rgba(120,30,60,0)");
  haze.addColorStop(1, "rgba(120,30,60,0.14)");
  ctx.fillStyle = haze;
  ctx.fillRect(0, 190, W, H - 190);
}

function drawNeon(ctx, x, y, text, color, t) {
  const c = color === "teal" ? PAL.teal : color === "gold" ? PAL.gold : PAL.blood2;
  const flicker = Math.sin(t * 13) > -0.92 ? 1 : 0.3;
  ctx.save();
  ctx.translate(Math.round(x), Math.round(y));
  // bracket
  px(ctx, -2, -5, 2, 14, "#0a0810");
  // sign
  ctx.globalAlpha = 0.25 * flicker;
  ctx.fillStyle = c;
  ctx.fillRect(-4, -4, 44, 13);
  ctx.globalAlpha = 0.96 * flicker;
  ctx.fillStyle = "#0b0810";
  ctx.fillRect(-2, -2, 40, 9);
  ctx.fillStyle = c;
  ctx.font = '700 7px "DejaVu Sans Mono", monospace';
  ctx.textBaseline = "top";
  ctx.fillText(text, 1, 0);
  ctx.globalAlpha = 0.4 * flicker;
  ctx.strokeStyle = c;
  ctx.lineWidth = 1;
  ctx.strokeRect(-3, -3, 42, 11);
  ctx.restore();
}

function drawChain(ctx, x, y, len, t) {
  ctx.save();
  ctx.strokeStyle = "rgba(12,10,17,0.95)";
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let i = 0; i < len; i += 6) {
    const sway = Math.sin(t * 0.6 + i * 0.1) * (i / len) * 2;
    if (i === 0) ctx.moveTo(x + sway, y + i);
    else ctx.lineTo(x + sway, y + i);
  }
  ctx.stroke();
  ctx.strokeStyle = "rgba(90,76,98,0.5)";
  ctx.lineWidth = 1;
  for (let i = 4; i < len; i += 7) {
    const sway = Math.sin(t * 0.6 + i * 0.1) * (i / len) * 2;
    ctx.beginPath();
    ctx.ellipse(x + sway, y + i, 2, 3, 0, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();
}

function drawSubway(ctx, game, t, cam) {
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, "#07070d");
  g.addColorStop(0.5, "#0d0d18");
  g.addColorStop(1, "#17101a");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // tiled back wall
  ctx.save();
  ctx.globalAlpha = 0.5;
  const tile = 18;
  const off = -(cam * 0.25) % tile;
  for (let x = off - tile; x < W + tile; x += tile) {
    for (let y = 42; y < 220; y += tile) {
      const hv = hash(Math.floor((x + cam * 0.25) / tile) * 4.1 + y * 0.13);
      px(ctx, x, y, tile - 1, tile - 1, hv > 0.6 ? "#1a2030" : "#171b28");
      if (hv > 0.93) px(ctx, x + 3, y + 4, 5, 2, "#3c2a2b");
    }
  }
  ctx.restore();

  // far tunnel lights
  for (let i = 0; i < 6; i++) {
    const x = ((i * 190 - cam * 0.22) % 1140 + 1140) % 1140 - 120;
    const flicker = 0.35 + Math.abs(Math.sin(t * 3 + i * 2.2)) * 0.5;
    ctx.save();
    ctx.globalAlpha = flicker;
    ctx.fillStyle = "rgba(73,216,198,0.55)";
    px(ctx, x, 84, 2, 1, PAL.teal);
    ctx.globalAlpha = flicker * 0.16;
    ctx.fillStyle = PAL.teal;
    ctx.beginPath();
    ctx.arc(x, 84, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // arches
  for (let i = -1; i < 8; i++) {
    const x = Math.round(i * 148 - ((cam * 0.42) % 148));
    ctx.strokeStyle = "#242433";
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(x, 220);
    ctx.lineTo(x, 80);
    ctx.quadraticCurveTo(x, 42, x + 74, 42);
    ctx.quadraticCurveTo(x + 148, 42, x + 148, 80);
    ctx.lineTo(x + 148, 220);
    ctx.stroke();
    ctx.strokeStyle = "#11111b";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x + 5, 220);
    ctx.lineTo(x + 5, 80);
    ctx.quadraticCurveTo(x + 5, 47, x + 74, 47);
    ctx.quadraticCurveTo(x + 143, 47, x + 143, 80);
    ctx.lineTo(x + 143, 220);
    ctx.stroke();
  }

  // cables / pipes
  ctx.strokeStyle = "#302a30";
  ctx.lineWidth = 2;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(-10, 26 + i * 9);
    ctx.bezierCurveTo(140, 34 + i * 9, 300, 22 + i * 8, W + 10, 30 + i * 9);
    ctx.stroke();
  }

  // fluorescent lights
  for (let i = 0; i < 5; i++) {
    const x = Math.round(i * 210 - ((cam * 0.55) % 210));
    const flicker = Math.sin(t * 22 + i * 3.1) > -0.86 ? 1 : 0.25;
    ctx.save();
    px(ctx, x + 30, 24, 46, 3, "rgba(10,10,16,0.9)");
    ctx.globalAlpha = flicker;
    px(ctx, x + 32, 25, 42, 2, "#cfe8df");
    ctx.globalAlpha = flicker * 0.16;
    const lg = ctx.createLinearGradient(0, 26, 0, 240);
    lg.addColorStop(0, "rgba(170,255,235,0.5)");
    lg.addColorStop(1, "rgba(170,255,235,0)");
    ctx.fillStyle = lg;
    ctx.beginPath();
    ctx.moveTo(x + 33, 27);
    ctx.lineTo(x + 73, 27);
    ctx.lineTo(x + 106, 244);
    ctx.lineTo(x, 244);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  // rails in the dark
  ctx.save();
  ctx.globalAlpha = 0.5;
  px(ctx, 0, 258, W, 2, "#3b3540");
  px(ctx, 0, 266, W, 2, "#2b2730");
  for (let i = -1; i < 24; i++) {
    const x = i * 44 - ((cam * 0.9) % 44);
    px(ctx, x, 258, 16, 10, "#1b1720");
  }
  ctx.restore();

  // grime / red emergency glows
  const rg = ctx.createLinearGradient(0, 190, 0, H);
  rg.addColorStop(0, "rgba(120,20,40,0)");
  rg.addColorStop(1, "rgba(120,20,40,0.18)");
  ctx.fillStyle = rg;
  ctx.fillRect(0, 190, W, H - 190);
}

function drawBossRoom(ctx, game, t, cam) {
  const g = ctx.createRadialGradient(W / 2, 70, 20, W / 2, 130, 340);
  g.addColorStop(0, "#4a1328");
  g.addColorStop(0.42, "#240b1c");
  g.addColorStop(1, "#08060e");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // writhing flesh walls
  for (let i = 0; i < 14; i++) {
    const x = hash(i * 2.3) * 560 - cam * 0.15;
    const y = 20 + hash(i * 5.1) * 190;
    const r = 18 + hash(i * 7.7) * 44;
    const pulse = 1 + Math.sin(t * 1.2 + i) * 0.06;
    ctx.save();
    ctx.globalAlpha = 0.15;
    ctx.fillStyle = i % 2 ? "#8a2547" : "#5c1a3a";
    ctx.beginPath();
    ctx.ellipse(x, y, r * pulse, r * 0.7, hash(i) * 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // giant watching eye
  const ex = W / 2 - cam * 0.1;
  const ey = 66;
  const lookX = game.player ? clamp((game.player.centerX - ex) * 0.04, -8, 8) : 0;
  const blink = Math.sin(t * 0.9) > 0.94 ? 0.1 : 1;
  ctx.save();
  ctx.fillStyle = "#0b0710";
  ctx.beginPath();
  ctx.ellipse(ex, ey, 58, 29 * blink, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#cdbfae";
  ctx.beginPath();
  ctx.ellipse(ex, ey, 54, 25 * blink, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#7e1a2c";
  ctx.beginPath();
  ctx.arc(ex + lookX, ey, 18 * blink, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#170a10";
  ctx.beginPath();
  ctx.arc(ex + lookX, ey, 8 * blink, 0, Math.PI * 2);
  ctx.fill();
  // veins around the eye
  ctx.strokeStyle = "rgba(160,30,60,0.45)";
  ctx.lineWidth = 1;
  for (let i = 0; i < 8; i++) {
    const a = i * 0.79;
    ctx.beginPath();
    ctx.moveTo(ex + Math.cos(a) * 58, ey + Math.sin(a) * 27);
    ctx.quadraticCurveTo(
      ex + Math.cos(a + 0.2) * 90, ey + Math.sin(a + 0.2) * 45,
      ex + Math.cos(a) * 120, ey + Math.sin(a) * 66
    );
    ctx.stroke();
  }
  ctx.restore();

  // hanging chains with hooks
  for (let i = 0; i < 5; i++) {
    const x = 46 + i * 112 - cam * 0.3;
    drawChain(ctx, x, 0, 44 + (i % 3) * 18, t + i);
    px(ctx, x - 2, 44 + (i % 3) * 18, 4, 5, "#2a2032");
  }

  // gold coins suspended in the air
  for (let i = 0; i < 9; i++) {
    const x = (hash(i * 8.1) * 560 + Math.sin(t * 0.5 + i) * 8 - cam * 0.5 + 560) % 560;
    const y = 90 + hash(i * 3.3) * 120;
    ctx.save();
    ctx.globalAlpha = 0.35 + Math.abs(Math.sin(t + i)) * 0.3;
    px(ctx, x, y, 2, 3, PAL.gold2);
    ctx.restore();
  }

  // pulsing floor glow
  const fg = ctx.createLinearGradient(0, 205, 0, H);
  fg.addColorStop(0, "rgba(210,40,70,0)");
  fg.addColorStop(1, "rgba(150,20,50,0.3)");
  ctx.fillStyle = fg;
  ctx.fillRect(0, 205, W, H - 205);
}

// ------------------------------------------------------------- terrain

export function drawTerrain(ctx, game) {
  const theme = game.room.theme;
  for (const s of game.room.solids) drawBlock(ctx, s, theme, true, game);
  for (const p of game.room.platforms) drawBlock(ctx, p, theme, false, game);
  for (const hz of game.room.hazards) drawSpikes(ctx, hz, game);
}

function drawBlock(ctx, s, theme, isSolid, game) {
  const x = Math.round(s.x);
  const y = Math.round(s.y);
  const w = Math.round(s.w);
  const h = Math.round(s.h);
  if (theme === "city") {
    px(ctx, x, y, w, h, "#141019");
    px(ctx, x, y, w, 3, "#33283b");
    px(ctx, x, y, w, 1, "#58445f");
    // sidewalk seams
    for (let sx = x + 20; sx < x + w; sx += 36) px(ctx, sx, y + 3, 1, 6, "#221a2a");
    for (let sx = x + 8; sx < x + w; sx += 24) {
      const hv = hash(sx * 0.7 + game.roomIndex);
      if (hv > 0.72) px(ctx, sx, y + 9 + (hv * 8) % 8, 5, 1, "#2a2132");
    }
    if (!isSolid) {
      // AC unit / ledge underside
      px(ctx, x + 3, y + 4, w - 6, 2, "#1e1726");
      for (let sx = x + 8; sx < x + w - 6; sx += 18) {
        px(ctx, sx, y + 5, 6, 2, "#0d0a12");
        px(ctx, sx + 2, y + 7, 2, 1, "#3d3048");
      }
    } else {
      px(ctx, x, y + 6, w, 1, "#0d0a12");
    }
  } else if (theme === "subway") {
    px(ctx, x, y, w, h, "#15151f");
    px(ctx, x, y, w, 2, "#3e3b49");
    px(ctx, x, y, w, 1, "#6c6676");
    // warning stripe on edges
    for (let sx = x; sx < x + w; sx += 10) {
      px(ctx, sx, y + 2, 5, 2, (sx / 10) % 2 < 1 ? PAL.gold2 : "#1a1512");
    }
    for (let sx = x + 12; sx < x + w - 10; sx += 24) {
      px(ctx, sx, y + 6, 10, 1, "#24222d");
      px(ctx, sx + 2, y + 8, 6, 1, "#0c0b11");
    }
    if (!isSolid) {
      px(ctx, x + 2, y + 10, w - 4, 2, "#24222d");
      for (let sx = x + 6; sx < x + w - 4; sx += 12) px(ctx, sx, y + 11, 2, 2, "#4a4553");
    }
  } else {
    // boss: bone-wrapped meat
    px(ctx, x, y, w, h, "#180914");
    px(ctx, x, y, w, 3, "#d9bfa8");
    px(ctx, x, y, w, 1, "#f2e6d8");
    for (let sx = x + 8; sx < x + w; sx += 14) {
      const hv = hash(sx * 1.3 + game.roomIndex);
      if (hv > 0.4) {
        px(ctx, sx, y + 3, 2, 4 + hv * 6, "#9e1f3c");
        px(ctx, sx + 1, y + 4, 1, 2 + hv * 4, "#5c1028");
      }
    }
    if (!isSolid) {
      px(ctx, x, y + 9, w, 2, "#2a0f1f");
      for (let sx = x + 5; sx < x + w; sx += 11) {
        px(ctx, sx, y + 10, 2, 2, "#d9bfa8");
        px(ctx, sx + 1, y + 12, 1, 2, "#bda48f");
      }
    }
  }
}

function drawSpikes(ctx, hz, game) {
  const x = Math.round(hz.x);
  const y = Math.round(hz.y);
  const w = Math.round(hz.w);
  const h = Math.round(hz.h);
  // pit darkness
  px(ctx, x, y, w, h, "#09060d");
  px(ctx, x, y - 2, w, 2, "#3a0d17");
  for (let sx = x + 2; sx < x + w; sx += 9) {
    ctx.fillStyle = "#b7aea3";
    ctx.beginPath();
    ctx.moveTo(sx, y + h);
    ctx.lineTo(sx + 4, y - 5);
    ctx.lineTo(sx + 8, y + h);
    ctx.fill();
    ctx.fillStyle = "#6f6a67";
    ctx.beginPath();
    ctx.moveTo(sx + 1, y + h);
    ctx.lineTo(sx + 4, y - 5);
    ctx.lineTo(sx + 4, y + h);
    ctx.fill();
    ctx.fillStyle = game.time ? PAL.blood : PAL.blood;
    px(ctx, sx + 3, y - 7, 2, 2, PAL.blood);
  }
}

// ------------------------------------------------------------- props

export function drawProps(ctx, game, behind = true) {
  const room = game.room;
  if (behind) {
    for (const d of room.details) {
      if (d.type === "puddle") drawPuddle(ctx, d, room.theme, game.time);
      else if (d.type === "vending") drawVending(ctx, d, game.time);
      else if (d.type === "barrel") drawBarrel(ctx, d);
    }
    for (const cp of room.checkpoints) {
      const active = game.checkpoint.roomIndex === game.roomIndex &&
        Math.abs(game.checkpoint.x - cp.x) < 2;
      drawCheckpoint(ctx, cp, active, game.time, room.theme);
    }
    for (const a of room.altars) drawAltar(ctx, a, game.time, !game.contracts.size);
    for (const n of room.npcs) drawMakima(ctx, n, game.time);
    for (const door of room.doors) drawDoor(ctx, door, game.time, room.theme);
  }
}

function drawPuddle(ctx, d, theme, t) {
  const y = d.x === 180 ? 244 : 244;
  ctx.save();
  ctx.globalAlpha = 0.6;
  ctx.fillStyle = theme === "subway" ? "#1b2b31" : "#241829";
  ctx.beginPath();
  ctx.ellipse(d.x + d.w / 2, y, d.w / 2, 3, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 0.3;
  ctx.fillStyle = theme === "subway" ? PAL.teal : PAL.blood2;
  const shimmer = Math.sin(t * 1.4 + d.x) * 3;
  ctx.fillRect(d.x + d.w * 0.25 + shimmer, y - 1, d.w * 0.3, 1);
  ctx.restore();
}

function drawVending(ctx, d, t) {
  const x = d.x;
  px(ctx, x - 10, 192, 22, 48, PAL.ink);
  px(ctx, x - 9, 193, 20, 46, "#1b2b34");
  px(ctx, x - 7, 196, 16, 24, "#081217");
  // cans
  for (let r = 0; r < 4; r++) {
    for (let c = 0; c < 3; c++) {
      px(ctx, x - 5 + c * 5, 199 + r * 5, 3, 3, (r + c) % 3 === 0 ? PAL.blood2 : (r + c) % 3 === 1 ? PAL.gold : PAL.teal);
    }
  }
  // glow
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  ctx.globalAlpha = 0.16 + Math.sin(t * 2.2) * 0.03;
  ctx.fillStyle = PAL.teal;
  ctx.fillRect(x - 12, 190, 26, 54);
  ctx.restore();
}

function drawBarrel(ctx, d) {
  const x = d.x;
  px(ctx, x - 7, 222, 14, 18, PAL.ink);
  px(ctx, x - 6, 223, 12, 16, "#262b28");
  px(ctx, x - 6, 226, 12, 2, "#3d4540");
  px(ctx, x - 6, 235, 12, 2, "#3d4540");
  px(ctx, x - 3, 229, 6, 4, PAL.gold2);
}

export function drawForeground(ctx, game) {
  const theme = game.room.theme;
  const t = game.time;
  if (theme === "city") {
    ctx.save();
    ctx.strokeStyle = "rgba(200,220,255,0.16)";
    ctx.lineWidth = 1;
    for (let i = 0; i < 52; i++) {
      const x = (hash(i * 3.7) * 520 + t * 7) % 520 - 20;
      const y = (hash(i * 7.1) * 272 + t * 260) % 272;
      ctx.globalAlpha = 0.2 + hash(i) * 0.3;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x - 2, y + 7);
      ctx.stroke();
    }
    ctx.restore();
  } else if (theme === "subway") {
    // dripping ceiling water
    ctx.save();
    ctx.globalAlpha = 0.25;
    for (let i = 0; i < 12; i++) {
      const x = (hash(i * 5.3) * 520 - game.camera.x * 0.8 + 1040) % 520;
      const cycle = (t * 70 + hash(i) * 240) % 240;
      px(ctx, x, cycle, 1, 3, PAL.teal);
    }
    ctx.restore();
  } else {
    // embers
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (let i = 0; i < 26; i++) {
      const x = (hash(i * 4.1) * 560 + Math.sin(t + i) * 14 - game.camera.x * 0.6 + 560) % 560;
      const y = (hash(i * 8.7) * 272 - t * (8 + hash(i) * 18)) % 272;
      ctx.globalAlpha = 0.15 + hash(i) * 0.4;
      px(ctx, x, y < 0 ? y + 272 : y, 1, 1, i % 3 === 0 ? PAL.gold : PAL.blood2);
    }
    ctx.restore();
  }

  // vignette
  const vg = ctx.createRadialGradient(W / 2, H / 2, 80, W / 2, H / 2, 300);
  vg.addColorStop(0, "rgba(0,0,0,0)");
  vg.addColorStop(1, "rgba(0,0,0,0.55)");
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
}

import { W, H, PAL, clamp } from "./util.js";

const FONT = '"DejaVu Sans Mono", "Courier New", monospace';

export function text(ctx, str, x, y, o = {}) {
  const {
    size = 8, color = PAL.bone, align = "left", weight = 700,
    shadow = true, glow = 0, alpha = 1, baseline = "top", spacing = 0,
  } = o;
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.font = `${weight} ${size}px ${FONT}`;
  ctx.textBaseline = baseline;
  ctx.textAlign = align;
  if (shadow) {
    ctx.fillStyle = "rgba(0,0,0,0.8)";
    ctx.fillText(str, x + 1, y + 1);
  }
  if (glow) {
    ctx.shadowColor = color;
    ctx.shadowBlur = glow;
  }
  ctx.fillStyle = color;
  if (spacing) {
    const chars = [...str];
    const widths = chars.map((c) => ctx.measureText(c).width + spacing);
    const total = widths.reduce((a, b) => a + b, 0) - spacing;
    let cx = align === "center" ? x - total / 2 : align === "right" ? x - total : x;
    ctx.textAlign = "left";
    chars.forEach((c, i) => {
      ctx.fillText(c, cx, y);
      cx += widths[i];
    });
  } else {
    ctx.fillText(str, x, y);
  }
  ctx.restore();
}

export function px(ctx, x, y, w, h, c) {
  ctx.fillStyle = c;
  ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
}

export function panel(ctx, x, y, w, h, accent = PAL.blood) {
  ctx.save();
  ctx.fillStyle = "rgba(5,4,9,0.88)";
  ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = "rgba(242,230,216,0.16)";
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  // corner brackets
  ctx.strokeStyle = accent;
  ctx.lineWidth = 1;
  const c = 8;
  ctx.beginPath();
  ctx.moveTo(x, y + c); ctx.lineTo(x, y); ctx.lineTo(x + c, y);
  ctx.moveTo(x + w - c, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + c);
  ctx.moveTo(x, y + h - c); ctx.lineTo(x, y + h); ctx.lineTo(x + c, y + h);
  ctx.moveTo(x + w - c, y + h); ctx.lineTo(x + w, y + h); ctx.lineTo(x + w, y + h - c);
  ctx.stroke();
  // top accent line
  ctx.globalAlpha = 0.55;
  ctx.fillStyle = accent;
  ctx.fillRect(x + 16, y, w - 32, 1);
  ctx.restore();
}

function heart(ctx, x, y, filled, scale = 1) {
  const map = [
    ".XX.XX.",
    "XXXXXXX",
    "XXXXXXX",
    ".XXXXX.",
    "..XXX..",
    "...X...",
  ];
  for (let r = 0; r < map.length; r++) {
    for (let c = 0; c < map[r].length; c++) {
      if (map[r][c] !== "X") continue;
      const col = filled
        ? (r === 1 && c < 4 ? PAL.blood3 : PAL.blood2)
        : "#2a1a24";
      px(ctx, x + c * scale, y + r * scale, scale, scale, col);
    }
  }
  if (!filled) {
    ctx.save();
    ctx.globalAlpha = 0.35;
    ctx.strokeStyle = PAL.blood;
    ctx.strokeRect(x + 0.5, y + 0.5, 7 * scale - 1, 6 * scale - 1);
    ctx.restore();
  }
}

function bloodDrop(ctx, x, y, s = 1) {
  px(ctx, x + 2 * s, y, 2 * s, 2 * s, PAL.blood2);
  px(ctx, x + 1 * s, y + 2 * s, 4 * s, 3 * s, PAL.blood);
  px(ctx, x, y + 3 * s, 6 * s, 3 * s, PAL.blood);
  px(ctx, x + 1 * s, y + 5 * s, 4 * s, 2 * s, PAL.rust);
  px(ctx, x + 1 * s, y + 2 * s, 1 * s, 1 * s, PAL.blood3);
}

function chainIcon(ctx, x, y) {
  ctx.save();
  ctx.strokeStyle = PAL.gold2;
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, 4, 3);
  ctx.strokeRect(x + 3.5, y + 2.5, 4, 3);
  ctx.restore();
}

function weaponIcon(ctx, x, y, weapon) {
  if (weapon === "chainsaw") {
    px(ctx, x, y + 4, 13, 4, "#3a3440");
    px(ctx, x + 1, y + 5, 11, 2, PAL.steel);
    for (let i = 0; i < 5; i++) {
      px(ctx, x + 1 + i * 2.4, y + 3, 1, 1, PAL.steel);
    }
    px(ctx, x - 3, y + 3, 4, 6, PAL.rust);
    px(ctx, x - 2, y + 4, 2, 2, PAL.blood);
  } else if (weapon === "shotgun") {
    px(ctx, x, y + 4, 16, 3, PAL.steel2);
    px(ctx, x + 10, y + 3, 5, 2, PAL.steel);
    px(ctx, x + 1, y + 6, 4, 3, "#3a2b22");
    px(ctx, x + 6, y + 6, 4, 2, "#3a2b22");
  } else {
    px(ctx, x, y + 5, 16, 2, PAL.ink);
    px(ctx, x + 1, y + 5, 14, 1, PAL.steel);
    px(ctx, x - 2, y + 4, 3, 4, PAL.gold2);
  }
}

export function drawHud(ctx, game) {
  const p = game.player;
  if (!p) return;
  const t = game.time;
  // top backdrop
  const g = ctx.createLinearGradient(0, 0, 0, 46);
  g.addColorStop(0, "rgba(5,4,10,0.86)");
  g.addColorStop(1, "rgba(5,4,10,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, 46);

  // hearts
  for (let i = 0; i < p.maxHp; i++) {
    heart(ctx, 11 + i * 11, 8, i < p.hp, 1);
  }
  // blood
  bloodDrop(ctx, 12, 21);
  text(ctx, String(game.blood).padStart(3, "0"), 22, 21, { size: 9, color: PAL.bone, glow: 2 });
  // debt
  chainIcon(ctx, 56, 22);
  const debtCol = game.debt >= 60 ? PAL.blood2 : game.debt >= 30 ? PAL.gold : PAL.bone2;
  text(ctx, `DEBT ${String(game.debt).padStart(2, "0")}`, 66, 21, { size: 8, color: debtCol, glow: game.debt >= 60 ? 4 : 0 });

  // right metadata
  text(ctx, game.room.sector, W - 12, 8, { size: 7, color: PAL.steel2, align: "right" });
  text(ctx, game.timeText, W - 12, 18, { size: 8, color: PAL.bone2, align: "right" });
  text(ctx, "TAB CONTRACTS  ·  ESC PAUSE", W - 12, 30, { size: 6, color: "rgba(242,230,216,0.42)", align: "right", shadow: false });

  // weapon / ammo
  const wy = H - 30;
  ctx.save();
  ctx.fillStyle = "rgba(5,4,10,0.62)";
  ctx.fillRect(6, wy - 3, 118, 27);
  ctx.strokeStyle = "rgba(242,230,216,0.12)";
  ctx.strokeRect(6.5, wy - 2.5, 117, 26);
  ctx.restore();
  weaponIcon(ctx, 14, wy + 2, p.weapon);
  const wname = p.weapon === "chainsaw" ? "CHAINSAW" : p.weapon === "shotgun" ? "BLOOD GUN" : "KON BLADE";
  text(ctx, wname, 38, wy, { size: 7, color: PAL.bone, glow: 1 });
  if (p.weapon === "shotgun") {
    for (let i = 0; i < p.maxAmmo; i++) {
      px(ctx, 38 + i * 5, wy + 11, 3, 5, i < p.ammo ? PAL.gold : "#2a2028");
    }
    if (p.ammo < p.maxAmmo) px(ctx, 38, wy + 18, Math.min(1, p.reload / 0.72) * 28, 1, PAL.gold2);
  } else if (p.weapon === "katana") {
    text(ctx, "CURSED EDGE", 38, wy + 11, { size: 6, color: PAL.steel2, shadow: false });
  } else {
    text(ctx, "HOLD NOTHING BACK", 38, wy + 11, { size: 6, color: PAL.steel2, shadow: false });
  }
  if (game.weapons.size > 1) {
    text(ctx, "Q SWAP", W - 10, H - 12, { size: 6, color: "rgba(242,230,216,0.35)", align: "right", shadow: false });
  }

  // special cooldown
  if (game.hasContract("fox")) {
    const ready = p.specialCd <= 0;
    text(ctx, ready ? "L — FOX BITE" : `FOX ${p.specialCd.toFixed(1)}s`, 9, H - 46,
      { size: 6, color: ready ? PAL.gold : PAL.steel2, shadow: false });
  }

  if (game.boss && !game.boss.dead) drawBossBar(ctx, game);
}

function drawBossBar(ctx, game) {
  const b = game.boss;
  const w = 268;
  const x = (W - w) / 2;
  const y = H - 15;
  ctx.save();
  ctx.fillStyle = "rgba(4,3,8,0.82)";
  ctx.fillRect(x - 3, y - 11, w + 6, 21);
  text(ctx, "THE DEBT DEVIL", x, y - 12, { size: 7, color: PAL.blood3, glow: 3 });
  text(ctx, b.phase === 2 ? "FORECLOSURE" : "COLLECTOR CLASS", x + w, y - 12, { size: 6, color: PAL.gold, align: "right" });
  ctx.fillStyle = "#2a0d18";
  ctx.fillRect(x, y, w, 6);
  const pct = clamp(b.hp / b.maxHp, 0, 1);
  const grad = ctx.createLinearGradient(x, 0, x + w, 0);
  grad.addColorStop(0, PAL.rust);
  grad.addColorStop(0.6, PAL.blood);
  grad.addColorStop(1, PAL.blood2);
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w * pct, 6);
  // segment ticks
  ctx.globalAlpha = 0.5;
  for (let i = 1; i < 10; i++) px(ctx, x + (w / 10) * i, y, 1, 6, PAL.ink);
  ctx.globalAlpha = 1;
  ctx.strokeStyle = "rgba(242,230,216,0.35)";
  ctx.strokeRect(x - 0.5, y - 0.5, w + 1, 7);
  if (b.state === "stunned") {
    text(ctx, "OPEN!", x + w / 2, y - 20, { size: 8, color: PAL.gold, align: "center", glow: 5 });
  }
  ctx.restore();
}

export function drawWorldUi(ctx, game) {
  const p = game.player;
  if (!p) return;
  // interaction prompt
  if (game.prompt) {
    const label = game.prompt.label;
    const w = label.length * 6 + 22;
    const x = W / 2 - w / 2;
    const y = H - 52;
    ctx.save();
    ctx.fillStyle = "rgba(5,4,10,0.82)";
    ctx.fillRect(x, y, w, 14);
    ctx.strokeStyle = PAL.gold2;
    ctx.strokeRect(x + 0.5, y + 0.5, w - 1, 13);
    // keycap E
    px(ctx, x + 5, y + 4, 7, 7, PAL.bone2);
    text(ctx, "E", x + 7, y + 4, { size: 6, color: PAL.ink, shadow: false });
    text(ctx, label.replace("  [E]", ""), x + 16, y + 4, { size: 7, color: PAL.bone, shadow: false });
    ctx.restore();
  }

  // hint toast
  if (game.hint) {
    const h = game.hint;
    const fade = Math.min(1, h.t * 3, (h.dur - h.t) * 2);
    const w = Math.min(W - 40, h.text.length * 4.8 + 24);
    const x = W / 2 - w / 2;
    const y = game.prompt ? H - 72 : H - 50;
    ctx.save();
    ctx.globalAlpha = clamp(fade, 0, 1);
    ctx.fillStyle = "rgba(5,4,10,0.7)";
    ctx.fillRect(x, y, w, 13);
    ctx.fillStyle = "rgba(210,31,60,0.7)";
    ctx.fillRect(x, y, 2, 13);
    text(ctx, h.text, W / 2, y + 3, { size: 6, color: PAL.bone2, align: "center", shadow: false });
    ctx.restore();
  }

  // low health warning
  if (p.hp === 1) {
    const a = 0.18 + Math.abs(Math.sin(game.time * 5)) * 0.16;
    const vg = ctx.createRadialGradient(W / 2, H / 2, 100, W / 2, H / 2, 300);
    vg.addColorStop(0, "rgba(210,31,60,0)");
    vg.addColorStop(1, `rgba(210,31,60,${a})`);
    ctx.fillStyle = vg;
    ctx.fillRect(0, 0, W, H);
  }
}

export function drawBanner(ctx, game) {
  const b = game.banner;
  if (!b) return;
  const fadeIn = clamp(b.t * 3, 0, 1);
  const fadeOut = clamp((b.dur - b.t) * 1.6, 0, 1);
  const a = Math.min(fadeIn, fadeOut);
  const slide = (1 - fadeIn) * 14;
  ctx.save();
  ctx.globalAlpha = a;
  const y = 62 - slide;
  // dark band
  const g = ctx.createLinearGradient(0, y - 18, 0, y + 46);
  g.addColorStop(0, "rgba(4,3,8,0)");
  g.addColorStop(0.3, "rgba(4,3,8,0.72)");
  g.addColorStop(0.7, "rgba(4,3,8,0.72)");
  g.addColorStop(1, "rgba(4,3,8,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, y - 18, W, 66);
  text(ctx, b.sector || "", W / 2, y - 4, { size: 7, color: PAL.gold, align: "center", glow: 3, spacing: 2 });
  text(ctx, b.title, W / 2, y + 9, { size: 19, color: PAL.bone, align: "center", glow: 6, spacing: 2 });
  text(ctx, b.flavor || "", W / 2, y + 33, { size: 7, color: PAL.steel2, align: "center", shadow: false });
  ctx.globalAlpha = a * 0.8;
  ctx.fillStyle = PAL.blood;
  ctx.fillRect(W / 2 - 34, y + 31, 30, 1);
  ctx.fillRect(W / 2 + 4, y + 31, 30, 1);
  ctx.restore();
}

export function drawTitle(ctx, game) {
  const t = game.titleTime;
  // dark vignette over the drifting city
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, "rgba(4,3,8,0.5)");
  g.addColorStop(0.45, "rgba(4,3,8,0.18)");
  g.addColorStop(1, "rgba(4,3,8,0.8)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // decorative chainsaw slash behind title
  ctx.save();
  ctx.translate(W / 2, 78);
  ctx.rotate(-0.08);
  ctx.globalAlpha = 0.16;
  px(ctx, -150, -10, 300, 20, PAL.blood2);
  for (let i = 0; i < 22; i++) {
    px(ctx, -150 + i * 14, -18, 7, 8, PAL.blood);
  }
  ctx.globalCompositeOperation = "lighter";
  ctx.globalAlpha = 0.12;
  ctx.strokeStyle = PAL.blood;
  ctx.lineWidth = 2;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.arc(0, 0, 110 + i * 18, -0.7, 0.7);
    ctx.stroke();
  }
  ctx.restore();

  // title
  const jitter = Math.sin(t * 1.5) * 0.6;
  const cx = W / 2;
  text(ctx, "CHAINSAW", cx + 2, 36 + jitter, { size: 38, color: PAL.rust, align: "center", glow: 8, spacing: 1 });
  text(ctx, "CHAINSAW", cx, 34 + jitter, { size: 38, color: PAL.bone, align: "center", glow: 10, spacing: 1 });
  // blood drip under it
  ctx.save();
  ctx.globalAlpha = 0.8;
  px(ctx, cx - 96, 70, 2, 5, PAL.blood);
  px(ctx, cx - 92, 70, 1, 10, PAL.blood);
  px(ctx, cx - 93, 80, 3, 3, PAL.blood2);
  px(ctx, cx + 74, 70, 2, 7, PAL.blood);
  px(ctx, cx + 78, 70, 1, 4, PAL.blood);
  ctx.restore();

  text(ctx, "DEBT", cx + 1, 82 + jitter, { size: 34, color: PAL.gold2, align: "center", glow: 9, spacing: 8 });
  text(ctx, "DEBT", cx, 80 + jitter, { size: 34, color: PAL.blood2, align: "center", glow: 12, spacing: 8 });

  // teeth divider
  ctx.save();
  for (let i = 0; i < 21; i++) {
    const x = cx - 126 + i * 12;
    ctx.fillStyle = i % 2 ? PAL.bone2 : PAL.steel2;
    ctx.beginPath();
    ctx.moveTo(x, 120);
    ctx.lineTo(x + 5, 126);
    ctx.lineTo(x + 10, 120);
    ctx.fill();
  }
  ctx.restore();

  text(ctx, "A BLOODSOAKED BARGAIN", cx, 133, { size: 9, color: PAL.gold, align: "center", spacing: 2, glow: 3 });
  text(ctx, "POWER NOW. INTEREST FOREVER.", cx, 148, { size: 7, color: PAL.steel2, align: "center", shadow: false });

  // press enter
  const blink = Math.sin(t * 4.4) > -0.2 ? 1 : 0.35;
  ctx.save();
  ctx.globalAlpha = blink;
  text(ctx, "PRESS ENTER TO SIGN", cx, 177, { size: 12, color: PAL.bone, align: "center", glow: 6, spacing: 2 });
  ctx.restore();

  // controls
  ctx.save();
  ctx.globalAlpha = 0.8;
  text(ctx, "A / D  MOVE      SPACE  JUMP      J  ATTACK      K  DASH", cx, 201, { size: 7, color: PAL.bone2, align: "center", shadow: false, spacing: 0 });
  text(ctx, "E  INTERACT      TAB  CONTRACTS      ESC  PAUSE", cx, 212, { size: 7, color: PAL.bone2, align: "center", shadow: false, spacing: 0 });
  ctx.restore();

  // bottom row
  text(ctx, "A FAN-MADE PIXEL NIGHTMARE", 12, H - 18, { size: 6, color: "rgba(242,230,216,0.35)", shadow: false, spacing: 1 });
  text(ctx, `BEST  ${game.bestText}`, W - 12, H - 18, { size: 6, color: "rgba(242,230,216,0.35)", align: "right", shadow: false });
  text(ctx, "M — SOUND", 12, H - 10, { size: 6, color: "rgba(242,230,216,0.22)", shadow: false });

  // little animated chainsaw ornament
  ctx.save();
  ctx.translate(cx, 160);
  ctx.rotate(Math.sin(t * 2) * 0.05);
  ctx.globalAlpha = 0.4;
  px(ctx, -22, 0, 44, 3, PAL.steel2);
  for (let i = 0; i < 8; i++) px(ctx, -20 + i * 5, -2, 3, 2, PAL.steel2);
  ctx.restore();
}

import { W, H, PAL, clamp } from "./util.js";
import { text, panel, px } from "./render-ui.js";
import { CONTRACTS, SHOP_ITEMS } from "./game.js";
import { drawMakima } from "./sprites.js";

function dim(ctx, color = "rgba(4,3,8,0.74)") {
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, W, H);
}

function keyHints(ctx, bits, y) {
  ctx.save();
  ctx.globalAlpha = 0.75;
  text(ctx, bits, W / 2, y, { size: 6, color: PAL.bone2, align: "center", shadow: false });
  ctx.restore();
}

function sigil(ctx, x, y, signed, selected) {
  ctx.save();
  ctx.translate(x, y);
  const col = signed ? PAL.gold : selected ? PAL.blood2 : PAL.steel2;
  ctx.strokeStyle = col;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(0, 0, 6.5, 0, Math.PI * 2);
  ctx.stroke();
  if (signed) {
    px(ctx, -3, 0, 2, 2, PAL.gold);
    px(ctx, -1, 2, 2, 2, PAL.gold);
    px(ctx, 1, 0, 2, 2, PAL.gold);
    px(ctx, 3, -2, 2, 2, PAL.gold);
  } else {
    px(ctx, -2, -2, 2, 4, col);
    px(ctx, 1, -2, 2, 4, col);
  }
  ctx.restore();
}

export function drawContracts(ctx, game) {
  dim(ctx);
  const x = 50;
  const y = 24;
  const w = 380;
  const h = 224;
  panel(ctx, x, y, w, h, PAL.blood);

  text(ctx, "DEVIL CONTRACTS", x + 16, y + 11, { size: 15, color: PAL.bone, glow: 5, spacing: 1 });
  text(ctx, "POWER NOW. INTEREST FOREVER.", x + 16, y + 29, { size: 6, color: PAL.steel2, shadow: false, spacing: 1 });

  // wallet
  text(ctx, `${game.blood} BLOOD`, x + w - 16, y + 12, { size: 8, color: PAL.blood3, align: "right", glow: 2 });
  text(ctx, `DEBT ${game.debt}`, x + w - 16, y + 23, { size: 7, color: game.debt >= 50 ? PAL.blood2 : PAL.gold, align: "right" });

  const rowY = y + 44;
  CONTRACTS.forEach((item, i) => {
    const ry = rowY + i * 36;
    const selected = i === game.menuIndex;
    const signed = game.contracts.has(item.id);
    const afford = game.blood >= item.cost;
    if (selected) {
      ctx.fillStyle = "rgba(210,31,60,0.16)";
      ctx.fillRect(x + 10, ry - 2, w - 20, 32);
      px(ctx, x + 10, ry - 2, 2, 32, PAL.blood2);
    }
    sigil(ctx, x + 24, ry + 12, signed, selected);
    const nameCol = signed ? PAL.gold : selected ? PAL.bone : PAL.bone2;
    text(ctx, item.name, x + 38, ry, { size: 9, color: nameCol, glow: selected ? 2 : 0 });
    if (signed) {
      text(ctx, "SIGNED", x + w - 18, ry, { size: 7, color: PAL.gold, align: "right", glow: 2 });
    } else {
      const col = afford ? PAL.blood3 : PAL.blood;
      text(ctx, `${item.cost} BLOOD`, x + w - 18, ry, { size: 7, color: col, align: "right" });
      text(ctx, `DEBT +${item.debt}`, x + w - 18, ry + 11, { size: 6, color: PAL.gold2, align: "right", shadow: false });
    }
    text(ctx, item.desc, x + 38, ry + 12, { size: 6, color: signed ? PAL.steel2 : PAL.bone2, shadow: false });
    text(ctx, signed ? item.flavor : (item.id === "katana" && !signed ? "UNLOCKS A WEAPON" : ""), x + 38, ry + 21, {
      size: 6, color: signed ? "rgba(255,200,87,0.55)" : "rgba(242,230,216,0.36)", shadow: false,
    });
  });

  // footer message
  if (game.menuMessage) {
    text(ctx, game.menuMessage, x + 16, y + h - 27, { size: 7, color: PAL.gold, glow: 2 });
  } else {
    text(ctx, "↑ ↓  SELECT      ENTER  SIGN", x + 16, y + h - 27, { size: 7, color: PAL.bone2, shadow: false });
  }
  text(ctx, "ESC  CLOSE", x + w - 16, y + h - 27, { size: 7, color: PAL.steel2, align: "right", shadow: false });
  text(ctx, "Every contract is legally binding in Hell.", x + 16, y + h - 14, { size: 6, color: "rgba(242,230,216,0.3)", shadow: false });
}

export function drawShop(ctx, game) {
  dim(ctx);
  const x = 34;
  const y = 20;
  const w = 412;
  const h = 232;
  panel(ctx, x, y, w, h, PAL.gold2);

  text(ctx, "MAKIMA", x + 14, y + 10, { size: 14, color: PAL.bone, glow: 4, spacing: 2 });
  text(ctx, "PUBLIC SAFETY  ·  DEVIL HUNTER", x + 14, y + 27, { size: 6, color: PAL.steel2, shadow: false });
  text(ctx, `${game.blood} BLOOD`, x + w - 14, y + 12, { size: 8, color: PAL.blood3, align: "right", glow: 2 });

  // portrait
  ctx.save();
  ctx.translate(x + 10, y + 40);
  drawMakima(ctx, null, game.time, true);
  ctx.restore();
  ctx.strokeStyle = "rgba(255,200,87,0.28)";
  ctx.strokeRect(x + 13.5, y + 57.5, 78, 93);
  text(ctx, "“SIGN HERE.”", x + 18, y + 156, { size: 7, color: PAL.bone2, shadow: false });

  // items
  const listX = x + 108;
  const listW = w - 122;
  SHOP_ITEMS.forEach((item, i) => {
    const ry = y + 44 + i * 31;
    const selected = i === game.menuIndex;
    const sold = !item.repeat && game.shopBought.has(item.id);
    const afford = game.blood >= item.cost;
    if (selected) {
      ctx.fillStyle = "rgba(255,200,87,0.10)";
      ctx.fillRect(listX - 6, ry - 2, listW + 2, 28);
      px(ctx, listX - 6, ry - 2, 2, 28, PAL.gold);
    }
    text(ctx, item.name, listX, ry, {
      size: 8, color: sold ? PAL.steel2 : selected ? PAL.bone : PAL.bone2, glow: selected ? 1 : 0,
    });
    if (sold) {
      text(ctx, "SOLD OUT", listX + listW, ry, { size: 6, color: PAL.steel2, align: "right", shadow: false });
    } else {
      text(ctx, `${item.cost}`, listX + listW, ry, {
        size: 8, color: afford ? PAL.gold : PAL.rust, align: "right",
      });
      text(ctx, "BLOOD", listX + listW, ry + 8, { size: 5, color: PAL.steel2, align: "right", shadow: false });
    }
    text(ctx, item.desc, listX, ry + 11, { size: 6, color: sold ? "rgba(242,230,216,0.3)" : PAL.steel2, shadow: false });
  });

  if (game.menuMessage) {
    text(ctx, game.menuMessage, x + 14, y + h - 28, { size: 7, color: PAL.gold, glow: 2 });
  } else {
    text(ctx, "↑ ↓  SELECT      ENTER  BUY", x + 14, y + h - 28, { size: 7, color: PAL.bone2, shadow: false });
  }
  text(ctx, "ESC  LEAVE", x + w - 14, y + h - 28, { size: 7, color: PAL.steel2, align: "right", shadow: false });
  text(ctx, "Makima does not offer refunds. Neither does Hell.", x + 14, y + h - 14, { size: 6, color: "rgba(242,230,216,0.28)", shadow: false });
}

export function drawPause(ctx, game) {
  dim(ctx, "rgba(4,3,8,0.72)");
  const x = 88;
  const y = 36;
  const w = 304;
  const h = 200;
  panel(ctx, x, y, w, h, PAL.steel2);
  text(ctx, "PAUSED", x + w / 2, y + 12, { size: 18, color: PAL.bone, align: "center", glow: 5, spacing: 4 });
  text(ctx, "THE CHAINSAW CAN WAIT.", x + w / 2, y + 33, { size: 6, color: PAL.steel2, align: "center", shadow: false });

  const rows = [
    ["SECTOR", `${game.room.sector} — ${game.room.name}`],
    ["TIME", game.timeText],
    ["BLOOD", String(game.blood)],
    ["DEBT", String(game.debt)],
    ["KILLS / DEATHS", `${game.kills} / ${game.deaths}`],
    ["BEST CLEAR", game.bestText],
  ];
  rows.forEach(([k, v], i) => {
    const ry = y + 50 + i * 12;
    text(ctx, k, x + 20, ry, { size: 7, color: PAL.steel2, shadow: false });
    text(ctx, v, x + w - 20, ry, { size: 7, color: i === 3 ? PAL.gold : PAL.bone2, align: "right", shadow: false });
  });

  text(ctx, "A/D MOVE   SPACE JUMP   J ATTACK   K DASH", x + w / 2, y + 133, { size: 6, color: PAL.bone2, align: "center", shadow: false });
  text(ctx, "L FOX BITE   Q SWAP   E INTERACT   TAB CONTRACTS", x + w / 2, y + 145, { size: 6, color: PAL.bone2, align: "center", shadow: false });
  text(ctx, "M SOUND   ESC RESUME", x + w / 2, y + 161, { size: 7, color: PAL.gold, align: "center", glow: 2 });

  // pacts owned
  const owned = [...game.contracts];
  text(ctx, owned.length ? `PACTS: ${owned.map((id) => CONTRACTS.find((c) => c.id === id)?.name).join(" · ")}` : "NO PACTS SIGNED. YET.",
    x + w / 2, y + h - 16, { size: 5, color: "rgba(242,230,216,0.45)", align: "center", shadow: false });
}

export function drawDead(ctx, game) {
  const t = game.time;
  ctx.fillStyle = "rgba(10,2,6,0.82)";
  ctx.fillRect(0, 0, W, H);
  const g = ctx.createRadialGradient(W / 2, H / 2, 30, W / 2, H / 2, 300);
  g.addColorStop(0, "rgba(160,20,45,0.22)");
  g.addColorStop(1, "rgba(0,0,0,0.75)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // broken chains
  ctx.save();
  ctx.strokeStyle = "rgba(160,40,60,0.35)";
  ctx.lineWidth = 2;
  for (let i = 0; i < 2; i++) {
    const sx = i === 0 ? 76 : W - 76;
    for (let j = 0; j < 7; j++) {
      ctx.beginPath();
      ctx.ellipse(sx + Math.sin(t + j) * 2, 30 + j * 13, 2, 4, 0, 0, Math.PI * 2);
      ctx.stroke();
    }
  }
  ctx.restore();

  const shake = Math.sin(t * 20) * 0.6;
  text(ctx, "YOU DIED", W / 2 + 2, 58 + shake, { size: 38, color: PAL.rust, align: "center", glow: 10, spacing: 3 });
  text(ctx, "YOU DIED", W / 2, 56 + shake, { size: 38, color: PAL.blood2, align: "center", glow: 16, spacing: 3 });
  text(ctx, "THE DEBT OUTLIVES YOU.", W / 2, 104, { size: 8, color: PAL.bone2, align: "center", spacing: 2 });

  const cp = game.checkpoint;
  const roomName = game.rooms[cp.roomIndex]?.name || "UNKNOWN";
  text(ctx, `DEBT +3   BLOOD LOST 30%`, W / 2, 128, { size: 7, color: PAL.gold, align: "center", shadow: false });
  text(ctx, `LAST LAMP: ${roomName}`, W / 2, 140, { size: 6, color: PAL.steel2, align: "center", shadow: false });

  const blink = Math.sin(t * 4.5) > -0.3 ? 1 : 0.4;
  ctx.save();
  ctx.globalAlpha = blink;
  text(ctx, "ENTER — RISE AGAIN", W / 2, 174, { size: 10, color: PAL.bone, align: "center", glow: 4, spacing: 2 });
  ctx.restore();
  text(ctx, "ESC — ABANDON RUN", W / 2, 193, { size: 6, color: PAL.steel2, align: "center", shadow: false });

  text(ctx, `BLOOD ${game.blood}   ·   DEBT ${game.debt}   ·   KILLS ${game.kills}`, W / 2, 220, { size: 6, color: "rgba(242,230,216,0.4)", align: "center", shadow: false });
}

export function drawWin(ctx, game) {
  const t = game.time;
  ctx.fillStyle = "rgba(6,4,10,0.8)";
  ctx.fillRect(0, 0, W, H);
  // golden rays
  ctx.save();
  ctx.translate(W / 2, 100);
  ctx.globalCompositeOperation = "lighter";
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2 + t * 0.08;
    ctx.strokeStyle = i % 2 ? "rgba(255,200,87,0.10)" : "rgba(210,31,60,0.10)";
    ctx.lineWidth = i % 2 ? 2 : 1;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * 30, Math.sin(a) * 18);
    ctx.lineTo(Math.cos(a) * 320, Math.sin(a) * 220);
    ctx.stroke();
  }
  ctx.restore();

  const x = 50;
  const y = 24;
  const w = 380;
  const h = 224;
  panel(ctx, x, y, w, h, PAL.gold2);

  text(ctx, "DEBT COLLECTED", x + w / 2, y + 12, { size: 24, color: PAL.gold, align: "center", glow: 9, spacing: 2 });
  text(ctx, "THE DEBT DEVIL IS DEAD. THE PAPERWORK IS NOT.", x + w / 2, y + 40, { size: 6, color: PAL.bone2, align: "center", shadow: false });

  // rank
  const rank = game.rank;
  ctx.save();
  ctx.strokeStyle = "rgba(255,200,87,0.4)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(x + w - 56, y + 82, 28, 0, Math.PI * 2);
  ctx.stroke();
  ctx.globalAlpha = 0.5;
  ctx.beginPath();
  ctx.arc(x + w - 56, y + 82, 23, 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();
  text(ctx, rank, x + w - 56, y + 58, { size: 34, color: PAL.gold, align: "center", glow: 10 });
  text(ctx, "RANK", x + w - 56, y + 97, { size: 5, color: PAL.steel2, align: "center", shadow: false });

  const stats = [
    ["CLEAR TIME", game.timeText],
    ["BLOOD", String(game.blood)],
    ["DEBT", String(game.debt)],
    ["KILLS", String(game.kills)],
    ["DEATHS", String(game.deaths)],
    ["PACTS", `${game.contracts.size} / ${CONTRACTS.length}`],
  ];
  stats.forEach(([k, v], i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const sx = x + 18 + col * 136;
    const sy = y + 64 + row * 22;
    text(ctx, k, sx, sy, { size: 6, color: PAL.steel2, shadow: false });
    text(ctx, v, sx, sy + 8, { size: 10, color: i === 2 ? (game.debt > 40 ? PAL.blood2 : PAL.gold) : PAL.bone, glow: 1 });
  });

  text(ctx, game.rankFlavor, x + w / 2, y + 140, { size: 7, color: PAL.gold2, align: "center", shadow: false });
  const newBest = game.best && Math.abs(game.best - game.elapsed) < 0.01;
  text(ctx, newBest ? "NEW BEST TIME" : `BEST  ${game.bestText}`, x + w / 2, y + 153, {
    size: 7, color: newBest ? PAL.gold : PAL.steel2, align: "center", glow: newBest ? 3 : 0,
  });

  const blink = Math.sin(t * 4.2) > -0.2 ? 1 : 0.4;
  ctx.save();
  ctx.globalAlpha = blink;
  text(ctx, "ENTER — SIGN ANOTHER CONTRACT", x + w / 2, y + 174, { size: 9, color: PAL.bone, align: "center", glow: 4 });
  ctx.restore();
  text(ctx, "ESC — TITLE", x + w / 2, y + 192, { size: 6, color: PAL.steel2, align: "center", shadow: false });
  text(ctx, "THE HOUSE ALWAYS WINS. UNTIL IT DOESN'T.", x + w / 2, y + h - 13, { size: 5, color: "rgba(242,230,216,0.3)", align: "center", shadow: false });
}

import { W, H, PAL, clamp, rand } from "./util.js";
import {
  drawBackground, drawTerrain, drawProps, drawForeground,
} from "./render-bg.js";
import {
  drawPlayer, drawZombie, drawBat, drawKatana, drawCollector, drawBoss,
} from "./sprites.js";
import {
  text, px, drawHud, drawWorldUi, drawBanner, drawTitle,
} from "./render-ui.js";
import {
  drawContracts, drawShop, drawPause, drawDead, drawWin,
} from "./render-menus.js";

export function render(ctx, game) {
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, W, H);

  let sx = 0;
  let sy = 0;
  if (game.shakeTime > 0) {
    const m = game.shakeMag * Math.min(1, game.shakeTime * 5);
    sx = (Math.random() * 2 - 1) * m;
    sy = (Math.random() * 2 - 1) * m * 0.6;
  }

  ctx.save();
  ctx.translate(Math.round(sx), Math.round(sy));
  if (game.mode === "title") drawTitleScene(ctx, game);
  else drawWorld(ctx, game);
  ctx.restore();

  // HUD and world prompts stay steady.
  if (game.mode !== "title" && game.player) {
    drawHud(ctx, game);
    drawWorldUi(ctx, game);
    drawBanner(ctx, game);
  }

  // fade / flash / full-screen overlays
  if (game.fade > 0) {
    ctx.fillStyle = `rgba(4,3,8,${clamp(game.fade, 0, 1)})`;
    ctx.fillRect(0, 0, W, H);
  }
  if (game.flashTime > 0) {
    ctx.save();
    ctx.globalAlpha = clamp(game.flashTime * 1.8, 0, 0.65);
    ctx.fillStyle = game.flashColor;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
  }

  if (game.mode === "contracts") drawContracts(ctx, game);
  else if (game.mode === "shop") drawShop(ctx, game);
  else if (game.mode === "pause") drawPause(ctx, game);
  else if (game.mode === "dead") drawDead(ctx, game);
  else if (game.mode === "win") drawWin(ctx, game);
  else if (game.mode === "title") drawTitle(ctx, game);

  if (game.mode === "play" && game.menuMessageTime > 0 && game.menuMessage) {
    ctx.save();
    ctx.globalAlpha = clamp(game.menuMessageTime * 2, 0, 1);
    text(ctx, game.menuMessage, W / 2, 52, { size: 7, color: PAL.gold, align: "center", glow: 3 });
    ctx.restore();
  }
}

function drawTitleScene(ctx, game) {
  const oldX = game.camera.x;
  game.camera.x = 250 + Math.sin(game.titleTime * 0.08) * 160;
  drawBackground(ctx, game);
  game.camera.x = oldX;

  // low rooftop foreground
  ctx.save();
  ctx.fillStyle = "#07050b";
  ctx.fillRect(0, 244, W, H - 244);
  ctx.fillStyle = "#191222";
  ctx.fillRect(0, 244, W, 3);
  ctx.fillStyle = "#2a2132";
  ctx.fillRect(0, 244, W, 1);
  // vents and parapet details
  for (let i = 0; i < 7; i++) {
    const x = 24 + i * 71;
    px(ctx, x, 232, 18, 12, "#0a0810");
    px(ctx, x + 2, 234, 14, 2, "#211a2a");
    px(ctx, x + 2, 239, 14, 1, "#120e18");
  }
  // hanging chain
  ctx.strokeStyle = "rgba(100,85,110,0.5)";
  ctx.lineWidth = 2;
  for (let i = 0; i < 9; i++) {
    ctx.beginPath();
    ctx.ellipse(431 + Math.sin(game.titleTime * 0.8 + i * 0.3) * 2, 4 + i * 8, 2, 4, 0, 0, Math.PI * 2);
    ctx.stroke();
  }
  // hero silhouette
  const fake = {
    x: 0, y: -20, w: 12, h: 20, facing: -1, onGround: true,
    animTime: game.titleTime, vx: 0, attackTimer: 0, attackDur: 1,
    attackIndex: 0, weapon: "chainsaw", dashTimer: 0, invuln: 0,
  };
  ctx.save();
  ctx.translate(424, 246);
  ctx.scale(2, 2);
  drawPlayer(ctx, fake, game.titleTime, game);
  ctx.restore();
  // red rim light
  const rim = ctx.createRadialGradient(424, 230, 4, 424, 230, 60);
  rim.addColorStop(0, "rgba(255,59,82,0.16)");
  rim.addColorStop(1, "rgba(255,59,82,0)");
  ctx.fillStyle = rim;
  ctx.fillRect(360, 170, 130, 100);
  ctx.restore();
}

function drawWorld(ctx, game) {
  const cam = game.camera.x;
  drawBackground(ctx, game);

  ctx.save();
  ctx.translate(-Math.round(cam), 0);

  drawTerrain(ctx, game);
  drawProps(ctx, game, true);
  drawWarnings(ctx, game);

  // pickups behind actors
  for (const p of game.pickups) drawPickup(ctx, p, game.time);
  for (const e of game.effects) if (e.type === "afterimage") drawEffect(ctx, e, game);
  for (const e of game.effects) if (e.type === "portal" || e.type === "dash") drawEffect(ctx, e, game);

  for (const e of game.enemies) {
    if (e.dead) continue;
    drawEnemy(ctx, e, game);
  }
  if (game.boss && !game.boss.dead) drawBoss(ctx, game.boss, game.time, game.player);

  if (game.player && !game.player.dead) {
    drawPlayer(ctx, game.player, game.time, game);
  }

  for (const pr of game.projectiles) drawProjectile(ctx, pr, game.time);

  for (const e of game.effects) {
    if (e.type === "fox" || e.type === "explosion" || e.type === "death" || e.type === "doublejump" || e.type === "muzzle") {
      drawEffect(ctx, e, game);
    }
  }

  drawParticles(ctx, game);
  drawTexts(ctx, game);
  ctx.restore();

  drawForeground(ctx, game);

  // screen-space beam? world warning
  if (game.boss && game.boss.state === "beam") {
    drawBeam(ctx, game);
  }
}

function drawEnemy(ctx, e, game) {
  const t = game.time;
  if (e.flash > 0) {
    // small hit flash aura
    ctx.save();
    ctx.globalAlpha = 0.25;
    ctx.fillStyle = PAL.white;
    ctx.fillRect(e.x - 2, e.y - 2, e.w + 4, e.h + 4);
    ctx.restore();
  }
  if (e.type === "zombie") drawZombie(ctx, e, t);
  else if (e.type === "bat") drawBat(ctx, e, t);
  else if (e.type === "katana") drawKatana(ctx, e, t);
  else if (e.type === "collector") drawCollector(ctx, e, t);

  // tiny hp bar for tough enemies
  if (e.hp < e.maxHp && (e.type === "katana" || e.type === "collector")) {
    const w = 20;
    px(ctx, e.centerX - w / 2, e.y - 7, w, 2, "#170c12");
    px(ctx, e.centerX - w / 2, e.y - 7, (e.hp / e.maxHp) * w, 2, PAL.blood2);
  }
}

function drawPickup(ctx, p, t) {
  const bob = Math.sin(t * 5 + p.phase) * 1.5;
  if (p.type === "heart") {
    ctx.save();
    ctx.translate(p.x, p.y + bob);
    ctx.globalAlpha = 0.35;
    ctx.fillStyle = PAL.blood2;
    ctx.beginPath();
    ctx.arc(2, 2, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
    px(ctx, 0, 0, 5, 2, PAL.blood2);
    px(ctx, 0, 2, 5, 3, PAL.blood);
    px(ctx, 1, 5, 3, 1, PAL.rust);
    px(ctx, 1, 0, 1, 1, PAL.blood3);
    ctx.restore();
    return;
  }
  ctx.save();
  ctx.translate(p.x, p.y + bob);
  ctx.globalAlpha = 0.35;
  ctx.fillStyle = PAL.blood;
  ctx.beginPath();
  ctx.arc(2, 3, 6 + Math.sin(t * 7 + p.phase) * 1, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
  px(ctx, 1, 0, 2, 2, PAL.blood2);
  px(ctx, 0, 2, 4, 3, PAL.blood);
  px(ctx, 1, 5, 2, 1, PAL.rust);
  ctx.restore();
}

function drawProjectile(ctx, pr, t) {
  if (pr.type === "pellet") {
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = 0.7;
    ctx.fillStyle = PAL.gold;
    ctx.fillRect(pr.x - Math.sign(pr.vx) * 8, pr.y + 1, 10, 1);
    ctx.globalAlpha = 1;
    px(ctx, pr.x, pr.y, 7, 3, PAL.gold);
    px(ctx, pr.x + 2, pr.y + 1, 3, 1, PAL.white);
    ctx.restore();
  } else if (pr.type === "wave") {
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = 0.8;
    ctx.strokeStyle = PAL.bone;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(pr.x, pr.y + 8, 12, -1.1, 1.1);
    ctx.stroke();
    ctx.globalAlpha = 0.5;
    ctx.strokeStyle = PAL.blood2;
    ctx.beginPath();
    ctx.arc(pr.x, pr.y + 8, 8, -1.0, 1.0);
    ctx.stroke();
    ctx.restore();
  } else {
    const flip = Math.floor(t * 10 + pr.x) % 2 === 0;
    ctx.save();
    if (pr.type === "bossCoin") {
      ctx.globalAlpha = 0.25;
      ctx.fillStyle = PAL.blood2;
      ctx.beginPath();
      ctx.arc(pr.x + 3, pr.y + 3, 8, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    px(ctx, pr.x, pr.y, 6, 6, PAL.gold2);
    px(ctx, pr.x + 1, pr.y + 1, 4, 4, PAL.gold);
    if (flip) px(ctx, pr.x + 2, pr.y + 2, 1, 2, PAL.gold2);
    ctx.restore();
  }
}

function drawWarnings(ctx, game) {
  for (const w of game.warnings) {
    const a = 0.3 + Math.abs(Math.sin((w.t + w.dur) * 12)) * 0.5;
    ctx.save();
    ctx.globalAlpha = a;
    if (w.type === "beam") {
      ctx.fillStyle = PAL.blood;
      ctx.fillRect(w.x, w.y + w.h - 3, w.w, 3);
      for (let x = 0; x < w.w; x += 16) {
        ctx.fillStyle = PAL.blood2;
        ctx.fillRect(w.x + x, w.y + w.h - 5, 8, 2);
      }
      text(ctx, "! ! !", game.player.centerX, w.y - 10, { size: 7, color: PAL.blood2, align: "center", glow: 4 });
    } else {
      ctx.strokeStyle = PAL.gold;
      ctx.beginPath();
      ctx.ellipse(w.x + w.w / 2, w.y + w.h, w.w / 2, 3, 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.fillStyle = PAL.blood2;
      ctx.fillRect(w.x + w.w / 2 - 1, w.y, 2, w.h);
    }
    ctx.restore();
  }
}

function drawBeam(ctx, game) {
  const b = game.boss;
  if (!b) return;
  const y = game.room.ground - 18;
  const a = 0.65 + Math.sin(game.time * 40) * 0.2;
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  ctx.globalAlpha = a;
  const g = ctx.createLinearGradient(0, y, 0, y + 18);
  g.addColorStop(0, "rgba(255,59,82,0.9)");
  g.addColorStop(0.5, "rgba(255,200,87,0.9)");
  g.addColorStop(1, "rgba(255,59,82,0.85)");
  ctx.fillStyle = g;
  ctx.fillRect(0, y, W, 18);
  ctx.globalAlpha = 0.5;
  ctx.fillStyle = PAL.white;
  ctx.fillRect(0, y + 7, W, 4);
  ctx.globalAlpha = 0.35;
  for (let i = 0; i < 20; i++) {
    const x = (i * 41 + game.time * 200) % W;
    ctx.fillRect(x, y - 4 + Math.random() * 26, 2, 1);
  }
  ctx.restore();
}

function drawEffect(ctx, e, game) {
  if (e.type === "afterimage") {
    ctx.save();
    ctx.globalAlpha = (1 - e.t / e.dur) * 0.35;
    const fake = {
      x: e.x, y: e.y, w: 12, h: 20, facing: e.facing, onGround: true,
      animTime: game.time, vx: 0, attackTimer: 0, attackDur: 1, attackIndex: 0,
      weapon: "chainsaw", dashTimer: 0, invuln: 0,
    };
    drawPlayer(ctx, fake, game.time, game);
    ctx.restore();
  } else if (e.type === "dash") {
    ctx.save();
    ctx.globalAlpha = 0.5 * (1 - e.t / e.dur);
    ctx.strokeStyle = PAL.blood2;
    ctx.lineWidth = 1;
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      ctx.moveTo(e.x + (e.facing > 0 ? -14 - i * 5 : 14 + i * 5), e.y - 6 + i * 3);
      ctx.lineTo(e.x + (e.facing > 0 ? -30 - i * 7 : 30 + i * 7), e.y - 6 + i * 3);
      ctx.stroke();
    }
    ctx.restore();
  } else if (e.type === "portal") {
    ctx.save();
    ctx.globalAlpha = 1 - e.t / e.dur;
    ctx.strokeStyle = PAL.blood2;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(e.x, e.y, 10 + e.t * 40, 20 + e.t * 50, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  } else if (e.type === "doublejump") {
    ctx.save();
    ctx.globalAlpha = 1 - e.t / e.dur;
    ctx.strokeStyle = PAL.blood2;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.ellipse(e.x, e.y, 9 + e.t * 26, 3 + e.t * 5, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  } else if (e.type === "explosion") {
    const k = e.t / e.dur;
    ctx.save();
    ctx.globalAlpha = 1 - k;
    ctx.globalCompositeOperation = "lighter";
    ctx.strokeStyle = PAL.blood2;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(e.x, e.y, 4 + k * 20, 0, Math.PI * 2);
    ctx.stroke();
    ctx.strokeStyle = PAL.gold;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(e.x, e.y, 2 + k * 13, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  } else if (e.type === "death") {
    const k = e.t / e.dur;
    ctx.save();
    ctx.globalAlpha = (1 - k) * 0.6;
    ctx.fillStyle = PAL.blood;
    ctx.beginPath();
    ctx.ellipse(e.x, e.y, 8 + k * 18, 5 + k * 10, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  } else if (e.type === "fox") {
    drawFox(ctx, e);
  } else if (e.type === "muzzle") {
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.globalAlpha = 1 - e.t / e.dur;
    ctx.fillStyle = PAL.gold;
    ctx.beginPath();
    ctx.arc(e.x, e.y, 7, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
}

function drawFox(ctx, e) {
  const k = e.t / e.dur;
  const open = Math.sin(Math.min(1, k * 1.6) * Math.PI) * 22;
  ctx.save();
  ctx.translate(e.x, e.y);
  if (e.facing < 0) ctx.scale(-1, 1);
  ctx.globalAlpha = 1 - Math.max(0, k - 0.7) / 0.3;
  // fox head jaw
  ctx.fillStyle = "rgba(255,59,82,0.16)";
  ctx.beginPath();
  ctx.ellipse(4, 8, 44, 40 + open, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = PAL.bone;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-10, 8 - open);
  ctx.quadraticCurveTo(30, -18 - open, 56, 4 - open);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(-10, 8 + open);
  ctx.quadraticCurveTo(30, 30 + open, 56, 8 + open);
  ctx.stroke();
  // teeth
  ctx.fillStyle = PAL.bone;
  for (let i = 0; i < 5; i++) {
    const x = 4 + i * 10;
    ctx.beginPath();
    ctx.moveTo(x, 7 - open);
    ctx.lineTo(x + 4, 14 - open);
    ctx.lineTo(x + 8, 7 - open);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(x, 9 + open);
    ctx.lineTo(x + 4, 2 + open);
    ctx.lineTo(x + 8, 9 + open);
    ctx.fill();
  }
  // eye
  ctx.fillStyle = PAL.gold;
  ctx.fillRect(22, -8 - open * 0.3, 4, 2);
  ctx.fillStyle = PAL.blood2;
  ctx.fillRect(12, 10, 40, 2);
  ctx.restore();
}

function drawParticles(ctx, game) {
  for (const p of game.particles) {
    const a = clamp(p.life / p.maxLife, 0, 1);
    ctx.save();
    ctx.globalAlpha = a;
    if (p.type === "spark") ctx.globalCompositeOperation = "lighter";
    ctx.fillStyle = p.color;
    ctx.fillRect(Math.round(p.x), Math.round(p.y), p.size, p.size);
    if (p.type === "blood" && p.size > 1) {
      ctx.globalAlpha = a * 0.5;
      ctx.fillRect(Math.round(p.x) + 1, Math.round(p.y) + 2, 1, 1);
    }
    ctx.restore();
  }
}

function drawTexts(ctx, game) {
  for (const t of game.texts) {
    const a = clamp((t.dur - t.t) * 3, 0, 1);
    ctx.save();
    ctx.globalAlpha = a;
    text(ctx, t.text, t.x, t.y - t.t * 18, {
      size: 6 * t.size, color: t.color, align: "center", glow: 2, shadow: true,
    });
    ctx.restore();
  }
}

import { W, H, clamp } from "./util.js";
import { Input, installTouchControls } from "./input.js";
import { Sfx } from "./audio.js";
import { Game } from "./game.js";
import { render } from "./render.js";

const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d", { alpha: false });
ctx.imageSmoothingEnabled = false;

const frame = document.getElementById("frame");
const boot = document.getElementById("boot");
const input = new Input();
const sfx = new Sfx();
const game = new Game(input, sfx);
installTouchControls(input);

function resize() {
  const pad = innerWidth < 640 ? 0 : 24;
  const scale = Math.min((innerWidth - pad) / W, (innerHeight - pad) / H);
  const w = Math.max(320, Math.floor(W * scale));
  const h = Math.max(181, Math.floor(H * scale));
  frame.style.width = `${w}px`;
  frame.style.height = `${h}px`;
  canvas.style.width = `${w}px`;
  canvas.style.height = `${h}px`;
}
addEventListener("resize", resize);
resize();

let last = performance.now();
let booted = false;
function loop(now) {
  const dt = clamp((now - last) / 1000, 0, 0.05);
  last = now;
  try {
    game.update(dt);
    render(ctx, game);
    input.endFrame();
  } catch (err) {
    console.error(err);
  }
  if (!booted) {
    booted = true;
    setTimeout(() => boot.classList.add("hidden"), 350);
  }
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

