352:   updateContracts(dt) {
353:     const items = CONTRACTS;
354:     if (this.input.pressed("back") || this.input.pressed("contracts")) { this.mode = "play"; return; }
355:     if (this.input.pressed("up")) { this.menuIndex = (this.menuIndex - 1 + items.length) % items.length; this.sfx.click(); }
356:     if (this.input.pressed("down")) { this.menuIndex = (this.menuIndex + 1) % items.length; this.sfx.click(); }
357:     if (this.input.pressed("confirm") || this.input.pressed("interact") || this.input.pressed("attack")) {
358:       this.signContract(items[this.menuIndex]);
359:     }
360:     this.updateParticles(dt * 0.4);
361:   }
362: 
363:   signContract(item) {
364:     if (this.contracts.has(item.id)) {
365:       this.menuMessage = "ALREADY SIGNED.";
366:       this.menuMessageTime = 1.4;
367:       this.sfx.deny();
368:       return;
369:     }
370:     if (this.blood < item.cost) {
371:       this.menuMessage = `NOT ENOUGH BLOOD — NEED ${item.cost}`;
372:       this.menuMessageTime = 1.6;
373:       this.sfx.deny();
374:       this.shake(2, 0.12);
375:       return;
376:     }
377:     this.blood -= item.cost;
378:     this.debt = Math.min(99, this.debt + item.debt);
379:     this.contracts.add(item.id);
380:     if (item.id === "katana") {
381:       this.weapons.add("katana");
382:       this.player.weapon = "katana";
383:     }
384:     this.sfx.contract();
385:     this.flashScreen(0.35, PAL.blood);
386:     this.shake(4, 0.3);
387:     this.spawnBlood(this.player.centerX, this.player.centerY, 20, PAL.blood2);
388:     this.menuMessage = `${item.name} SIGNED. DEBT +${item.debt}.`;
389:     this.menuMessageTime = 2;
390:     this.checkCollector();
391:   }
