400:   updateShop(dt) {
401:     const items = SHOP_ITEMS;
402:     if (this.input.pressed("back") || this.input.pressed("interact")) { this.mode = "play"; return; }
403:     if (this.input.pressed("up")) { this.menuIndex = (this.menuIndex - 1 + items.length) % items.length; this.sfx.click(); }
404:     if (this.input.pressed("down")) { this.menuIndex = (this.menuIndex + 1) % items.length; this.sfx.click(); }
405:     if (this.input.pressed("confirm") || this.input.pressed("attack")) this.buy(items[this.menuIndex]);
406:     this.updateParticles(dt * 0.4);
407:   }
408: 
409:   buy(item) {
410:     const sold = !item.repeat && this.shopBought.has(item.id);
411:     if (sold) {
412:       this.menuMessage = "SOLD OUT.";
413:       this.menuMessageTime = 1.2;
414:       this.sfx.deny();
415:       return;
416:     }
417:     if (item.id === "heal" && this.player.hp >= this.player.maxHp) {
418:       this.menuMessage = "YOU'RE ALREADY STITCHED.";
419:       this.menuMessageTime = 1.4;
420:       this.sfx.deny();
421:       return;
422:     }
423:     if (item.id === "debt" && this.debt <= 0) {
424:       this.menuMessage = "NO DEBT. SUSPICIOUS.";
425:       this.menuMessageTime = 1.4;
426:       this.sfx.deny();
427:       return;
428:     }
429:     if (this.blood < item.cost) {
430:       this.menuMessage = `NOT ENOUGH BLOOD — NEED ${item.cost}`;
431:       this.menuMessageTime = 1.5;
432:       this.sfx.deny();
433:       return;
434:     }
435:     this.blood -= item.cost;
436:     if (!item.repeat) this.shopBought.add(item.id);
437:     if (item.id === "shotgun") {
438:       this.weapons.add("shotgun");
439:       this.player.weapon = "shotgun";
440:       this.player.ammo = 6;
441:     } else if (item.id === "heart") {
442:       this.player.maxHp++;
443:       this.player.hp = this.player.maxHp;
444:     } else if (item.id === "tune") {
445:       this.upgrades++;
446:     } else if (item.id === "debt") {
447:       this.debt = Math.max(0, this.debt - 10);
448:     } else if (item.id === "heal") {
449:       this.player.heal(2);
450:     }
451:     this.sfx.coin();
452:     this.sfx.pickup();
453:     this.menuMessage = `${item.name} — DONE.`;
454:     this.menuMessageTime = 1.8;
455:     this.spawnSpark(this.player.centerX, this.player.centerY, 8);
456:   }
457: 
458:   findInteractable() {
459:     const p = this.player;
460:     const px = p.centerX;
461:     let best = null;
462:     let bestD = 30;
463:     for (const cp of this.room.checkpoints) {
464:       const d = Math.abs(px - cp.x) + Math.abs(p.y + p.h - cp.y) * 0.35;
465:       if (d < bestD) { best = { type: "checkpoint", x: cp.x, y: cp.y, label: "REST  [E]" }; bestD = d; }
466:     }
467:     for (const a of this.room.altars) {
468:       const d = Math.abs(px - a.x) + Math.abs(p.y + p.h - a.y) * 0.35;
469:       if (d < bestD) { best = { type: "altar", x: a.x, y: a.y, label: "DEVIL CONTRACTS  [E]" }; bestD = d; }
470:     }
471:     for (const n of this.room.npcs) {
472:       const d = Math.abs(px - n.x) + Math.abs(p.y + p.h - n.y) * 0.35;
473:       if (d < bestD) { best = { type: "npc", x: n.x, y: n.y, label: "MAKIMA  [E]" }; bestD = d; }
474:     }
475:     for (const door of this.room.doors) {
476:       const d = Math.abs(px - door.x) + Math.abs(p.y + p.h - door.y) * 0.35;
477:       if (d < bestD) { best = { type: "door", x: door.x, y: door.y, to: door.to, label: `${door.label}  [E]` }; bestD = d; }
478:     }
479:     return best;
480:   }
481: 
482:   interact(it) {
483:     if (it.type === "checkpoint") {
484:       this.checkpoint = { roomIndex: this.roomIndex, x: it.x, y: it.y };
485:       this.player.heal(this.player.maxHp);
486:       this.sfx.checkpoint();
487:       this.spawnSpark(it.x, it.y - 30, 14);
488:       this.addText(it.x, it.y - 44, "CHECKPOINT", PAL.gold, 1.4);
489:       if (this.room.boss && !this.bossDefeated) {
490:         this.boss = new Boss(this.room.width / 2, this.room.ground);
491:       }
492:       this.enemies = this.room.enemies.map((d) => createEnemy({ ...d }));
493:       this.fade = 0.25;
494:     } else if (it.type === "altar") {
495:       this.openContracts();
496:     } else if (it.type === "npc") {
497:       this.mode = "shop";
498:       this.menuIndex = 0;
499:       this.menuMessage = "";
500:       this.sfx.click();
501:     } else if (it.type === "door") {
502:       this.fade = 0.8;
503:       this.loadRoom(it.to);
504:     }
505:   }
