563:   addEffect(e) {
564:     e.t = e.t || 0;
565:     e.dur = e.dur || 0.3;
566:     this.effects.push(e);
567:   }
568: 
569:   spawnWarning(x, y, w, h, dur, type = "coin") {
570:     this.warnings.push({ x, y, w, h, t: 0, dur, type });
571:   }
572: 
573:   shake(mag, time) {
574:     this.shakeMag = Math.max(this.shakeMag, mag);
575:     this.shakeTime = Math.max(this.shakeTime, time);
576:   }
