583:   meleeHit(player) {
584:     const weapon = player.weapon;
585:     if (weapon === "shotgun") return;
586:     const heavy = player.attackIndex === 2;
587:     let range = weapon === "katana" ? 43 : 31 + player.attackIndex * 3;
588:     if (heavy) range += 4;
589:     let damage = weapon === "katana"
590:       ? (heavy ? 26 : 17)
591:       : (heavy ? 16 : 9);
592:     damage += this.upgrades * 5;
593:     const box = {
594:       x: player.facing > 0 ? player.x + player.w - 2 : player.x - range + 2,
595:       y: player.y + 1,
596:       w: range,
597:       h: 19,
598:     };
599:     let hits = 0;
600:     for (const e of this.enemies) {
601:       if (e.dead || !overlap(box, e.rect)) continue;
602:       e.hurt(damage, this, player.facing);
603:       hits++;
604:     }
605:     if (this.boss && !this.boss.dead && overlap(box, this.boss.rect)) {
606:       this.boss.hurt(damage, this);
607:       hits++;
608:     }
609:     for (const pr of this.projectiles) {
610:       if (!pr.friendly && overlap(box, pr.rect)) {
611:         pr.dead = true;
612:         this.spawnSpark(pr.x, pr.y, 3);
613:       }
614:     }
615:     if (hits) {
616:       this.sfx.hit();
617:       this.hitstop = 0.045;
618:       this.shake(weapon === "katana" ? 3 : 2, 0.1);
619:       this.spawnSpark(box.x + box.w * 0.6, box.y + 8, 3);
620:     }
621:   }
622: 
623:   fireShotgun(player) {
624:     const x = player.centerX + player.facing * 10;
625:     const y = player.y + 9;
626:     for (let i = -1; i <= 1; i++) {
627:       this.projectiles.push(new Projectile({
628:         x, y: y + i * 1.5,
629:         vx: player.facing * 430,
630:         vy: i * 26,
631:         type: "pellet", friendly: true, life: 0.5,
632:       }));
633:     }
634:     for (let i = 0; i < 8; i++) {
635:       this.spawnParticle(
636:         x, y,
637:         player.facing * rand(60, 220), rand(-60, 60),
638:         rand(0.08, 0.22), Math.random() < 0.5 ? PAL.gold : PAL.white,
639:         1, 0, "spark"
640:       );
641:     }
642:     this.addEffect({ type: "muzzle", x, y, facing: player.facing, t: 0, dur: 0.1 });
643:   }
644: 
645:   slashWave(player) {
646:     if (player.attackIndex !== 2) return;
647:     this.projectiles.push(new Projectile({
648:       x: player.centerX + player.facing * 16,
649:       y: player.y + 2,
650:       vx: player.facing * 300,
651:       vy: 0,
652:       type: "wave", friendly: true, life: 0.55,
653:     }));
654:    }
655: 
656:   foxBite(player) {
