238:   px(ctx, 2 - walk, 0, 4, 1, PAL.ink);
239: 
240:   // torso hunched
241:   px(ctx, -5, -14, 10, 9, PAL.ink);
242:   px(ctx, -4, -14, 9, 8, suit);
243:   px(ctx, -4, -12, 2, 2, flash ? PAL.white : PAL.blood);
244:   px(ctx, 2, -11, 2, 1, PAL.ink);
245: 
246:   // arms
247:   px(ctx, 4, -13, 7, 2, suit);
248:   px(ctx, 10, -13, 3, 2, skin);
249:   px(ctx, -5, -13, 2, 5, suit);
250: 
251:   // head
252:   px(ctx, -2, -20, 9, 7, PAL.ink);
253:   px(ctx, -1, -19, 7, 6, skin);
254:   px(ctx, -2, -20, 3, 2, skin);
255:   px(ctx, 2, -20, 4, 2, skin);
256:   px(ctx, 1, -18, 2, 2, PAL.ink);
