610: export function drawAltar(ctx, altar, t, active) {
611:   const x = Math.round(altar.x);
612:   const y = Math.round(altar.y);
613:   ctx.save();
614:   // stone slab
615:   px(ctx, x - 14, y - 12, 28, 12, PAL.ink);
616:   px(ctx, x - 13, y - 11, 26, 9, "#2a2032");
617:   px(ctx, x - 12, y - 12, 24, 2, "#4a3d58");
618:   px(ctx, x - 10, y - 4, 3, 2, "#1a1420");
619:   px(ctx, x + 6, y - 5, 3, 2, "#1a1420");
620:   // candles
621:   for (const ox of [-9, -2, 8]) {
622:     px(ctx, x + ox, y - 20, 2, 8, PAL.bone2);
623:     const f = Math.sin(t * 9 + ox) * 1;
624:     px(ctx, x + ox, y - 24 - f, 2, 4, PAL.gold);
625:     px(ctx, x + ox, y - 23 - f, 1, 2, PAL.white);
626:   }
627:   // floating scroll
628:   px(ctx, x - 8, y - 30 + Math.sin(t * 2) * 1, 16, 10, PAL.ink);
629:   px(ctx, x - 7, y - 29 + Math.sin(t * 2) * 1, 14, 8, PAL.bone2);
630:   px(ctx, x - 5, y - 27 + Math.sin(t * 2) * 1, 10, 1, PAL.rust);
631:   px(ctx, x - 5, y - 24 + Math.sin(t * 2) * 1, 7, 1, PAL.rust);
632:   // red seal
633:   px(ctx, x + 4, y - 27 + Math.sin(t * 2) * 1, 3, 3, PAL.blood);
634:   // aura
635:   ctx.globalCompositeOperation = "lighter";
636:   ctx.globalAlpha = active ? 0.32 : 0.16;
637:   ctx.fillStyle = PAL.blood;
638:   ctx.beginPath();
639:   ctx.ellipse(x, y - 16, 20, 20, 0, 0, Math.PI * 2);
640:   ctx.fill();
641:   ctx.restore();
