6: export function text(ctx, str, x, y, o = {}) {
7:   const {
8:     size = 8, color = PAL.bone, align = "left", weight = 700,
9:     shadow = true, glow = 0, alpha = 1, baseline = "top", spacing = 0,
10:   } = o;
11:   ctx.save();
12:   ctx.globalAlpha = alpha;
