14:   ctx.textBaseline = baseline;
15:   ctx.textAlign = align;
16:   if (shadow) {
17:     ctx.fillStyle = "rgba(0,0,0,0.8)";
18:     ctx.fillText(str, x + 1, y + 1);
19:   }
20:   if (glow) {
21:     ctx.shadowColor = color;
22:     ctx.shadowBlur = glow;
23:   }
24:   ctx.fillStyle = color;
25:   if (spacing) {
26:     const chars = [...str];
27:     const widths = chars.map((c) => ctx.measureText(c).width + spacing);
28:     const total = widths.reduce((a, b) => a + b, 0) - spacing;
29:     let cx = align === "center" ? x - total / 2 : align === "right" ? x - total : x;
30:     ctx.textAlign = "left";
31:     chars.forEach((c, i) => {
32:       ctx.fillText(c, cx, y);
33:       cx += widths[i];
34:     });
35:   } else {
36:     ctx.fillText(str, x, y);
37:   }
38:   ctx.restore();
39: }
