50:   ctx.strokeStyle = "rgba(242,230,216,0.16)";
51:   ctx.lineWidth = 1;
52:   ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
53:   // corner brackets
54:   ctx.strokeStyle = accent;
55:   ctx.lineWidth = 1;
56:   const c = 8;
57:   ctx.beginPath();
58:   ctx.moveTo(x, y + c); ctx.lineTo(x, y); ctx.lineTo(x + c, y);
59:   ctx.moveTo(x + w - c, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + c);
60:   ctx.moveTo(x, y + h - c); ctx.lineTo(x, y + h); ctx.lineTo(x + c, y + h);
61:   ctx.moveTo(x + w - c, y + h); ctx.lineTo(x + w, y + h); ctx.lineTo(x + w, y + h - c);
62:   ctx.stroke();
