281: function walkerPhysics(e, dt, room) {
282:   const prevBottom = e.y + e.h;
283:   e.x += e.vx * dt;
284:   for (const s of solidsFor(room)) {
285:     if (!overlap(e, s)) continue;
286:     if (e.vx > 0) e.x = s.x - e.w;
287:     else if (e.vx < 0) e.x = s.x + s.w;
288:     e.vx = 0;
289:   }
290:   e.vy = Math.min(e.vy + GRAVITY * dt, MAX_FALL);
291:   e.y += e.vy * dt;
292:   e.onGround = false;
293:   for (const s of solidsFor(room)) {
294:     if (!overlap(e, s)) continue;
295:     if (e.vy >= 0 && prevBottom <= s.y + 4) {
296:       e.y = s.y - e.h;
297:       e.vy = 0;
298:       e.onGround = true;
299:     } else if (e.vy < 0) {
300:       e.y = s.y + s.h;
301:       e.vy = 0;
302:     }
303:   }
304:   for (const p of room.platforms) {
305:     if (!overlap(e, p)) continue;
306:     if (e.vy >= 0 && prevBottom <= p.y + 3) {
307:       e.y = p.y - e.h;
308:       e.vy = 0;
309:       e.onGround = true;
310:     }
311:   }
312: }
