23: export function drawPlayer(ctx, p, t, game) {
24:   const cx = Math.round(p.x + p.w / 2);
25:   const feet = Math.round(p.y + p.h);
26:   const moving = Math.abs(p.vx) > 14 && p.onGround;
27:   const run = moving ? Math.sin(p.animTime * 18) : 0;
28:   const bob = moving ? Math.abs(Math.sin(p.animTime * 18)) * -1 : Math.sin(t * 3.2) * 0.5;
29:   const dashLean = p.dashTimer > 0 ? 3 : 0;
30:   const hurt = p.invuln > 0 && Math.floor(t * 24) % 2 === 0;
31: 
32:   shadow(ctx, cx, feet + 1, 16, 0.4);
33:   ctx.save();
34:   ctx.translate(cx, feet);
35:   if (p.facing < 0) ctx.scale(-1, 1);
36:   ctx.translate(0, bob);
37:   if (dashLean) ctx.translate(1, 0);
38: 
39:   const suit = hurt ? PAL.white : "#17121f";
40:   const suit2 = hurt ? PAL.bone : "#241b30";
41:   const skin = hurt ? PAL.white : PAL.skin;
42:   const hair = hurt ? PAL.white : PAL.hair;
43: 
44:   // legs
45:   if (!p.onGround) {
46:     px(ctx, -4, -7, 3, 6, suit);
47:     px(ctx, 2, -5, 3, 5, suit);
48:     px(ctx, -4, -2, 4, 2, PAL.ink);
49:     px(ctx, 2, -1, 4, 2, PAL.ink);
50:   } else if (moving) {
51:     px(ctx, -5 + run * 2, -6, 3, 6, suit);
52:     px(ctx, 2 - run * 2, -6, 3, 6, suit);
53:     px(ctx, -6 + run * 2, -1, 5, 2, PAL.ink);
54:     px(ctx, 1 - run * 2, -1, 5, 2, PAL.ink);
55:   } else {
56:     px(ctx, -4, -6, 3, 6, suit);
57:     px(ctx, 1, -6, 3, 6, suit);
58:     px(ctx, -5, -1, 4, 2, PAL.ink);
59:     px(ctx, 1, -1, 5, 2, PAL.ink);
60:   }
61: 
62:   // torso / suit
63:   outlineRect(ctx, -5, -15, 10, 10, suit, PAL.ink);
64:   px(ctx, -5, -14, 1, 7, suit2);
65:   // shirt + tie
66:   px(ctx, -2, -14, 4, 5, PAL.bone);
67:   px(ctx, 0, -14, 1, 6, PAL.blood);
68:   px(ctx, 1, -13, 1, 3, PAL.blood);
69:   // lapels
70:   px(ctx, -3, -14, 1, 3, PAL.bone2);
71:   px(ctx, 2, -14, 1, 3, PAL.bone2);
72:   // belt
73:   px(ctx, -5, -7, 10, 1, PAL.ink);
74:   px(ctx, -1, -7, 2, 1, PAL.gold);
75: 
76:   // arms
77:   px(ctx, -7, -14, 2, 6, suit);
78:   px(ctx, 5, -14, 2, 6, suit);
79:   px(ctx, -7, -9, 2, 2, skin);
80:   px(ctx, 5, -9, 2, 2, skin);
81: 
82:   // head
83:   outlineRect(ctx, -4, -21, 8, 7, skin, PAL.ink);
84:   // face details
85:   px(ctx, 1, -19, 1, 1, PAL.ink);
86:   px(ctx, -2, -19, 1, 1, PAL.ink);
87:   px(ctx, 2, -17, 1, 1, PAL.rust);
88:   // messy blonde hair
89:   px(ctx, -5, -22, 10, 4, hair);
90:   px(ctx, -5, -20, 2, 2, hair);
91:   px(ctx, 4, -21, 2, 3, hair);
92:   px(ctx, -4, -23, 2, 2, hair);
93:   px(ctx, 0, -24, 2, 2, hair);
94:   px(ctx, 3, -23, 2, 2, hair);
95:   px(ctx, -5, -18, 1, 2, hair);
96:   px(ctx, 4, -18, 1, 1, hair);
97:   px(ctx, -3, -22, 2, 1, PAL.hair2);
98: 
99:   // weapon in hand when idle
100:   if (p.attackTimer <= 0) {
101:     if (p.weapon === "shotgun") {
102:       px(ctx, 4, -11, 9, 2, PAL.ink);
103:       px(ctx, 5, -11, 7, 1, PAL.steel2);
104:       px(ctx, 8, -10, 1, 2, PAL.rust);
105:       px(ctx, 12, -11, 2, 2, PAL.steel);
106:     } else if (p.weapon === "katana") {
107:       ctx.save();
108:       ctx.translate(5, -10);
109:       ctx.rotate(-0.35);
110:       px(ctx, 0, -1, 13, 2, PAL.ink);
111:       px(ctx, 1, -1, 11, 1, PAL.steel);
112:       px(ctx, 12, -1, 2, 1, PAL.white);
113:       px(ctx, -1, -2, 2, 3, PAL.gold2);
114:       ctx.restore();
115:     } else {
116:       // idle pull-cord
117:       px(ctx, 5, -11, 1, 4, PAL.rust);
118:       px(ctx, 5, -7, 2, 1, PAL.steel2);
119:     }
120:   }
121: 
122:   // attacks
123:   if (p.attackTimer > 0) {
124:     const prog = 1 - p.attackTimer / p.attackDur;
125:     drawAttack(ctx, p, prog, t);
126:   }
127: 
128:   ctx.restore();
129: 
130:   if (p.dashTimer > 0) {
131:     ctx.save();
132:     ctx.globalAlpha = 0.3;
133:     px(ctx, p.x + 2, p.y + 4, p.w - 4, p.h - 6, PAL.blood);
134:     ctx.restore();
135:   }
136: }
