269: export function drawBat(ctx, e, t) {
270:   const cx = Math.round(e.x + e.w / 2);
271:   const cy = Math.round(e.y + e.h / 2);
272:   const flap = Math.sin(t * 12 + e.seed) * 6;
273:   const flash = e.flash > 0;
274:   const body = flash ? PAL.white : "#2b1533";
275:   const wing = flash ? PAL.white : "#4a1f4e";
276:   ctx.save();
277:   ctx.translate(cx, cy);
278:   if (e.facing < 0) ctx.scale(-1, 1);
279:   // wings
280:   ctx.beginPath();
281:   ctx.moveTo(-1, -2);
282:   ctx.lineTo(-16, -5 - flap);
283:   ctx.lineTo(-12, 1 - flap * 0.5);
284:   ctx.lineTo(-15, 4);
285:   ctx.lineTo(-4, 4);
286:   ctx.closePath();
287:   ctx.fillStyle = wing;
288:   ctx.fill();
289:   ctx.strokeStyle = PAL.ink;
290:   ctx.lineWidth = 1;
291:   ctx.stroke();
292:   ctx.beginPath();
293:   ctx.moveTo(1, -2);
294:   ctx.lineTo(16, -5 - flap);
295:   ctx.lineTo(12, 1 - flap * 0.5);
296:   ctx.lineTo(15, 4);
297:   ctx.lineTo(4, 4);
298:   ctx.closePath();
299:   ctx.fillStyle = wing;
300:   ctx.fill();
301:   ctx.stroke();
302:   // body
303:   px(ctx, -4, -5, 8, 9, PAL.ink);
304:   px(ctx, -3, -4, 6, 7, body);
305:   px(ctx, -3, -6, 2, 2, body);
306:   px(ctx, 1, -7, 2, 3, body);
307:   // ears
308:   px(ctx, -4, -7, 2, 3, body);
309:   px(ctx, 2, -8, 2, 4, body);
310:   // eyes / fangs
311:   px(ctx, -2, -3, 1, 1, PAL.blood2);
312:   px(ctx, 2, -3, 1, 1, PAL.blood2);
313:   px(ctx, 0, 1, 1, 2, PAL.bone);
314:   px(ctx, 2, 1, 1, 2, PAL.bone);
315:   ctx.restore();
316: }
