28: export class Input {
29:   constructor() {
30:     this.downSet = new Set();
31:     this.pressedSet = new Set();
32:     this.releasedSet = new Set();
33:     this.onAction = null;
34:     this.anyPressed = false;
35: 
36:     addEventListener("keydown", (e) => {
37:       if (BLOCK.has(e.code)) e.preventDefault();
38:       if (!e.repeat) {
39:         this.downSet.add(e.code);
40:         this.pressedSet.add(e.code);
41:         this.anyPressed = true;
42:         this.onAction?.(e.code);
43:       }
44:     });
45:     addEventListener("keyup", (e) => {
46:       this.downSet.delete(e.code);
47:       this.releasedSet.add(e.code);
48:     });
49:     addEventListener("blur", () => this.downSet.clear());
50:   }
51: 
52:   down(action) {
53:     return MAP[action].some((code) => this.downSet.has(code));
54:   }
55:   pressed(action) {
56:     return MAP[action].some((code) => this.pressedSet.has(code));
57:   }
58:   released(action) {
59:     return MAP[action].some((code) => this.releasedSet.has(code));
60:   }
61:   axis() {
62:     let x = 0;
63:     if (this.down("left")) x -= 1;
64:     if (this.down("right")) x += 1;
65:     return x;
66:   }
67:   endFrame() {
68:     this.pressedSet.clear();
69:     this.releasedSet.clear();
70:     this.anyPressed = false;
