53: export class Game {
54:   constructor(input, sfx) {
55:     this.input = input;
56:     this.sfx = sfx;
57:     this.rooms = buildLevels();
58:     this.mode = "title";
59:     this.time = 0;
60:     this.titleTime = 0;
61:     this.roomIndex = 0;
62:     this.room = this.rooms[0];
63:     this.player = null;
64:     this.enemies = [];
65:     this.boss = null;
66:     this.projectiles = [];
67:     this.pickups = [];
68:     this.particles = [];
69:     this.effects = [];
70:     this.texts = [];
71:     this.warnings = [];
72:     this.camera = { x: 0, y: 0 };
73:     this.shakeMag = 0;
74:     this.shakeTime = 0;
75:     this.flashTime = 0;
76:     this.flashColor = PAL.white;
77:     this.hitstop = 0;
78:     this.fade = 0;
79:     this.banner = null;
80:     this.hint = null;
81:     this.prompt = null;
82:     this.menuIndex = 0;
83:     this.message = null;
84:     this.menuMessage = "";
85:     this.menuMessageTime = 0;
86:     this.bossDefeated = false;
87:     this.best = 0;
88:     try { this.best = Number(localStorage.getItem("chainsawdebt.best") || 0); } catch {}
89:     this.debugGod = false;
90:     this.frame = 0;
91:     this.resetRunState();
92:   }
93: 
94:   resetRunState() {
95:     this.blood = 0;
96:     this.debt = 0;
97:     this.kills = 0;
98:     this.deaths = 0;
99:     this.elapsed = 0;
100:     this.contracts = new Set();
101:     this.weapons = new Set(["chainsaw"]);
102:     this.weapon = "chainsaw";
103:     this.upgrades = 0;
104:     this.interestTimer = 20;
105:     this.collectorMarks = new Set();
106:     this.shopBought = new Set();
107:     this.checkpoint = { roomIndex: 0, x: 74, y: 240 };
108:     this.bossDefeated = false;
109:     this.boss = null;
110:     this.player = null;
111:     this.enemies = [];
112:     this.projectiles = [];
113:     this.pickups = [];
114:     this.particles = [];
115:     this.effects = [];
116:     this.texts = [];
117:     this.warnings = [];
118:     this.hint = null;
119:     this.banner = null;
120:     this.prompt = null;
121:     this.fade = 0;
122:     this.hitstop = 0;
123:     this.menuIndex = 0;
124:     this.menuMessage = "";
125:     this.seenHints = new Set();
126:   }
127: 
128:   startRun() {
129:     this.sfx.init();
130:     this.sfx.startMusic("city");
131:     this.resetRunState();
132:     this.mode = "play";
133:     this.loadRoom(0);
134:     this.player.hp = 5;
135:     this.player.maxHp = 5;
136:     this.setHint("A / D  MOVE      SPACE  JUMP      J  ATTACK", 8);
137:     this.flashScreen(0.35, PAL.bone);
138:     this.sfx.contract();
139:   }
140: 
141:   toTitle() {
142:     this.mode = "title";
143:     this.sfx.setMusic("city");
144:   }
145: 
146:   loadRoom(index, spawnOverride) {
147:     this.roomIndex = index;
148:     this.room = this.rooms[index];
149:     this.enemies = this.room.enemies.map((d) => createEnemy({ ...d }));
150:     this.projectiles = [];
151:     this.pickups = [];
152:     this.warnings = [];
153:     this.boss = null;
154:     if (this.room.boss && !this.bossDefeated) {
155:       this.boss = new Boss(this.room.width / 2, this.room.ground);
156:       this.boss.entered = false;
157:     }
158:     const spawn = spawnOverride || this.room.spawn;
159:     if (!this.player) {
160:       this.player = new Player(spawn.x, spawn.y);
161:     } else {
162:       this.player.x = spawn.x - this.player.w / 2;
163:       this.player.y = spawn.y - this.player.h;
164:       this.player.vx = 0;
165:       this.player.vy = 0;
166:       this.player.dead = false;
167:       this.player.attackTimer = 0;
168:       this.player.dashTimer = 0;
169:     }
170:     this.camera.x = clamp(this.player.centerX - W / 2, 0, Math.max(0, this.room.width - W));
171:     this.camera.y = 0;
172:     this.banner = {
173:       title: this.room.name,
174:       sector: this.room.sector,
175:       flavor: this.room.flavor,
176:       t: 0, dur: 3.2,
177:     };
178:     this.fade = Math.max(this.fade, 0.7);
179:     this.sfx.setMusic(index === 2 ? "boss" : "city");
180:     if (index === 2) {
181:       setTimeout(() => {
182:         if (this.mode === "play" && this.roomIndex === 2 && this.boss && !this.boss.dead) {
183:           this.sfx.bossRoar();
184:           this.shake(8, 0.8);
185:         }
186:       }, 700);
187:     }
188:     if (index === 1 && !this.seenHints.has("subway")) {
189:       this.seenHints.add("subway");
190:       this.setHint("TAB — OPEN CONTRACTS. POWER NOW. INTEREST LATER.", 7);
191:     }
192:   }
193: 
194:   hasContract(id) { return this.contracts.has(id); }
195: 
196:   setHint(text, dur = 5) {
197:     this.hint = { text, t: 0, dur };
198:   }
199: 
200:   update(dt) {
201:     this.time += dt;
202:     this.frame++;
203:     if (this.mode === "title") {
204:       this.titleTime += dt;
205:       if (this.input.pressed("confirm") || this.input.pressed("jump")) this.startRun();
206:       if (this.input.pressed("mute")) this.sfx.toggle();
207:       return;
208:     }
209: 
210:     if (this.input.pressed("mute")) {
211:       const muted = this.sfx.toggle();
212:       this.menuMessage = muted ? "SOUND OFF" : "SOUND ON";
213:       this.menuMessageTime = 1.2;
214:     }
215: 
216:     if (this.mode === "play") this.updateWorld(dt);
217:     else if (this.mode === "contracts") this.updateContracts(dt);
218:     else if (this.mode === "shop") this.updateShop(dt);
219:     else if (this.mode === "pause") {
220:       if (this.input.pressed("pause") || this.input.pressed("back") || this.input.pressed("confirm")) this.mode = "play";
221:     } else if (this.mode === "dead") {
222:       this.updateParticles(dt);
223:       this.texts = this.texts.filter((t) => { t.t += dt; return t.t < t.dur; });
224:       if (this.input.pressed("confirm") || this.input.pressed("restart") || this.input.pressed("jump")) this.respawn();
225:       if (this.input.pressed("back")) this.toTitle();
226:     } else if (this.mode === "win") {
227:       this.updateParticles(dt);
228:       if (this.input.pressed("confirm") || this.input.pressed("restart") || this.input.pressed("jump")) this.startRun();
229:       if (this.input.pressed("back")) this.toTitle();
230:     }
231: 
232:     this.updateBanner(dt);
233:     this.menuMessageTime = Math.max(0, this.menuMessageTime - dt);
234:     this.shakeTime = Math.max(0, this.shakeTime - dt);
235:     if (this.shakeTime <= 0) this.shakeMag = 0;
236:     this.flashTime = Math.max(0, this.flashTime - dt);
237:     this.fade = Math.max(0, this.fade - dt * 2.4);
238:   }
239: 
240:   updateBanner(dt) {
241:     if (this.banner) {
242:       this.banner.t += dt;
243:       if (this.banner.t > this.banner.dur) this.banner = null;
244:     }
245:     if (this.hint) {
246:       this.hint.t += dt;
247:       if (this.hint.t > this.hint.dur) this.hint = null;
248:     }
249:   }
250: 
251:   updateWorld(dt) {
252:     if (this.hitstop > 0) {
253:       this.hitstop = Math.max(0, this.hitstop - dt);
254:       this.updateParticles(dt * 0.25);
255:       this.texts.forEach((t) => (t.t += dt * 0.3));
256:       return;
257:     }
258:     this.elapsed += dt;
259:     const p = this.player;
260:     if (!p) return;
261: 
262:     if (this.input.pressed("contracts")) {
263:       this.openContracts();
264:       return;
265:     }
266:     if (this.input.pressed("pause")) {
267:       this.mode = "pause";
268:       return;
269:     }
270: 
271:     // weapon swap
272:     if (this.input.pressed("swap") && this.weapons.size > 1) {
273:       const list = [...this.weapons];
274:       const i = list.indexOf(this.player.weapon);
275:       this.player.weapon = list[(i + 1) % list.length];
276:       this.player.attackTimer = 0;
277:       this.sfx.click();
278:       this.addText(p.centerX, p.y - 8, this.player.weapon.toUpperCase(), PAL.gold, 0.8);
279:     }
280: 
281:     p.update(dt, this);
282: 
283:     for (const e of this.enemies) if (!e.dead) e.update(dt, this);
284:     this.enemies = this.enemies.filter((e) => !e.dead);
285: 
286:     if (this.boss && !this.boss.dead) {
287:       const activeBoss = this.boss;
288:       activeBoss.update(dt, this);
289:       if (this.boss === activeBoss && !activeBoss.entered && activeBoss.state !== "intro") {
290:         activeBoss.entered = true;
291:         this.banner = { title: "THE DEBT DEVIL", sector: "COLLECTOR CLASS", flavor: "It has come to collect.", t: 0, dur: 2.8 };
292:       }
293:     }
294: 
295:     for (const pr of this.projectiles) pr.update(dt, this);
296:     this.projectiles = this.projectiles.filter((pr) => !pr.dead);
297: 
298:     for (const pk of this.pickups) pk.update(dt, this);
299:     this.pickups = this.pickups.filter((pk) => !pk.dead);
300: 
301:     this.updateParticles(dt);
302:     this.updateEffects(dt);
303:     this.texts = this.texts.filter((t) => { t.t += dt; return t.t < t.dur; });
304:     this.warnings = this.warnings.filter((w) => { w.t += dt; return w.t < w.dur; });
305: 
306:     // hazards
307:     for (const hz of this.room.hazards) {
308:       if (overlap(p.rect, hz) && p.invuln <= 0) {
309:         p.hurt(1, p.centerX, this);
310:         p.y = hz.y - p.h - 2;
311:         p.vy = -310;
312:       }
313:     }
314: 
315:     // debt interest
316:     if (this.debt > 0 && this.debt < 99) {
317:       this.interestTimer -= dt;
318:       if (this.interestTimer <= 0) {
319:         this.interestTimer = 20;
320:         this.debt = Math.min(99, this.debt + 1);
321:         this.addText(p.centerX, p.y - 18, "INTEREST +1 DEBT", PAL.gold2, 1.5);
322:         this.checkCollector();
323:       }
324:     }
325: 
326:     // interaction
327:     this.prompt = this.findInteractable();
328:     if (this.prompt && this.input.pressed("interact")) this.interact(this.prompt);
329: 
330:     // camera
331:     const target = clamp(p.centerX - W / 2 + p.facing * 26, 0, Math.max(0, this.room.width - W));
332:     this.camera.x = lerp(this.camera.x, target, 1 - Math.pow(0.0008, dt));
333:     this.camera.y = 0;
334: 
335:     // tutorial beats
336:     if (this.roomIndex === 0 && !this.seenHints.has("intro") && this.elapsed > 1.2) {
337:       this.seenHints.add("intro");
338:     }
339:     if (this.roomIndex === 0 && !this.seenHints.has("altar") && p.x > 260) {
340:       this.seenHints.add("altar");
341:       this.setHint("TAB — SIGN A CONTRACT. BLOOD NOW, DEBT FOREVER.", 7);
342:     }
343:     if (this.roomIndex === 0 && !this.seenHints.has("talk") && p.x > 150 && p.x < 230) {
344:       this.seenHints.add("talk");
345:       this.setHint("E — TALK TO MAKIMA / REST AT LAMPS", 6);
346:     }
347:     if (this.roomIndex === 2 && !this.seenHints.has("boss") && this.elapsed > 2) {
348:       this.seenHints.add("boss");
349:       this.setHint("IT FLOATS. IT LIES. CUT IT DOWN.", 6);
350:     }
351:   }
352: 
353:   updateContracts(dt) {
354:     const items = CONTRACTS;
355:     if (this.input.pressed("back") || this.input.pressed("contracts")) { this.mode = "play"; return; }
356:     if (this.input.pressed("up")) { this.menuIndex = (this.menuIndex - 1 + items.length) % items.length; this.sfx.click(); }
357:     if (this.input.pressed("down")) { this.menuIndex = (this.menuIndex + 1) % items.length; this.sfx.click(); }
358:     if (this.input.pressed("confirm") || this.input.pressed("interact") || this.input.pressed("attack")) {
359:       this.signContract(items[this.menuIndex]);
360:     }
361:     this.updateParticles(dt * 0.4);
362:   }
363: 
364:   signContract(item) {
365:     if (this.contracts.has(item.id)) {
366:       this.menuMessage = "ALREADY SIGNED.";
367:       this.menuMessageTime = 1.4;
368:       this.sfx.deny();
369:       return;
370:     }
371:     if (this.blood < item.cost) {
372:       this.menuMessage = `NOT ENOUGH BLOOD — NEED ${item.cost}`;
373:       this.menuMessageTime = 1.6;
374:       this.sfx.deny();
375:       this.shake(2, 0.12);
376:       return;
377:     }
378:     this.blood -= item.cost;
379:     this.debt = Math.min(99, this.debt + item.debt);
380:     this.contracts.add(item.id);
381:     if (item.id === "katana") {
382:       this.weapons.add("katana");
383:       this.player.weapon = "katana";
384:     }
385:     this.sfx.contract();
386:     this.flashScreen(0.35, PAL.blood);
387:     this.shake(4, 0.3);
388:     this.spawnBlood(this.player.centerX, this.player.centerY, 20, PAL.blood2);
389:     this.menuMessage = `${item.name} SIGNED. DEBT +${item.debt}.`;
390:     this.menuMessageTime = 2;
391:     this.checkCollector();
392:   }
393: 
394:   openContracts() {
395:     this.mode = "contracts";
396:     this.menuIndex = 0;
397:     this.menuMessage = "";
398:     this.sfx.click();
399:   }
400: 
401:   updateShop(dt) {
402:     const items = SHOP_ITEMS;
403:     if (this.input.pressed("back") || this.input.pressed("interact")) { this.mode = "play"; return; }
404:     if (this.input.pressed("up")) { this.menuIndex = (this.menuIndex - 1 + items.length) % items.length; this.sfx.click(); }
405:     if (this.input.pressed("down")) { this.menuIndex = (this.menuIndex + 1) % items.length; this.sfx.click(); }
406:     if (this.input.pressed("confirm") || this.input.pressed("attack")) this.buy(items[this.menuIndex]);
407:     this.updateParticles(dt * 0.4);
408:   }
409: 
410:   buy(item) {
411:     const sold = !item.repeat && this.shopBought.has(item.id);
412:     if (sold) {
413:       this.menuMessage = "SOLD OUT.";
414:       this.menuMessageTime = 1.2;
415:       this.sfx.deny();
416:       return;
417:     }
418:     if (item.id === "heal" && this.player.hp >= this.player.maxHp) {
419:       this.menuMessage = "YOU'RE ALREADY STITCHED.";
420:       this.menuMessageTime = 1.4;
421:       this.sfx.deny();
422:       return;
423:     }
424:     if (item.id === "debt" && this.debt <= 0) {
425:       this.menuMessage = "NO DEBT. SUSPICIOUS.";
426:       this.menuMessageTime = 1.4;
427:       this.sfx.deny();
428:       return;
429:     }
430:     if (this.blood < item.cost) {
431:       this.menuMessage = `NOT ENOUGH BLOOD — NEED ${item.cost}`;
432:       this.menuMessageTime = 1.5;
433:       this.sfx.deny();
434:       return;
435:     }
436:     this.blood -= item.cost;
437:     if (!item.repeat) this.shopBought.add(item.id);
438:     if (item.id === "shotgun") {
439:       this.weapons.add("shotgun");
440:       this.player.weapon = "shotgun";
441:       this.player.ammo = 6;
442:     } else if (item.id === "heart") {
443:       this.player.maxHp++;
444:       this.player.hp = this.player.maxHp;
445:     } else if (item.id === "tune") {
446:       this.upgrades++;
447:     } else if (item.id === "debt") {
448:       this.debt = Math.max(0, this.debt - 10);
449:     } else if (item.id === "heal") {
450:       this.player.heal(2);
451:     }
452:     this.sfx.coin();
453:     this.sfx.pickup();
454:     this.menuMessage = `${item.name} — DONE.`;
455:     this.menuMessageTime = 1.8;
456:     this.spawnSpark(this.player.centerX, this.player.centerY, 8);
457:   }
458: 
459:   findInteractable() {
460:     const p = this.player;
461:     const px = p.centerX;
462:     let best = null;
463:     let bestD = 30;
464:     for (const cp of this.room.checkpoints) {
465:       const d = Math.abs(px - cp.x) + Math.abs(p.y + p.h - cp.y) * 0.35;
466:       if (d < bestD) { best = { type: "checkpoint", x: cp.x, y: cp.y, label: "REST  [E]" }; bestD = d; }
467:     }
468:     for (const a of this.room.altars) {
469:       const d = Math.abs(px - a.x) + Math.abs(p.y + p.h - a.y) * 0.35;
470:       if (d < bestD) { best = { type: "altar", x: a.x, y: a.y, label: "DEVIL CONTRACTS  [E]" }; bestD = d; }
471:     }
472:     for (const n of this.room.npcs) {
473:       const d = Math.abs(px - n.x) + Math.abs(p.y + p.h - n.y) * 0.35;
474:       if (d < bestD) { best = { type: "npc", x: n.x, y: n.y, label: "MAKIMA  [E]" }; bestD = d; }
475:     }
476:     for (const door of this.room.doors) {
477:       const d = Math.abs(px - door.x) + Math.abs(p.y + p.h - door.y) * 0.35;
478:       if (d < bestD) { best = { type: "door", x: door.x, y: door.y, to: door.to, label: `${door.label}  [E]` }; bestD = d; }
479:     }
480:     return best;
481:   }
482: 
483:   interact(it) {
484:     if (it.type === "checkpoint") {
485:       this.checkpoint = { roomIndex: this.roomIndex, x: it.x, y: it.y };
486:       this.player.heal(this.player.maxHp);
487:       this.sfx.checkpoint();
488:       this.spawnSpark(it.x, it.y - 30, 14);
489:       this.addText(it.x, it.y - 44, "CHECKPOINT", PAL.gold, 1.4);
490:       if (this.room.boss && !this.bossDefeated) {
491:         this.boss = new Boss(this.room.width / 2, this.room.ground);
492:       }
493:       this.enemies = this.room.enemies.map((d) => createEnemy({ ...d }));
494:       this.fade = 0.25;
495:     } else if (it.type === "altar") {
496:       this.openContracts();
497:     } else if (it.type === "npc") {
498:       this.mode = "shop";
499:       this.menuIndex = 0;
500:       this.menuMessage = "";
501:       this.sfx.click();
502:     } else if (it.type === "door") {
503:       this.fade = 0.8;
504:       this.loadRoom(it.to);
505:     }
506:   }
507: 
508:   updateParticles(dt) {
509:     for (const p of this.particles) {
510:       p.life -= dt;
511:       p.vy += (p.gravity || 0) * dt;
512:       p.x += p.vx * dt;
513:       p.y += p.vy * dt;
514:       if (p.type === "dust") p.vx *= 0.96;
515:     }
516:     this.particles = this.particles.filter((p) => p.life > 0);
517:     if (this.particles.length > 420) this.particles.splice(0, this.particles.length - 420);
518:   }
519: 
520:   updateEffects(dt) {
521:     for (const e of this.effects) e.t += dt;
522:     this.effects = this.effects.filter((e) => e.t < e.dur);
523:   }
524: 
525:   spawnParticle(x, y, vx, vy, life, color, size = 1, gravity = 0, type = "blood") {
526:     this.particles.push({ x, y, vx, vy, life, maxLife: life, color, size, gravity, type });
527:   }
528: 
529:   spawnBlood(x, y, n = 8, color = PAL.blood) {
530:     for (let i = 0; i < n; i++) {
531:       const a = rand(0, Math.PI * 2);
532:       const s = rand(30, 170);
533:       this.spawnParticle(
534:         x + rand(-4, 4), y + rand(-4, 4),
535:         Math.cos(a) * s, Math.sin(a) * s - 50,
536:         rand(0.3, 0.85), Math.random() < 0.25 ? PAL.blood2 : color,
537:         randInt(1, 2), 620, "blood"
538:       );
539:     }
540:   }
541: 
542:   spawnSpark(x, y, n = 5) {
543:     for (let i = 0; i < n; i++) {
544:       const a = rand(0, Math.PI * 2);
545:       const s = rand(30, 130);
546:       this.spawnParticle(x, y, Math.cos(a) * s, Math.sin(a) * s, rand(0.12, 0.35), Math.random() < 0.5 ? PAL.gold : PAL.bone, 1, 180, "spark");
547:     }
548:   }
549: 
550:   spawnDust(x, y, n = 6) {
551:     for (let i = 0; i < n; i++) {
552:       this.spawnParticle(
553:         x + rand(-6, 6), y - rand(0, 4),
554:         rand(-40, 40), rand(-60, -10),
555:         rand(0.25, 0.6), PAL.bone2, randInt(1, 2), -10, "dust"
556:       );
557:     }
558:   }
559: 
560:   addText(x, y, text, color = PAL.bone, dur = 0.8, size = 1) {
561:     this.texts.push({ x, y, text, color, t: 0, dur, size });
562:   }
563: 
564:   addEffect(e) {
565:     e.t = e.t || 0;
566:     e.dur = e.dur || 0.3;
567:     this.effects.push(e);
568:   }
