589:   meleeHit(player) {
590:     const weapon = player.weapon;
591:     if (weapon === "shotgun") return;
592:     const heavy = player.attackIndex === 2;
593:     let range = weapon === "katana" ? 43 : 31 + player.attackIndex * 3;
594:     if (heavy) range += 4;
595:     let damage = weapon === "katana"
596:       ? (heavy ? 26 : 17)
597:       : (heavy ? 16 : 9);
598:     damage += this.upgrades * 5;
599:     const box = {
600:       x: player.facing > 0 ? player.x + player.w - 2 : player.x - range + 2,
601:       y: player.y + 1,
602:       w: range,
603:       h: 19,
604:     };
605:     let hits = 0;
606:     for (const e of this.enemies) {
607:       if (e.dead || !overlap(box, e.rect)) continue;
608:       e.hurt(damage, this, player.facing);
609:       hits++;
610:     }
611:     if (this.boss && !this.boss.dead && overlap(box, this.boss.rect)) {
612:       this.boss.hurt(damage, this);
613:       hits++;
614:     }
615:     for (const pr of this.projectiles) {
616:       if (!pr.friendly && overlap(box, pr.rect)) {
617:         pr.dead = true;
618:         this.spawnSpark(pr.x, pr.y, 3);
619:       }
620:     }
621:     if (hits) {
622:       this.sfx.hit();
623:       this.hitstop = 0.045;
624:       this.shake(weapon === "katana" ? 3 : 2, 0.1);
625:       this.spawnSpark(box.x + box.w * 0.6, box.y + 8, 3);
626:     }
627:   }
