700:   checkCollector() {
701:     const marks = [25, 55, 85];
702:     for (const mark of marks) {
703:       if (this.debt >= mark && !this.collectorMarks.has(mark) && this.roomIndex !== 2) {
704:         this.collectorMarks.add(mark);
705:         const p = this.player;
706:         this.spawnEnemyAt("collector", clamp(p.centerX + (p.facing > 0 ? 140 : -140), 50, this.room.width - 50), 0, true);
707:         this.banner = { title: "DEBT COLLECTOR", sector: "INTEREST DUE", flavor: "It can smell your credit.", t: 0, dur: 3 };
708:         this.sfx.bossRoar();
709:         this.shake(6, 0.5);
710:         this.flashScreen(0.25, PAL.gold);
711:         break;
712:       }
713:     }
