89:       <button data-code="Space">JMP</button>
90:     </div>`;
91:   document.body.appendChild(wrap);
92:   wrap.querySelectorAll("button").forEach((btn) => {
93:     const code = btn.dataset.code;
94:     const press = (e) => {
95:       e.preventDefault();
96:       input.downSet.add(code);
97:       input.pressedSet.add(code);
98:       input.onAction?.(code);
99:     };
100:     const release = (e) => {
101:       e.preventDefault();
102:       input.downSet.delete(code);
103:     };
104:     btn.addEventListener("pointerdown", press);
105:     btn.addEventListener("pointerup", release);
106:     btn.addEventListener("pointercancel", release);
