459:   findInteractable() {
460:     const p = this.player;
461:     const px = p.centerX;
462:     let best = null;
463:     let bestD = 30;
464:     for (const cp of this.room.checkpoints) {
465:       const d = Math.abs(px - cp.x) + Math.abs(p.y + p.h - cp.y) * 0.35;
466:       if (d < bestD) { best = { type: "checkpoint", x: cp.x, y: cp.y, label: "REST  [E]" }; bestD = d; }
467:     }
468:     for (const a of this.room.altars) {
469:       const d = Math.abs(px - a.x) + Math.abs(p.y + p.h - a.y) * 0.35;
470:       if (d < bestD) { best = { type: "altar", x: a.x, y: a.y, label: "DEVIL CONTRACTS  [E]" }; bestD = d; }
471:     }
472:     for (const n of this.room.npcs) {
473:       const d = Math.abs(px - n.x) + Math.abs(p.y + p.h - n.y) * 0.35;
474:       if (d < bestD) { best = { type: "npc", x: n.x, y: n.y, label: "MAKIMA  [E]" }; bestD = d; }
475:     }
476:     for (const door of this.room.doors) {
477:       const d = Math.abs(px - door.x) + Math.abs(p.y + p.h - door.y) * 0.35;
478:       if (d < bestD) { best = { type: "door", x: door.x, y: door.y, to: door.to, label: `${door.label}  [E]` }; bestD = d; }
479:     }
480:     return best;
481:   }
