440:   ctx.save();
441:   ctx.translate(cx, base + bob);
442:   const squash = 1 + Math.sin(t * 2.1) * 0.025;
443: 
444:   // hanging chains
445:   ctx.strokeStyle = "#6b5a44";
446:   ctx.lineWidth = 1;
447:   for (let i = -2; i <= 2; i++) {
448:     ctx.beginPath();
449:     ctx.moveTo(i * 26, -112);
450:     ctx.lineTo(i * 22 + Math.sin(t + i) * 2, -84);
451:     ctx.stroke();
