454:   // back scales / arms
455:   ctx.fillStyle = flash ? PAL.white : "#2a1424";
456:   ctx.beginPath();
457:   ctx.ellipse(-48, -48, 20, 30, -0.25, 0, Math.PI * 2);
458:   ctx.fill();
459:   ctx.beginPath();
460:   ctx.ellipse(48, -48, 20, 30, 0.25, 0, Math.PI * 2);
461:   ctx.fill();
462:   // claws
463:   for (const s of [-1, 1]) {
464:     px(ctx, s * 58 - 3, -26, 5, 12, PAL.bone2);
465:     px(ctx, s * 64 - 3, -30, 4, 9, PAL.bone2);
466:     px(ctx, s * 52 - 2, -33, 4, 8, PAL.bone2);
467:   }
468: 
469:   // main body
470:   ctx.fillStyle = dark;
471:   ctx.beginPath();
472:   ctx.ellipse(0, -54 * squash, 42, 54 * squash, 0, 0, Math.PI * 2);
473:   ctx.fill();
474:   ctx.fillStyle = flesh;
475:   ctx.beginPath();
476:   ctx.ellipse(0, -55 * squash, 38, 50 * squash, 0, 0, Math.PI * 2);
477:   ctx.fill();
478:   ctx.fillStyle = flesh2;
479:   ctx.beginPath();
480:   ctx.ellipse(-8, -62, 26, 34, -0.2, 0, Math.PI * 2);
481:   ctx.fill();
482: 
483:   // pulsing veins
484:   ctx.strokeStyle = phase2 ? "#ff4d63" : "#3c1328";
485:   ctx.lineWidth = 1;
486:   for (let i = 0; i < 5; i++) {
487:     const a = i * 1.27 + Math.sin(t * 1.5 + i) * 0.08;
488:     ctx.beginPath();
489:     ctx.moveTo(Math.cos(a) * 6, -55 + Math.sin(a) * 8);
490:     ctx.quadraticCurveTo(
491:       Math.cos(a) * 24, -55 + Math.sin(a) * 30,
492:       Math.cos(a + 0.3) * 36, -55 + Math.sin(a + 0.3) * 46
493:     );
494:     ctx.stroke();
495:   }
496: 
497:   // eyes track the player
498:   const pxp = player ? player.x + player.w / 2 - cx : 0;
499:   const pyp = player ? player.y + player.h / 2 - base : -40;
500:   const eyes = [
501:     [-22, -82, 8],
502:     [16, -88, 10],
503:     [-5, -69, 6],
504:     [28, -67, 6],
505:     [-30, -63, 5],
506:   ];
507:   eyes.forEach(([ex, ey, r], i) => {
508:     const blink = Math.sin(t * 1.3 + i * 2.1) > 0.97 ? 0.2 : 1;
509:     ctx.fillStyle = flash ? PAL.white : PAL.bone;
510:     ctx.beginPath();
