386:     this.flashScreen(0.35, PAL.blood);
387:     this.shake(4, 0.3);
388:     this.spawnBlood(this.player.centerX, this.player.centerY, 20, PAL.blood2);
389:     this.menuMessage = `${item.name} SIGNED. DEBT +${item.debt}.`;
