31:     this.pressedSet = new Set();
32:     this.releasedSet = new Set();
33:     this.onAction = null;
34:     this.anyPressed = false;
35: 
36:     addEventListener("keydown", (e) => {
37:       if (BLOCK.has(e.code)) e.preventDefault();
38:       if (!e.repeat) {
39:         this.downSet.add(e.code);
40:         this.pressedSet.add(e.code);
41:         this.anyPressed = true;
42:         this.onAction?.(e.code);
43:       }
44:     });
45:     addEventListener("keyup", (e) => {
46:       this.downSet.delete(e.code);
47:       this.releasedSet.add(e.code);
48:     });
49:     addEventListener("blur", () => this.downSet.clear());
