325:   ctx.save();
326:   ctx.translate(cx, feet);
327:   if (e.facing < 0) ctx.scale(-1, 1);
328:   if (dash) ctx.translate(2, 1);
329:   const suit = flash ? PAL.white : "#111019";
330:   const suit2 = flash ? PAL.white : "#292138";
331:   // legs
332:   if (dash) {
333:     px(ctx, -7, -6, 5, 3, suit);
334:     px(ctx, 2, -4, 5, 3, suit);
335:   } else {
336:     px(ctx, -4, -7, 3, 7, suit);
337:     px(ctx, 1, -7, 3, 7, suit);
338:   }
339:   px(ctx, -5, -1, 4, 2, PAL.ink);
340:   px(ctx, 1, -1, 5, 2, PAL.ink);
341:   // coat tails
342:   ctx.fillStyle = suit2;
343:   ctx.beginPath();
344:   ctx.moveTo(-5, -15);
345:   ctx.lineTo(-9, -3);
346:   ctx.lineTo(-4, -6);
347:   ctx.closePath();
348:   ctx.fill();
349:   // torso
350:   px(ctx, -5, -16, 10, 10, PAL.ink);
351:   px(ctx, -4, -15, 8, 9, suit);
352:   px(ctx, -1, -15, 3, 6, PAL.bone);
353:   px(ctx, 0, -15, 1, 6, PAL.blood);
354:   // arms
355:   px(ctx, 4, -14, 3, 6, suit);
356:   px(ctx, 5, -9, 2, 2, PAL.skin);
357:   // head - porcelain katana mask
358:   px(ctx, -4, -24, 9, 8, PAL.ink);
359:   px(ctx, -3, -23, 7, 7, flash ? PAL.white : "#d9d4c7");
360:   px(ctx, -2, -21, 2, 2, PAL.ink);
361:   px(ctx, 2, -21, 1, 2, PAL.ink);
362:   px(ctx, 0, -20, 1, 4, PAL.blood);
363:   px(ctx, -3, -24, 2, 2, PAL.blood);
364:   px(ctx, 3, -25, 2, 3, PAL.blood);
365:   // katana arm
366:   ctx.save();
367:   ctx.translate(5, -13);
368:   const ang = telegraph ? -1.9 : dash ? 0.05 : -0.55;
369:   ctx.rotate(ang);
370:   px(ctx, 0, -1, 27, 2, PAL.ink);
371:   px(ctx, 1, -1, 25, 1, telegraph ? PAL.white : PAL.steel);
372:   px(ctx, -2, -2, 3, 3, PAL.gold2);
