576: export function drawCheckpoint(ctx, cp, active, t, theme) {
577:   const x = Math.round(cp.x);
578:   const y = Math.round(cp.y);
579:   const glow = active ? 1 : 0.45;
580:   ctx.save();
581:   // pole
582:   px(ctx, x - 1, y - 38, 3, 38, PAL.ink);
583:   px(ctx, x, y - 37, 1, 35, PAL.steel2);
584:   // lamp head
585:   px(ctx, x - 6, y - 44, 13, 6, PAL.ink);
586:   px(ctx, x - 5, y - 43, 11, 4, active ? PAL.gold : PAL.steel2);
587:   px(ctx, x - 4, y - 42, 3, 2, active ? PAL.white : PAL.steel);
588:   // light cone
589:   ctx.globalCompositeOperation = "lighter";
590:   const flicker = 0.82 + Math.sin(t * 14 + cp.x) * 0.08;
591:   const grad = ctx.createLinearGradient(0, y - 42, 0, y + 4);
592:   grad.addColorStop(0, active ? "rgba(255,200,87,0.28)" : "rgba(140,150,170,0.14)");
593:   grad.addColorStop(1, "rgba(255,200,87,0)");
594:   ctx.fillStyle = grad;
595:   ctx.globalAlpha = flicker * glow;
596:   ctx.beginPath();
597:   ctx.moveTo(x - 5, y - 42);
598:   ctx.lineTo(x + 5, y - 42);
599:   ctx.lineTo(x + 26, y + 5);
600:   ctx.lineTo(x - 26, y + 5);
601:   ctx.closePath();
602:   ctx.fill();
603:   // base
604:   ctx.globalCompositeOperation = "source-over";
605:   ctx.globalAlpha = 1;
606:   px(ctx, x - 5, y - 2, 11, 2, PAL.ink);
607:   ctx.restore();
608: }
