395:   ctx.save();
396:   ctx.translate(e.x, e.y);
397:   if (e.facing < 0) ctx.scale(-1, 1);
398:   ctx.globalAlpha = 1 - Math.max(0, k - 0.7) / 0.3;
399:   // fox head jaw
400:   ctx.fillStyle = "rgba(255,59,82,0.16)";
