402:   ctx.ellipse(4, 8, 44, 40 + open, 0, 0, Math.PI * 2);
403:   ctx.fill();
404:   ctx.strokeStyle = PAL.bone;
405:   ctx.lineWidth = 2;
406:   ctx.beginPath();
407:   ctx.moveTo(-10, 8 - open);
408:   ctx.quadraticCurveTo(30, -18 - open, 56, 4 - open);
409:   ctx.stroke();
410:   ctx.beginPath();
411:   ctx.moveTo(-10, 8 + open);
412:   ctx.quadraticCurveTo(30, 30 + open, 56, 8 + open);
413:   ctx.stroke();
414:   // teeth
415:   ctx.fillStyle = PAL.bone;
416:   for (let i = 0; i < 5; i++) {
417:     const x = 4 + i * 10;
418:     ctx.beginPath();
419:     ctx.moveTo(x, 7 - open);
420:     ctx.lineTo(x + 4, 14 - open);
421:     ctx.lineTo(x + 8, 7 - open);
422:     ctx.fill();
423:     ctx.beginPath();
424:     ctx.moveTo(x, 9 + open);
425:     ctx.lineTo(x + 4, 2 + open);
426:     ctx.lineTo(x + 8, 9 + open);
427:     ctx.fill();
428:   }
429:   // eye
430:   ctx.fillStyle = PAL.gold;
431:   ctx.fillRect(22, -8 - open * 0.3, 4, 2);
432:   ctx.fillStyle = PAL.blood2;
433:   ctx.fillRect(12, 10, 40, 2);
434:   ctx.restore();
