410:   buy(item) {
411:     const sold = !item.repeat && this.shopBought.has(item.id);
412:     if (sold) {
413:       this.menuMessage = "SOLD OUT.";
414:       this.menuMessageTime = 1.2;
415:       this.sfx.deny();
416:       return;
417:     }
418:     if (item.id === "heal" && this.player.hp >= this.player.maxHp) {
419:       this.menuMessage = "YOU'RE ALREADY STITCHED.";
420:       this.menuMessageTime = 1.4;
421:       this.sfx.deny();
422:       return;
423:     }
424:     if (item.id === "debt" && this.debt <= 0) {
425:       this.menuMessage = "NO DEBT. SUSPICIOUS.";
426:       this.menuMessageTime = 1.4;
427:       this.sfx.deny();
428:       return;
429:     }
430:     if (this.blood < item.cost) {
431:       this.menuMessage = `NOT ENOUGH BLOOD — NEED ${item.cost}`;
432:       this.menuMessageTime = 1.5;
433:       this.sfx.deny();
434:       return;
435:     }
436:     this.blood -= item.cost;
437:     if (!item.repeat) this.shopBought.add(item.id);
438:     if (item.id === "shotgun") {
439:       this.weapons.add("shotgun");
440:       this.player.weapon = "shotgun";
441:       this.player.ammo = 6;
442:     } else if (item.id === "heart") {
443:       this.player.maxHp++;
444:       this.player.hp = this.player.maxHp;
445:     } else if (item.id === "tune") {
446:       this.upgrades++;
447:     } else if (item.id === "debt") {
448:       this.debt = Math.max(0, this.debt - 10);
449:     } else if (item.id === "heal") {
450:       this.player.heal(2);
451:     }
452:     this.sfx.coin();
453:     this.sfx.pickup();
454:     this.menuMessage = `${item.name} — DONE.`;
455:     this.menuMessageTime = 1.8;
456:     this.spawnSpark(this.player.centerX, this.player.centerY, 8);
457:   }
