65:   // shirt + tie
66:   px(ctx, -2, -14, 4, 5, PAL.bone);
67:   px(ctx, 0, -14, 1, 6, PAL.blood);
68:   px(ctx, 1, -13, 1, 3, PAL.blood);
69:   // lapels
70:   px(ctx, -3, -14, 1, 3, PAL.bone2);
71:   px(ctx, 2, -14, 1, 3, PAL.bone2);
72:   // belt
73:   px(ctx, -5, -7, 10, 1, PAL.ink);
74:   px(ctx, -1, -7, 2, 1, PAL.gold);
75: 
76:   // arms
77:   px(ctx, -7, -14, 2, 6, suit);
78:   px(ctx, 5, -14, 2, 6, suit);
79:   px(ctx, -7, -9, 2, 2, skin);
80:   px(ctx, 5, -9, 2, 2, skin);
81: 
82:   // head
83:   outlineRect(ctx, -4, -21, 8, 7, skin, PAL.ink);
84:   // face details
85:   px(ctx, 1, -19, 1, 1, PAL.ink);
86:   px(ctx, -2, -19, 1, 1, PAL.ink);
87:   px(ctx, 2, -17, 1, 1, PAL.rust);
88:   // messy blonde hair
89:   px(ctx, -5, -22, 10, 4, hair);
90:   px(ctx, -5, -20, 2, 2, hair);
91:   px(ctx, 4, -21, 2, 3, hair);
92:   px(ctx, -4, -23, 2, 2, hair);
93:   px(ctx, 0, -24, 2, 2, hair);
94:   px(ctx, 3, -23, 2, 2, hair);
95:   px(ctx, -5, -18, 1, 2, hair);
96:   px(ctx, 4, -18, 1, 1, hair);
97:   px(ctx, -3, -22, 2, 1, PAL.hair2);
98: 
99:   // weapon in hand when idle
100:   if (p.attackTimer <= 0) {
101:     if (p.weapon === "shotgun") {
102:       px(ctx, 4, -11, 9, 2, PAL.ink);
103:       px(ctx, 5, -11, 7, 1, PAL.steel2);
104:       px(ctx, 8, -10, 1, 2, PAL.rust);
105:       px(ctx, 12, -11, 2, 2, PAL.steel);
106:     } else if (p.weapon === "katana") {
107:       ctx.save();
108:       ctx.translate(5, -10);
109:       ctx.rotate(-0.35);
110:       px(ctx, 0, -1, 13, 2, PAL.ink);
