222: export function drawZombie(ctx, e, t) {
223:   const cx = Math.round(e.x + e.w / 2);
224:   const feet = Math.round(e.y + e.h);
225:   const walk = Math.sin(e.animTime * 9) * 1.4;
226:   const flash = e.flash > 0;
227:   shadow(ctx, cx, feet + 1, 14, 0.35);
228:   ctx.save();
229:   ctx.translate(cx + walk * 0.2, feet);
230:   if (e.facing < 0) ctx.scale(-1, 1);
231:   const skin = flash ? PAL.white : PAL.green;
232:   const suit = flash ? PAL.white : "#1d1a24";
233: 
234:   // legs
235:   px(ctx, -4 + walk, -6, 3, 6, suit);
236:   px(ctx, 2 - walk, -6, 3, 6, suit);
237:   px(ctx, -5 + walk, 0, 4, 1, PAL.ink);
238:   px(ctx, 2 - walk, 0, 4, 1, PAL.ink);
239: 
240:   // torso hunched
241:   px(ctx, -5, -14, 10, 9, PAL.ink);
242:   px(ctx, -4, -14, 9, 8, suit);
243:   px(ctx, -4, -12, 2, 2, flash ? PAL.white : PAL.blood);
244:   px(ctx, 2, -11, 2, 1, PAL.ink);
245: 
246:   // arms
247:   px(ctx, 4, -13, 7, 2, suit);
248:   px(ctx, 10, -13, 3, 2, skin);
249:   px(ctx, -5, -13, 2, 5, suit);
250: 
251:   // head
252:   px(ctx, -2, -20, 9, 7, PAL.ink);
253:   px(ctx, -1, -19, 7, 6, skin);
254:   px(ctx, -2, -20, 3, 2, skin);
255:   px(ctx, 2, -20, 4, 2, skin);
256:   px(ctx, 1, -18, 2, 2, PAL.ink);
257:   px(ctx, 5, -17, 1, 1, PAL.gold);
258:   px(ctx, 2, -15, 4, 1, PAL.ink);
259:   px(ctx, 1, -14, 1, 1, PAL.bone);
260:   // exposed brain
261:   px(ctx, -1, -22, 5, 3, flash ? PAL.white : "#d97d94");
