384: export function drawCollector(ctx, e, t) {
385:   const cx = Math.round(e.x + e.w / 2);
386:   const cy = Math.round(e.y + e.h / 2);
387:   const bob = Math.sin(t * 3 + e.seed) * 2;
388:   const flash = e.flash > 0;
389:   ctx.save();
390:   ctx.translate(cx, cy + bob);
391:   if (e.facing < 0) ctx.scale(-1, 1);
392:   // chains
393:   ctx.strokeStyle = flash ? PAL.white : PAL.gold2;
394:   ctx.lineWidth = 1;
395:   for (let i = 0; i < 3; i++) {
396:     ctx.beginPath();
397:     ctx.moveTo(-8 + i * 7, -14);
398:     ctx.lineTo(-10 + i * 6, -26);
399:     ctx.stroke();
400:   }
401:   // coat body
402:   ctx.fillStyle = flash ? PAL.white : "#1b1623";
403:   ctx.beginPath();
404:   ctx.moveTo(-7, -10);
405:   ctx.lineTo(-10, 14);
406:   ctx.lineTo(0, 10);
407:   ctx.lineTo(10, 14);
408:   ctx.lineTo(7, -10);
409:   ctx.closePath();
410:   ctx.fill();
411:   // coin head
412:   px(ctx, -7, -24, 14, 14, PAL.ink);
413:   px(ctx, -6, -23, 12, 12, flash ? PAL.white : PAL.gold2);
414:   px(ctx, -5, -22, 10, 10, flash ? PAL.white : PAL.gold);
415:   px(ctx, -3, -20, 6, 5, PAL.ink);
416:   px(ctx, -2, -19, 2, 2, PAL.blood2);
417:   px(ctx, 2, -19, 1, 2, PAL.blood2);
418:   px(ctx, -4, -15, 8, 1, PAL.gold2);
419:   // ledger
420:   px(ctx, 7, -8, 7, 9, PAL.ink);
421:   px(ctx, 8, -7, 5, 7, PAL.bone2);
422:   px(ctx, 9, -6, 3, 1, PAL.rust);
423:   px(ctx, 9, -4, 3, 1, PAL.rust);
424:   ctx.restore();
425: }
