427: export function drawBoss(ctx, b, t, player) {
428:   const cx = b.x + b.w / 2;
429:   const base = b.y + b.h;
430:   const bob = Math.sin(t * 2.1) * 3;
431:   const phase2 = b.phase === 2;
432:   const flash = b.flash > 0;
433:   const flesh = flash ? PAL.white : phase2 ? "#7c1734" : "#5c2346";
434:   const flesh2 = flash ? PAL.white : phase2 ? "#b32246" : "#8c3b5e";
435:   const dark = PAL.ink;
436: 
437:   // ground shadow
438:   shadow(ctx, cx, base + 2, 100, 0.5);
439: 
440:   ctx.save();
441:   ctx.translate(cx, base + bob);
442:   const squash = 1 + Math.sin(t * 2.1) * 0.025;
443: 
444:   // hanging chains
445:   ctx.strokeStyle = "#6b5a44";
446:   ctx.lineWidth = 1;
447:   for (let i = -2; i <= 2; i++) {
448:     ctx.beginPath();
449:     ctx.moveTo(i * 26, -112);
450:     ctx.lineTo(i * 22 + Math.sin(t + i) * 2, -84);
451:     ctx.stroke();
452:   }
453: 
454:   // back scales / arms
455:   ctx.fillStyle = flash ? PAL.white : "#2a1424";
456:   ctx.beginPath();
457:   ctx.ellipse(-48, -48, 20, 30, -0.25, 0, Math.PI * 2);
458:   ctx.fill();
459:   ctx.beginPath();
460:   ctx.ellipse(48, -48, 20, 30, 0.25, 0, Math.PI * 2);
461:   ctx.fill();
462:   // claws
463:   for (const s of [-1, 1]) {
464:     px(ctx, s * 58 - 3, -26, 5, 12, PAL.bone2);
465:     px(ctx, s * 64 - 3, -30, 4, 9, PAL.bone2);
466:     px(ctx, s * 52 - 2, -33, 4, 8, PAL.bone2);
467:   }
468: 
469:   // main body
470:   ctx.fillStyle = dark;
471:   ctx.beginPath();
472:   ctx.ellipse(0, -54 * squash, 42, 54 * squash, 0, 0, Math.PI * 2);
473:   ctx.fill();
474:   ctx.fillStyle = flesh;
475:   ctx.beginPath();
476:   ctx.ellipse(0, -55 * squash, 38, 50 * squash, 0, 0, Math.PI * 2);
477:   ctx.fill();
478:   ctx.fillStyle = flesh2;
479:   ctx.beginPath();
480:   ctx.ellipse(-8, -62, 26, 34, -0.2, 0, Math.PI * 2);
481:   ctx.fill();
482: 
483:   // pulsing veins
484:   ctx.strokeStyle = phase2 ? "#ff4d63" : "#3c1328";
485:   ctx.lineWidth = 1;
486:   for (let i = 0; i < 5; i++) {
487:     const a = i * 1.27 + Math.sin(t * 1.5 + i) * 0.08;
488:     ctx.beginPath();
489:     ctx.moveTo(Math.cos(a) * 6, -55 + Math.sin(a) * 8);
490:     ctx.quadraticCurveTo(
491:       Math.cos(a) * 24, -55 + Math.sin(a) * 30,
492:       Math.cos(a + 0.3) * 36, -55 + Math.sin(a + 0.3) * 46
493:     );
494:     ctx.stroke();
495:   }
496: 
497:   // eyes track the player
498:   const pxp = player ? player.x + player.w / 2 - cx : 0;
499:   const pyp = player ? player.y + player.h / 2 - base : -40;
500:   const eyes = [
501:     [-22, -82, 8],
502:     [16, -88, 10],
503:     [-5, -69, 6],
504:     [28, -67, 6],
505:     [-30, -63, 5],
506:   ];
507:   eyes.forEach(([ex, ey, r], i) => {
508:     const blink = Math.sin(t * 1.3 + i * 2.1) > 0.97 ? 0.2 : 1;
509:     ctx.fillStyle = flash ? PAL.white : PAL.bone;
510:     ctx.beginPath();
511:     ctx.ellipse(ex, ey, r, r * 0.66 * blink, 0, 0, Math.PI * 2);
512:     ctx.fill();
513:     if (blink > 0.5) {
514:       const dx = clamp(pxp / 80, -1, 1) * r * 0.35;
515:       const dy = clamp(pyp / 40, -1, 1) * r * 0.25;
516:       ctx.fillStyle = phase2 ? "#ff2038" : PAL.blood;
517:       ctx.beginPath();
518:       ctx.arc(ex + dx, ey + dy, r * 0.36, 0, Math.PI * 2);
519:       ctx.fill();
520:       ctx.fillStyle = PAL.ink;
521:       ctx.beginPath();
522:       ctx.arc(ex + dx, ey + dy, r * 0.15, 0, Math.PI * 2);
523:       ctx.fill();
524:     }
525:   });
526: 
527:   // mouth
528:   const open = 6 + Math.sin(t * 3.1) * 3 + (b.state === "roar" ? 8 : 0);
529:   ctx.fillStyle = dark;
530:   ctx.beginPath();
531:   ctx.ellipse(2, -34, 17, open, 0.04, 0, Math.PI * 2);
532:   ctx.fill();
533:   ctx.fillStyle = "#5b0d20";
534:   ctx.beginPath();
535:   ctx.ellipse(2, -33, 14, open * 0.7, 0.04, 0, Math.PI * 2);
536:   ctx.fill();
537:   for (let i = -2; i <= 2; i++) {
538:     px(ctx, i * 6 - 2, -34 - open * 0.55, 3, 5, PAL.bone);
539:     px(ctx, i * 6 - 1, -34 + open * 0.35, 2, 4, PAL.bone);
540:   }
541: 
542:   // suit collar / tie at the bottom
543:   px(ctx, -26, -18, 52, 12, flash ? PAL.white : "#17121f");
544:   px(ctx, -26, -18, 8, 7, flash ? PAL.white : "#241b30");
545:   px(ctx, 18, -18, 8, 7, flash ? PAL.white : "#241b30");
546:   px(ctx, -3, -17, 6, 4, PAL.bone);
547:   px(ctx, -1, -15, 2, 9, PAL.blood);
548: 
549:   // orbiting coins
550:   for (let i = 0; i < 4; i++) {
551:     const a = t * 0.8 + i * Math.PI / 2;
552:     const ox = Math.cos(a) * 58;
553:     const oy = -58 + Math.sin(a) * 14;
554:     px(ctx, ox - 3, oy - 3, 6, 6, PAL.gold2);
555:     px(ctx, ox - 2, oy - 2, 4, 4, PAL.gold);
556:     px(ctx, ox - 1, oy - 1, 1, 1, PAL.white);
557:   }
558: 
559:   // phase transition aura
560:   if (b.state === "phase") {
561:     ctx.save();
562:     ctx.globalCompositeOperation = "lighter";
563:     ctx.globalAlpha = 0.4 + Math.sin(t * 22) * 0.2;
564:     ctx.strokeStyle = PAL.blood2;
565:     ctx.lineWidth = 2;
566:     ctx.beginPath();
567:     ctx.arc(0, -55, 58 + Math.sin(t * 8) * 5, 0, Math.PI * 2);
568:     ctx.stroke();
569:     ctx.restore();
570:   }
571:   ctx.restore();
