97:   px(ctx, -3, -22, 2, 1, PAL.hair2);
98: 
99:   // weapon in hand when idle
100:   if (p.attackTimer <= 0) {
101:     if (p.weapon === "shotgun") {
102:       px(ctx, 4, -11, 9, 2, PAL.ink);
103:       px(ctx, 5, -11, 7, 1, PAL.steel2);
104:       px(ctx, 8, -10, 1, 2, PAL.rust);
105:       px(ctx, 12, -11, 2, 2, PAL.steel);
106:     } else if (p.weapon === "katana") {
107:       ctx.save();
108:       ctx.translate(5, -10);
109:       ctx.rotate(-0.35);
110:       px(ctx, 0, -1, 13, 2, PAL.ink);
111:       px(ctx, 1, -1, 11, 1, PAL.steel);
112:       px(ctx, 12, -1, 2, 1, PAL.white);
113:       px(ctx, -1, -2, 2, 3, PAL.gold2);
114:       ctx.restore();
115:     } else {
116:       // idle pull-cord
117:       px(ctx, 5, -11, 1, 4, PAL.rust);
118:       px(ctx, 5, -7, 2, 1, PAL.steel2);
119:     }
120:   }
121: 
122:   // attacks
123:   if (p.attackTimer > 0) {
124:     const prog = 1 - p.attackTimer / p.attackDur;
125:     drawAttack(ctx, p, prog, t);
126:   }
127: 
128:   ctx.restore();
129: 
130:   if (p.dashTimer > 0) {
131:     ctx.save();
132:     ctx.globalAlpha = 0.3;
133:     px(ctx, p.x + 2, p.y + 4, p.w - 4, p.h - 6, PAL.blood);
134:     ctx.restore();
135:   }
136: }
