138: function drawAttack(ctx, p, prog, t) {
139:   const swing = Math.sin(prog * Math.PI);
140:   if (p.weapon === "chainsaw") {
141:     // arm + motor
142:     px(ctx, 5, -14, 6, 4, "#17121f");
143:     px(ctx, 10, -15, 5, 6, PAL.rust);
144:     px(ctx, 11, -14, 3, 4, PAL.blood);
145:     px(ctx, 9, -16, 2, 2, PAL.steel2);
146:     // blade
147:     ctx.save();
148:     ctx.translate(15, -12);
149:     ctx.rotate(-0.25 + swing * 0.55);
150:     px(ctx, 0, -3, 23, 6, PAL.ink);
151:     px(ctx, 1, -2, 21, 4, PAL.steel);
152:     px(ctx, 2, -2, 19, 1, PAL.white);
153:     for (let i = 0; i < 7; i++) {
154:       const x = 2 + i * 3;
155:       ctx.fillStyle = PAL.steel;
156:       ctx.beginPath();
157:       ctx.moveTo(x, -3);
158:       ctx.lineTo(x + 2, -6);
159:       ctx.lineTo(x + 2, -3);
160:       ctx.fill();
161:     }
162:     ctx.fillStyle = PAL.blood;
163:     px(ctx, 4, 0, 13, 1, PAL.blood);
164:     ctx.restore();
165: 
166:     // motion arcs
167:     ctx.save();
168:     ctx.globalCompositeOperation = "lighter";
169:     ctx.globalAlpha = 0.55 * (1 - prog * 0.4);
170:     ctx.strokeStyle = PAL.blood2;
171:     ctx.lineWidth = 2;
172:     ctx.beginPath();
173:     ctx.arc(2, -12, 24 + p.attackIndex * 3, -1.0 + prog * 0.3, 0.75 + prog * 0.3);
174:     ctx.stroke();
175:     ctx.globalAlpha *= 0.8;
176:     ctx.strokeStyle = PAL.white;
177:     ctx.lineWidth = 1;
178:     ctx.beginPath();
179:     ctx.arc(2, -12, 20 + p.attackIndex * 3, -0.8, 0.55);
180:     ctx.stroke();
181:     ctx.restore();
182: 
183:     if (Math.random() < 0.5) {
184:       ctx.save();
185:       ctx.globalAlpha = 0.7;
186:       px(ctx, 24 + Math.random() * 9, -17 + Math.random() * 10, 1, 1, PAL.gold);
187:       ctx.restore();
188:     }
189:   } else if (p.weapon === "katana") {
190:     ctx.save();
191:     ctx.translate(4, -13);
192:     ctx.rotate(-1.15 + prog * 1.9);
193:     px(ctx, 0, -1, 28, 2, PAL.ink);
194:     px(ctx, 1, -1, 26, 1, PAL.steel);
195:     px(ctx, 24, -1, 3, 1, PAL.white);
196:     px(ctx, -2, -2, 3, 3, PAL.gold2);
197:     ctx.restore();
198:     ctx.save();
199:     ctx.globalCompositeOperation = "lighter";
200:     ctx.globalAlpha = 0.65 * (1 - prog * 0.5);
201:     ctx.strokeStyle = PAL.bone;
202:     ctx.lineWidth = 2;
203:     ctx.beginPath();
204:     ctx.arc(3, -12, 29, -1.0 + prog * 0.4, 0.7 + prog * 0.4);
205:     ctx.stroke();
206:     ctx.restore();
207:   } else if (p.weapon === "shotgun") {
208:     px(ctx, 4, -13, 13, 3, PAL.ink);
209:     px(ctx, 5, -13, 11, 1, PAL.steel2);
210:     px(ctx, 15, -13, 3, 3, PAL.steel);
211:     if (prog < 0.3) {
212:       ctx.save();
213:       ctx.globalCompositeOperation = "lighter";
214:       ctx.globalAlpha = 0.9 - prog * 2;
215:       px(ctx, 17, -15, 8, 7, PAL.gold);
216:       px(ctx, 20, -13, 7, 3, PAL.white);
217:       ctx.restore();
218:     }
219:   }
220: }
